import assert from "node:assert/strict";
import { operation, validate } from "./contract.mjs";

// Run on the app backend; the provider still authenticates the store evidence.
export function toVerifyPurchaseInput(purchase, context = {}) {
  const { store, purchaseToken } = purchase ?? {};
  let input;
  const required = (value) => {
    if (typeof value !== "string" || !value.trim())
      throw new Error("Purchase evidence is required");
    return value;
  };
  switch (store) {
    case "apple":
      input = { store, apple: { jws: required(purchaseToken) } };
      break;
    case "google":
      input = { store, google: { purchaseToken: required(purchaseToken) } };
      break;
    case "amazon":
      input = {
        store,
        amazon: {
          userId: required(context.storeUserId),
          receiptId: required(purchaseToken),
          ...(context.amazonSandbox === true ? { sandbox: true } : {}),
        },
      };
      break;
    case "horizon":
      input = {
        store,
        horizon: {
          userId: required(context.storeUserId),
          sku: required(purchase.productId),
        },
      };
      break;
    default:
      throw new Error("Unsupported purchase store");
  }
  if (!validate(operation("verifyPurchase").input, input))
    throw new Error("Purchase evidence does not match the protocol input");
  return input;
}

export function runBridgeDemo() {
  const checks = [];
  for (const store of ["apple", "google"]) {
    const token = `fictional-${store}-evidence`;
    const input = toVerifyPurchaseInput({
      store,
      purchaseToken: token,
      productId: "premium.monthly",
      userId: "untrusted-client-claim",
    });
    assert.deepEqual(input, {
      store,
      ...(store === "apple"
        ? { apple: { jws: token } }
        : { google: { purchaseToken: token } }),
    });
    checks.push(`${store}: maps evidence without forwarding client identity`);
    assert(validate(operation("verifyPurchase").input, input));
    checks.push(`${store}: matches the installed verification input schema`);
  }
  for (const store of ["amazon", "horizon"]) {
    const input = toVerifyPurchaseInput(
      {
        store,
        purchaseToken: "receipt-1",
        productId: "premium.monthly",
        userId: "untrusted-app-user",
      },
      { storeUserId: "authenticated-store-user", amazonSandbox: true },
    );
    assert.deepEqual(
      input,
      store === "amazon"
        ? {
            store,
            amazon: {
              userId: "authenticated-store-user",
              receiptId: "receipt-1",
              sandbox: true,
            },
          }
        : {
            store,
            horizon: {
              userId: "authenticated-store-user",
              sku: "premium.monthly",
            },
          },
    );
    checks.push(
      `${store}: uses server-selected store identity, distinct from the app user`,
    );
    assert(validate(operation("verifyPurchase").input, input));
    checks.push(`${store}: matches the installed verification input schema`);
  }
  for (const [label, purchase] of [
    ["missing purchase", null],
    ["unknown store", { store: "unknown", purchaseToken: "fictional" }],
    [
      "Amazon requires its authenticated store user",
      { store: "amazon", purchaseToken: "fictional" },
    ],
    [
      "Horizon requires its authenticated store user",
      { store: "horizon", purchaseToken: "fictional" },
    ],
    ["missing evidence", { store: "apple" }],
    ["blank evidence", { store: "google", purchaseToken: " " }],
    ["non-string evidence", { store: "apple", purchaseToken: 123 }],
    [
      "oversized evidence",
      { store: "apple", purchaseToken: "x".repeat(16385) },
    ],
  ]) {
    assert.throws(() => toVerifyPurchaseInput(purchase), Error);
    checks.push(`Rejects ${label}`);
  }
  return checks;
}

if (import.meta.main)
  console.log(
    `Client boundary: ${runBridgeDemo().length} checks passed against the installed contract. Fixture fields only; no SDK checkout or store contacted.`,
  );

example/provider.mjs:
import { Database } from "bun:sqlite";
import { createHash, randomUUID } from "node:crypto";
import {
  providerCapabilitiesSchema,
  COMMERCE_EVENT_VERSION,
  HTTP_BINDING,
} from "openiap-commerce-protocol";
import { protocolError, validate } from "./contract.mjs";
import { createErasureLedger } from "./erasure.mjs";

export const FIXTURE = Object.freeze({
  store: "fixture",
  evidence: "local-purchase-alice",
  userId: "demo_alice",
  productId: "premium.monthly",
  startsAt: Date.UTC(2026, 8, 7, 9),
  expiresAt: Date.UTC(2026, 9, 7, 9),
});
export const CREDENTIALS = Object.freeze({
  verification: "Bearer local-demo-verification",
  server: "Bearer local-demo-server",
});
const fingerprint = (value) => createHash("sha256").update(value).digest("hex");

export function isEntitled(state, expiresAt, now) {
  return (
    (state === "Active" || state === "InGracePeriod") &&
    (expiresAt == null || now < expiresAt)
  );
}

// This adapter recognizes one fictional purchase; it never contacts a store.
function fixtureEvidence(input) {
  switch (input.store) {
    case "apple":
      return input.apple?.jws;
    case "google":
      return input.google?.purchaseToken;
    case "amazon":
      return (
        input.amazon &&
        JSON.stringify([
          input.amazon.userId,
          input.amazon.receiptId,
          input.amazon.sandbox === true,
        ])
      );
    case "horizon":
      return (
        input.horizon &&
        JSON.stringify([input.horizon.userId, input.horizon.sku])
      );
    default:
      return input.evidence;
  }
}

function verifyFixture(input, fixture) {
  if (input.store !== fixture.store) return { error: "UNSUPPORTED_STORE" };
  const evidence = fixtureEvidence(input);
  if (typeof evidence !== "string") return { error: "INVALID_REQUEST" };
  if (evidence === "local-upstream-outage") {
    return { error: "VERIFICATION_FAILED" };
  }
  const current = fixture.currentVerdict?.();
  if (current === "outage") return { error: "VERIFICATION_FAILED" };
  return { accepted: evidence === fixture.evidence && current !== false };
}

export function createProvider(path, now, fixture = FIXTURE) {
  const db = new Database(path, { create: true });
  db.exec(`
    PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS purchases (
      fingerprint TEXT PRIMARY KEY, user_id TEXT, product_id TEXT NOT NULL,
      state TEXT NOT NULL, expires_at INTEGER NOT NULL, will_renew INTEGER NOT NULL,
      observed_at INTEGER NOT NULL, entitlement_granted INTEGER NOT NULL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS outbox (
      event_id TEXT PRIMARY KEY, delivery_id TEXT NOT NULL, body TEXT NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending',
      next_at INTEGER NOT NULL DEFAULT 0
    );
  `);
  const erasures = createErasureLedger(db);
  if (
    !db
      .query("PRAGMA table_info(purchases)")
      .all()
      .some((column) => column.name === "erased")
  )
    db.exec(
      "ALTER TABLE purchases ADD COLUMN erased INTEGER NOT NULL DEFAULT 0",
    );

  function snapshot(row) {
    return {
      productId: row.product_id,
      state: row.state,
      active: isEntitled(row.state, row.expires_at, now()),
      store: fixture.store,
      expiresAt: row.expires_at,
      willRenew: Boolean(row.will_renew),
    };
  }

  function rowsFor(userId) {
    return db.query("SELECT * FROM purchases WHERE user_id = ?").all(userId);
  }

  function entitlements(userId) {
    if (fixture.pointInTime) {
      const current = fixture.currentVerdict?.();
      if (current === "outage") return { error: "VERIFICATION_FAILED" };
      return {
        userId,
        productIds:
          current === false
            ? []
            : [...new Set(rowsFor(userId).map((row) => row.product_id))],
        subscriptions: [],
      };
    }
    const subscriptions = rowsFor(userId)
      .map(snapshot)
      .filter((row) => row.active);
    return {
      userId,
      productIds: [...new Set(subscriptions.map((row) => row.productId))],
      subscriptions,
    };
  }

  const eventTypes = [
    "entitlement.granted",
    "subscription.canceled",
    "subscription.expired",
    "entitlement.revoked",
  ];
  const capabilityNames = Object.keys(
    providerCapabilitiesSchema.$defs.StoreCapabilities.properties,
  );
  const supported = new Set([
    "initialValidation",
    "subscriptions",
    "entitlements",
    "serverNotifications",
    "expiration",
  ]);
  const capabilities = {
    specVersion: HTTP_BINDING.protocolVersion,
    implementation: {
      name: "Commerce Protocol Example — fictional fixture store",
    },
    eventTypes,
    stores: {
      [fixture.store]: Object.fromEntries(
        capabilityNames.map((key) => [
          key,
          {
            provider:
              supported.has(key) &&
              (!fixture.pointInTime ||
                ["initialValidation", "entitlements"].includes(key)),
            implementation:
              supported.has(key) &&
              (!fixture.pointInTime ||
                ["initialValidation", "entitlements"].includes(key)),
            notes:
              "Local fixture demonstration only; no real store integration or profile conformance claim.",
          },
        ]),
      ),
    },
  };

  function enqueue(eventType, row, occurredAt, sourceStoreEventId) {
    const body = {
      eventId: randomUUID(),
      eventType,
      eventVersion: COMMERCE_EVENT_VERSION,
      occurredAt,
      processedAt: now(),
      store: fixture.store,
      environment: "local-fixture",
      projectId: "commerce_example",
      productId: row.product_id,
      ...(row.user_id ? { userId: row.user_id } : {}),
      subscription: snapshot(row),
      ...(sourceStoreEventId ? { sourceStoreEventId } : {}),
    };
    if (!validate("#/$defs/CommerceEvent", body))
      throw new Error("Invalid event");
    db.query(
      "INSERT INTO outbox (event_id, delivery_id, body) VALUES (?, ?, ?)",
    ).run(body.eventId, randomUUID(), JSON.stringify(body));
  }

  const handlers = {
    providerCapabilities: () => capabilities,
    verifyPurchase(input) {
      const verdict = verifyFixture(input, fixture);
      if (verdict.error) return verdict;
      if (verdict.accepted) {
        db.query(
          `INSERT OR IGNORE INTO purchases (fingerprint, user_id, product_id, state, expires_at, will_renew, observed_at) VALUES (?, NULL, ?, 'Active', ?, 1, ?)`,
        ).run(
          fingerprint(fixtureEvidence(input)),
          fixture.productId,
          fixture.expiresAt,
          fixture.startsAt,
        );
      }
      const expired = !fixture.pointInTime && now() >= fixture.expiresAt;
      return {
        store: fixture.store,
        isValid: verdict.accepted && !expired,
        state: !verdict.accepted
          ? "INAUTHENTIC"
          : expired
            ? "EXPIRED"
            : "ENTITLED",
        ...(verdict.accepted ? { productId: fixture.productId } : {}),
        environment: "local-fixture",
      };
    },
    bindPurchase(input) {
      if (input.store !== fixture.store) return { error: "UNSUPPORTED_STORE" };
      if (typeof fixtureEvidence(input) !== "string")
        return { error: "INVALID_REQUEST" };
      return db.transaction(() => {
        if (erasures.has(input.userId)) return { bound: false };
        const key = fingerprint(fixtureEvidence(input));
        const updated = db
          .query(
            "UPDATE purchases SET user_id = ? WHERE fingerprint = ? AND user_id IS NULL AND erased = 0",
          )
          .run(input.userId, key);
        const row = db
          .query("SELECT * FROM purchases WHERE fingerprint = ?")
          .get(key);
        if (
          updated.changes &&
          !fixture.pointInTime &&
          isEntitled(row.state, row.expires_at, now())
        ) {
          enqueue("entitlement.granted", row, row.observed_at);
          db.query(
            "UPDATE purchases SET entitlement_granted = 1 WHERE fingerprint = ?",
          ).run(key);
        }
        return { bound: row?.user_id === input.userId };
      })();
    },
    entitlements: (input) => entitlements(input.userId),
    eraseUser(input) {
      return db.transaction(() => {
        const jobId = erasures.remember(input.userId);
        db.query(
          "UPDATE purchases SET user_id = NULL, erased = 1, entitlement_granted = 0 WHERE user_id = ?",
        ).run(input.userId);
        // A claimed delivery may already be in flight; the receiver erases its own copy.
        db.query(
          "DELETE FROM outbox WHERE json_extract(body, '$.userId') = ?",
        ).run(input.userId);
        return { accepted: true, jobId, status: "completed" };
      })();
    },
    subscriptionStatus(input) {
      if (fixture.pointInTime) return { active: false };
      const snapshots = rowsFor(input.userId).map(snapshot);
      const subscription = snapshots.find((row) => row.active) ?? snapshots[0];
      return {
        active: snapshots.some((row) => row.active),
        ...(subscription ? { subscription } : {}),
      };
    },
  };

  async function fetch(request) {
    const url = new URL(request.url);
    const spec = HTTP_BINDING.operations.find(
      (entry) => entry.path === url.pathname && entry.method === request.method,
    );
    if (!spec) return protocolError("NOT_FOUND");
    const auth = request.headers.get("authorization");
    if (spec.auth !== "none") {
      if (!Object.values(CREDENTIALS).includes(auth))
        return protocolError("UNAUTHORIZED");
      if (spec.auth === "server" && auth !== CREDENTIALS.server)
        return protocolError("FORBIDDEN");
    }
    if (!handlers[spec.name]) return protocolError("UNSUPPORTED_PROFILE");
    let input = null;
    if (spec.input) {
      try {
        input =
          request.method === "GET"
            ? Object.fromEntries(url.searchParams)
            : await request.json();
      } catch {
        return protocolError("INVALID_REQUEST");
      }
      if (!validate(spec.input, input)) return protocolError("INVALID_REQUEST");
    }
    try {
      const result = handlers[spec.name](input);
      if (result.error) return protocolError(result.error);
      if (!validate(spec.result, result))
        throw new Error("Invalid protocol response");
      return Response.json(result, { status: spec.successStatus });
    } catch {
      return protocolError("INTERNAL_ERROR");
    }
  }

  function observe({ id, kind, occurredAt }) {
    if (
      !["cancel", "expire"].includes(kind) ||
      !Number.isSafeInteger(occurredAt) ||
      occurredAt > now()
    ) {
      throw new Error("Invalid fixture observation");
    }
    return db.transaction(() => {
      if (db.query("SELECT id FROM observations WHERE id = ?").get(id))
        return false;
      const row = db
        .query("SELECT * FROM purchases WHERE fingerprint = ?")
        .get(fingerprint(fixture.evidence));
      if (!row) throw new Error("Verify the fixture purchase first");
      if (kind === "expire" && occurredAt < row.expires_at) {
        throw new Error("Premature expiry requires store reconciliation");
      }
      db.query("INSERT INTO observations VALUES (?)").run(id);
      if (occurredAt < row.observed_at) return false;
      if (
        (kind === "cancel" && (!row.will_renew || row.state !== "Active")) ||
        (kind === "expire" && row.state === "Expired")
      )
        return false;
      const next = {
        ...row,
        will_renew: 0,
        state: kind === "expire" ? "Expired" : row.state,
      };
      db.query(
        "UPDATE purchases SET state = ?, will_renew = 0, observed_at = ? WHERE fingerprint = ?",
      ).run(next.state, occurredAt, row.fingerprint);
      const types = [
        kind === "cancel" ? "subscription.canceled" : "subscription.expired",
      ];
      if (
        row.entitlement_granted &&
        !isEntitled(next.state, next.expires_at, now())
      ) {
        types.push("entitlement.revoked");
        db.query(
          "UPDATE purchases SET entitlement_granted = 0 WHERE fingerprint = ?",
        ).run(row.fingerprint);
      }
      for (const eventType of types) enqueue(eventType, next, occurredAt, id);
      return true;
    })();
  }

  function inspect() {
    return {
      purchases: db
        .query(
          "SELECT user_id AS userId, product_id AS productId, state, will_renew AS willRenew FROM purchases",
        )
        .all(),
      access: entitlements(fixture.userId),
      deliveries: db
        .query(
          "SELECT event_id AS eventId, delivery_id AS deliveryId, attempts, status, body FROM outbox ORDER BY rowid",
        )
        .all()
        .map(({ body, ...row }) => ({
          ...row,
          eventType: JSON.parse(body).eventType,
        })),
    };
  }

  return { db, fetch, observe, inspect, close: () => db.close() };
}

example/scenario.mjs:
import assert from "node:assert/strict";
import { operation, validate } from "./contract.mjs";
import { CREDENTIALS, FIXTURE } from "./provider.mjs";
import { deliver } from "./webhooks.mjs";

export const STAGES = [
  {
    title: "Start with the contract",
    built: "HTTP routes + schema validation + SQLite",
    result: "A running server, an empty purchase table, and no access.",
  },
  {
    title: "Verify a purchase",
    built: "Fixture store adapter + purchase persistence",
    result: "Valid evidence is saved. Alice still has no access.",
  },
  {
    title: "Connect it to a user",
    built: "Server authorization + atomic binding + entitlement reads",
    result: "Alice gets Premium. Another user cannot take the purchase.",
  },
  {
    title: "Handle cancellation",
    built: "Lifecycle processing + transactional event outbox",
    result: "Renewal stops. Alice keeps the time she already paid for.",
  },
  {
    title: "Deliver, retry, deduplicate",
    built: "HMAC signatures + retry worker + durable receiver inbox",
    result:
      "A 503 retries successfully. Redelivery creates no second inbox row.",
  },
  {
    title: "Expire access and restart",
    built: "Expiry-aware reads + recovery from SQLite",
    result:
      "Access closes at the deadline. Restarting preserves purchases and deliveries.",
  },
  {
    title: "Delete the account",
    built: "Idempotent erasure + receiver cleanup + durable deletion guard",
    result:
      "Alice is removed from purchases and event copies. Late deliveries cannot restore her account data.",
  },
];

export async function requestOperation(baseUrl, name, input, role = "server") {
  const spec = operation(name);
  const url = new URL(spec.path, baseUrl);
  if (spec.method === "GET" && input)
    for (const [key, value] of Object.entries(input))
      url.searchParams.set(key, value);
  const response = await fetch(url, {
    method: spec.method,
    headers: {
      "content-type": "application/json",
      ...(role ? { authorization: CREDENTIALS[role] } : {}),
    },
    ...(spec.method === "POST" ? { body: JSON.stringify(input) } : {}),
  });
  return {
    operation: name,
    httpStatus: response.status,
    body: await response.json(),
  };
}

export function createScenario(runtime) {
  const history = [];
  const checks = [];
  const evidence = { store: FIXTURE.store, evidence: FIXTURE.evidence };
  const call = (name, input, role) =>
    requestOperation(runtime.baseUrl, name, input, role);
  const check = (label, actual, expected) => {
    assert.deepEqual(actual, expected, label);
    checks.push(label);
  };

  async function advance() {
    const stage = history.length;
    if (stage >= STAGES.length) return history.at(-1);
    const responses = [];
    const run = async (name, input, role) => {
      const result = await call(name, input, role);
      responses.push(result);
      return result;
    };
    const start = checks.length;
    if (stage === 0) {
      check(
        "Fixture request matches the installed schema",
        validate(operation("verifyPurchase").input, evidence),
        true,
      );
      check(
        "Capabilities use the published response schema",
        (await run("providerCapabilities", null, null)).httpStatus,
        200,
      );
      check(
        "Purchase storage starts empty",
        runtime.provider.inspect().purchases,
        [],
      );
      check(
        "No profile conformance is claimed",
        (await run("providerCapabilities", null, null)).body.profiles,
        undefined,
      );
    } else if (stage === 1) {
      check(
        "Fixture evidence is accepted",
        (await run("verifyPurchase", evidence, "verification")).body.isValid,
        true,
      );
      check(
        "Verification does not grant access",
        (await run("entitlements", { userId: FIXTURE.userId })).body.productIds,
        [],
      );
      check(
        "Invalid evidence produces a negative verdict",
        (
          await run(
            "verifyPurchase",
            { store: FIXTURE.store, evidence: "invalid" },
            "verification",
          )
        ).body.isValid,
        false,
      );
      check(
        "An upstream outage is not a negative verdict",
        (
          await run(
            "verifyPurchase",
            { store: FIXTURE.store, evidence: "local-upstream-outage" },
            "verification",
          )
        ).body.error.code,
        "VERIFICATION_FAILED",
      );
    } else if (stage === 2) {
      check(
        "Verification credentials cannot bind a user",
        (
          await run(
            "bindPurchase",
            { ...evidence, userId: FIXTURE.userId },
            "verification",
          )
        ).body.error.code,
        "FORBIDDEN",
      );
      check(
        "The server binds Alice",
        (await run("bindPurchase", { ...evidence, userId: FIXTURE.userId }))
          .body.bound,
        true,
      );
      check(
        "Repeating the same binding succeeds",
        (await run("bindPurchase", { ...evidence, userId: FIXTURE.userId }))
          .body.bound,
        true,
      );
      check(
        "Bob cannot take Alice's purchase",
        (await run("bindPurchase", { ...evidence, userId: "demo_bob" })).body
          .bound,
        false,
      );
      check(
        "Alice can access Premium",
        (await run("entitlements", { userId: FIXTURE.userId })).body.productIds,
        [FIXTURE.productId],
      );
      check(
        "First binding queues one grant; repeat and conflict queue none",
        runtime.provider.inspect().deliveries.map((row) => row.eventType),
        ["entitlement.granted"],
      );
    } else if (stage === 3) {
      runtime.time = FIXTURE.startsAt + 86_400_000;
      runtime.provider.observe({
        id: "fixture-cancel",
        kind: "cancel",
        occurredAt: runtime.time,
      });
      const result = await run("subscriptionStatus", {
        userId: FIXTURE.userId,
      });
      check("Cancellation keeps paid access", result.body.active, true);
      check(
        "Cancellation stops renewal",
        result.body.subscription.willRenew,
        false,
      );
      check(
        "Cancellation queues one event",
        runtime.provider
          .inspect()
          .deliveries.filter((row) => row.eventType === "subscription.canceled")
          .length,
        1,
      );
    } else if (stage === 4) {
      const failed = await deliver(
        runtime.provider,
        runtime.secret,
        runtime.now,
        async () => new Response(null, { status: 503 }),
      );
      responses.push({
        operation: "webhook: receiver unavailable",
        body: failed,
      });
      check("A 503 leaves a durable retry", failed[0].status, "pending");
      runtime.restart();
      runtime.time += 30_000;
      const delivered = await deliver(
        runtime.provider,
        runtime.secret,
        runtime.now,
        runtime.post,
      );
      responses.push({
        operation: "webhook: retry after restart",
        body: delivered,
      });
      check("Retry survives provider restart", delivered[0].httpStatus, 200);
      check(
        "Retry keeps the delivery identity",
        delivered[0].deliveryId,
        failed[0].deliveryId,
      );
      // Simulate loss of the delivery acknowledgement after the receiver committed.
      runtime.provider.db
        .query("UPDATE outbox SET status = 'pending', next_at = 0")
        .run();
      runtime.time += 1_000;
      responses.push({
        operation: "webhook: lost-ack redelivery",
        body: await deliver(
          runtime.provider,
          runtime.secret,
          runtime.now,
          runtime.post,
        ),
      });
      check(
        "Redelivery has one inbox row per event",
        runtime.receiver.count(),
        2,
      );
    } else if (stage === 5) {
      runtime.time = FIXTURE.expiresAt;
      check(
        "Access closes at expiry before a notification arrives",
        (await run("entitlements", { userId: FIXTURE.userId })).body.productIds,
        [],
      );
      const observation = {
        id: "fixture-expire",
        kind: "expire",
        occurredAt: runtime.time,
      };
      runtime.provider.observe(observation);
      check(
        "Duplicate store notification emits no extra event",
        runtime.provider.observe(observation),
        false,
      );
      const before = runtime.provider.inspect();
      runtime.restart();
      check(
        "Reopening both databases preserves state",
        runtime.provider.inspect(),
        before,
      );
      check(
        "Receiver deduplication survives restart",
        runtime.receiver.count(),
        2,
      );
      responses.push({
        operation: "webhook: expiry + revocation",
        body: await deliver(
          runtime.provider,
          runtime.secret,
          runtime.now,
          runtime.post,
        ),
      });
      check("All four events reach the receiver", runtime.receiver.count(), 4);
      check(
        "The final status is inactive",
        (await run("subscriptionStatus", { userId: FIXTURE.userId })).body
          .active,
        false,
      );
    } else if (stage === 6) {
      check(
        "Verification credentials cannot erase users",
        (await run("eraseUser", { userId: FIXTURE.userId }, "verification"))
          .httpStatus,
        403,
      );
      // The app removes its event copies before requesting provider erasure.
      runtime.receiver.eraseUser(FIXTURE.userId);
      const erased = await run("eraseUser", { userId: FIXTURE.userId });
      check(
        "Provider erasure completes",
        [erased.body.accepted, erased.body.status],
        [true, "completed"],
      );
      runtime.restart();
      check(
        "Erasure retry after restart returns the same job",
        (await run("eraseUser", { userId: FIXTURE.userId })).body,
        erased.body,
      );
      check(
        "Purchase has no account identity",
        runtime.provider.inspect().purchases.map((row) => row.userId),
        [null],
      );
      check("App event copies are erased", runtime.receiver.count(), 0);
      check(
        "Erased account has no access",
        (await run("entitlements", { userId: FIXTURE.userId })).body.productIds,
        [],
      );
      check(
        "A stale binding retry cannot restore identity",
        (await run("bindPurchase", { ...evidence, userId: FIXTURE.userId }))
          .body.bound,
        false,
      );
    }
    const entry = {
      step: stage + 1,
      ...STAGES[stage],
      simulatedTime: new Date(runtime.time).toISOString(),
      ...runtime.provider.inspect(),
      inboxCount: runtime.receiver.count(),
      responses,
      checks: checks.slice(start),
      totalChecks: checks.length,
    };
    history.push(entry);
    return entry;
  }

  return { advance, history };
}

