}

function post(
  app: Hono,
  path: string,
  body: unknown,
  key: string | null = SERVER_KEY,
) {
  return app.request(path, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(key ? { Authorization: `Bearer ${key}` } : {}),
    },
    body: JSON.stringify(body),
  });
}

