import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { HarmonizedPurchaseState } from "../purchases/purchaseState";
import { hmacSha256Hex } from "../utils/sha256";
import {
  applySubscriptionEventHandler,
  bindSubscriptionToUserHandler,
  rebindSubscriptionToUserHandler,
  drainSubscriptionUserErasurePage,
  buildVerifiedSubscriptionSnapshot,
  getCurrentProductIdByTokenHandler,
  getSourceProductIdByTokenHandler,
  mergeVerifiedSubscriptionSnapshot,
  recordVerifiedSubscriptionHandler,
} from "./internal";

type Row = Record<string, unknown> & { _id: string; _creationTime: number };

class MemQuery {
  constructor(private rows: Row[]) {}

  withIndex(_name: string, cb?: (q: IndexBuilder) => IndexBuilder): MemQuery {
    if (!cb) return this;
    const builder = new IndexBuilder();
    cb(builder);
    return new MemQuery(
      this.rows.filter((row) =>
        builder.predicates.every((predicate) => predicate(row)),
      ),
    );
  }

  async unique(): Promise<Row | null> {
    if (this.rows.length > 1) {
      throw new Error("unique() called on a query that returned > 1 row");
    }
    return this.rows[0] ?? null;
  }

  async collect(): Promise<Row[]> {
    return [...this.rows];
  }

  async take(count: number): Promise<Row[]> {
    return this.rows.slice(0, count);
  }
}

class IndexBuilder {
  predicates: Array<(row: Row) => boolean> = [];

  eq(field: string, value: unknown): IndexBuilder {
    this.predicates.push((row) => row[field] === value);
    return this;
  }
}

class MemDb {
  tables = new Map<string, Map<string, Row>>();
  private counter = 0;

  constructor() {
    this.table("organizations").set("organizations_seed_1", {
      _id: "organizations_seed_1",
      _creationTime: Date.now(),
    });
    this.table("projects").set("projects_seed_1", {
      _id: "projects_seed_1",
      _creationTime: Date.now(),
      organizationId: "organizations_seed_1",
    });
  }

  private table(name: string): Map<string, Row> {
    let table = this.tables.get(name);
    if (!table) {
      table = new Map();
      this.tables.set(name, table);
    }
    return table;
  }

  query(tableName: string): MemQuery {
    return new MemQuery([...this.table(tableName).values()]);
  }

  async insert(
    tableName: string,
    doc: Record<string, unknown>,
  ): Promise<string> {
    const id = `${tableName}_${++this.counter}`;
    this.table(tableName).set(id, {
      ...doc,
      _id: id,
      _creationTime: Date.now() + this.counter / 1_000,
    });
    return id;
  }

  async get(id: string): Promise<Row | null> {
    for (const table of this.tables.values()) {
      const row = table.get(id);
      if (row) return row;
    }
    return null;
  }

  async patch(id: string, patch: Record<string, unknown>): Promise<void> {
    for (const table of this.tables.values()) {
      const row = table.get(id);
      if (row) {
        Object.assign(row, patch);
        return;
      }
    }
    throw new Error(`patch: no doc with id ${id}`);
  }

  async delete(id: string): Promise<void> {
    for (const table of this.tables.values()) {
      if (table.delete(id)) return;
    }
  }

  rows(tableName: string): Row[] {
    return [...this.table(tableName).values()];
  }

  seedProduct(doc: {
    projectId: string;
    platform: "IOS" | "Android";
    productId: string;
    billingPeriod?: string;
  }): void {
    this.table("products").set(`products_${++this.counter}`, {
      _id: `products_${this.counter}`,
      _creationTime: Date.now(),
      ...doc,
    });
  }
}

function makeCtx(db: MemDb) {
  return { db } as unknown as Parameters<
    typeof recordVerifiedSubscriptionHandler
  >[0];
}

const PROJECT_ID = "projects_seed_1";
const TOKEN = "purchase_token_1";

describe("entitlement events across the expiry deadline", () => {
  it.each([false, true])(
    "revokes once when the clock expires before notifications (cancel first: %s)",
    async (cancelFirst) => {
      vi.useFakeTimers();
      try {
        vi.setSystemTime(1_000);
        const db = new MemDb();
        const started = await seedWebhookEvent(db, {
          type: "SubscriptionStarted",
          notificationId: "clock-start",
          occurredAt: 1_000,
        });
        await db.patch(started, { expiresAt: 2_000, renewsAt: 2_000 });
        await applySubscriptionEventHandler(makeCtx(db), {
          projectId: PROJECT_ID as never,
          eventId: started as never,
        });
        await bindSubscriptionToUserHandler(makeCtx(db), {
          projectId: PROJECT_ID as never,
          purchaseToken: TOKEN,
          userId: "clock-user",
        });
        vi.setSystemTime(3_000);
        if (cancelFirst) {
          const canceled = await seedWebhookEvent(db, {
            type: "SubscriptionStarted",
            notificationId: "clock-cancel",
            occurredAt: 2_500,
          });
          await db.patch(canceled, {
            type: "SubscriptionCanceled",
            expiresAt: 2_000,
            renewsAt: undefined,
            willRenew: false,
          });
          await applySubscriptionEventHandler(makeCtx(db), {
            projectId: PROJECT_ID as never,
            eventId: canceled as never,
          });
        }
        const expired = await seedWebhookEvent(db, {
          type: "SubscriptionExpired",
          notificationId: "clock-expire",
          occurredAt: 3_000,
        });
        await db.patch(expired, { expiresAt: 2_000 });
        const args = {
          projectId: PROJECT_ID as never,
          eventId: expired as never,
        };
        await applySubscriptionEventHandler(makeCtx(db), args);
        await applySubscriptionEventHandler(makeCtx(db), args);
        expect(
          db
            .rows("commerceEvents")
            .filter((row) => String(row.eventType).startsWith("entitlement."))
            .map((row) => row.eventType),
        ).toEqual(["entitlement.granted", "entitlement.revoked"]);
      } finally {
        vi.useRealTimers();
      }
    },
  );
});

async function seedWebhookEvent(
  db: MemDb,
  args: {
    type:
      | "SubscriptionStarted"
      | "SubscriptionRenewed"
      | "SubscriptionExpired"
      | "SubscriptionProductChanged";
    notificationId: string;
    occurredAt: number;
    platform?: "IOS" | "Android";
    productId?: string;
  },
): Promise<string> {
  const platform = args.platform ?? "Android";
  return await db.insert("webhookEvents", {
    projectId: PROJECT_ID,
    type: args.type,
    source:
      platform === "IOS"
        ? "AppleAppStoreServerNotificationsV2"
        : "GooglePlayRealTimeDeveloperNotifications",
    platform,
    environment: "Sandbox",
    purchaseToken: TOKEN,
    sourceNotificationId: args.notificationId,
    productId: args.productId ?? "premium_monthly",
    subscriptionState:
      args.type === "SubscriptionExpired" ? "Expired" : "Active",
    expiresAt: 1_800_000_000_000,
    renewsAt: 1_800_000_000_000,
    currency: "USD",
    priceAmountMicros: 9_990_000,
    occurredAt: args.occurredAt,
    receivedAt: args.occurredAt,
  });
}

describe("subscription erasure across replacement tokens", () => {
  it.each([false, true])(
    "reconciles a granted successor without restoring erased identities (successor erasure requested: %s)",
    async (successorErased) => {
      const db = new MemDb();
      const ctx = makeCtx(db);
      const hashKey = "erasure-test-key";
      await db.patch(PROJECT_ID, { userErasureHashKey: hashKey });
      async function erasureJob(userId: string): Promise<string> {
        return db.insert("subscriptionUserErasureJobs", {
          projectId: PROJECT_ID,
          userId,
          userIdHash: await hmacSha256Hex(hashKey, userId),
          status: "queued",
          subscriptionsErased: 0,
          commerceEventsErased: 0,
        });
      }
      await recordVerifiedSubscriptionHandler(ctx, {
        projectId: PROJECT_ID as never,
        platform: "Android",
        purchaseToken: TOKEN,
        productId: "premium_monthly",
        purchaseState: "ENTITLED",
      });
      await bindSubscriptionToUserHandler(ctx, {
        projectId: PROJECT_ID as never,
        purchaseToken: TOKEN,
        userId: "erased-owner",
      });
      await drainSubscriptionUserErasurePage(
        ctx,
        (await erasureJob("erased-owner")) as never,
      );
      const startedId = await seedWebhookEvent(db, {
        type: "SubscriptionStarted",
        notificationId: "successor-granted",
        occurredAt: 1_000,
      });
      await db.patch(startedId, {
        purchaseToken: "replacement",
        expiresAt: Date.now() + 60_000,
      });
      await applySubscriptionEventHandler(ctx, {
        projectId: PROJECT_ID as never,
        eventId: startedId as never,
      });
      await bindSubscriptionToUserHandler(ctx, {
        projectId: PROJECT_ID as never,
        purchaseToken: "replacement",
        userId: "successor-owner",
      });
      const grant = db
        .rows("commerceEvents")
        .find((event) => event.eventType === "entitlement.granted");
      expect(grant?.userId).toBe("successor-owner");

      const successorErasureJob = successorErased
        ? await erasureJob("successor-owner")
        : undefined;
      // A destination exists so an emitted revocation would be delivered;
      // none is, which is the point of the assertions below.
      await db.insert("outboundDestinations", {
        projectId: PROJECT_ID,
        enabled: true,
        eventTypes: ["entitlement.revoked"],
      });
      const linkedId = await seedWebhookEvent(db, {
        type: "SubscriptionProductChanged",
        notificationId: "late-erased-link",
        occurredAt: 2_000,
      });
      await db.patch(linkedId, {
        purchaseToken: "replacement",
        linkedPurchaseToken: TOKEN,
      });
      const args = {
        projectId: PROJECT_ID as never,
        eventId: linkedId as never,
      };
      await applySubscriptionEventHandler(ctx, args);
      await applySubscriptionEventHandler(ctx, args);

      // The erased owner was unlinked, not the subscription. The successor
      // bound the replacement token afterwards, so that live association
      // survives the merge and nothing is revoked.
      expect(db.rows("subscriptions")).toHaveLength(1);
      expect(db.rows("subscriptions")[0].accountErased).toBeUndefined();
      expect(db.rows("subscriptions")[0].userId).toBe("successor-owner");
      expect(
        db
          .rows("commerceEvents")
          .filter((event) => event.eventType === "entitlement.revoked"),
      ).toEqual([]);
      expect(db.rows("outboundDeliveries")).toEqual([]);
      if (successorErased) {
        await drainSubscriptionUserErasurePage(
          ctx,
          successorErasureJob as never,
        );
        expect(
          db.rows("commerceEvents").some((event) => event.userId !== undefined),
        ).toBe(false);
      }
      expect(
        JSON.stringify(
          [...db.tables.values()].map((rows) => [...rows.values()]),
        ),
      ).not.toContain("erased-owner");
    },
  );

  it.each([
    { erasedToken: TOKEN, successorExists: false, boundToken: undefined },
    { erasedToken: TOKEN, successorExists: true, boundToken: undefined },
    { erasedToken: TOKEN, successorExists: true, boundToken: "replacement" },
    { erasedToken: "replacement", successorExists: true, boundToken: TOKEN },
  ])(
    "merges an erased record without dropping a live binding: %j",
    async (testCase) => {
      const db = new MemDb();
      const ctx = makeCtx(db);
      for (const purchaseToken of testCase.successorExists
        ? [TOKEN, "replacement"]
        : [TOKEN]) {
        const id = await recordVerifiedSubscriptionHandler(ctx, {
          projectId: PROJECT_ID as never,
          platform: "Android",
          purchaseToken,
          productId: "premium_monthly",
          purchaseState: "ENTITLED",
          subscriptionState: "SUBSCRIPTION_STATE_ACTIVE",
        });
        if (purchaseToken === testCase.erasedToken)
          await db.patch(id!, { accountErased: true });
        if (purchaseToken === testCase.boundToken)
          await bindSubscriptionToUserHandler(ctx, {
            projectId: PROJECT_ID as never,
            purchaseToken,
            userId: "linked-owner",
          });
      }
      const eventId = await seedWebhookEvent(db, {
        type: "SubscriptionStarted",
        notificationId: "erased-replacement",
        occurredAt: Date.now(),
      });
      await db.patch(eventId, {
        purchaseToken: "replacement",
        linkedPurchaseToken: TOKEN,
      });
      await applySubscriptionEventHandler(ctx, {
        projectId: PROJECT_ID as never,
        eventId: eventId as never,
      });

      expect(db.rows("subscriptions")).toHaveLength(1);
      const merged = db.rows("subscriptions")[0];
      expect(merged.purchaseToken).toBe("replacement");
      // The merge must not attribute the record to anyone who did not bind it,
      // and it must not revoke the binder who did.
      expect(
        db
          .rows("commerceEvents")
          .every(
            (event) =>
              event.userId === undefined || event.userId === "linked-owner",
          ),
      ).toBe(true);
      expect(
        db
          .rows("commerceEvents")
          .some((event) => event.eventType === "entitlement.revoked"),
      ).toBe(false);
      if (testCase.boundToken) {
        // A live binding on either side is a later association than the erasure,
        // so it survives and the marker does not carry.
        expect(merged.userId).toBe("linked-owner");
        expect(merged.accountErased).toBeUndefined();
      } else {
        expect(merged.userId).toBeUndefined();
        expect(merged.accountErased).toBe(true);
        // Unowned again, so the record can be associated with someone new.
        expect(
          await bindSubscriptionToUserHandler(ctx, {
            projectId: PROJECT_ID as never,
            purchaseToken: "replacement",
            userId: "new-owner",
          }),
        ).not.toBeNull();
        expect(db.rows("subscriptions")[0].accountErased).toBeUndefined();
      }
    },
  );
});

describe("bindSubscriptionToUser amount handling", () => {
  it("does not repeat an amount the webhook already reported", async () => {
    const db = new MemDb();
    db.seedProduct({
      projectId: PROJECT_ID,
      platform: "Android",
      productId: "premium_monthly",
      billingPeriod: "P1M",
    });
    const eventId = await seedWebhookEvent(db, {
      type: "SubscriptionStarted",
      notificationId: "message-webhook-first",
      occurredAt: 1_000,
    });
    await applySubscriptionEventHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      eventId: eventId as never,
    });
    const afterWebhook = db
      .rows("commerceEvents")
      .filter((row) => row.amountMicros !== undefined).length;

    await bindSubscriptionToUserHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "user_1",
    });

    const priced = db
      .rows("commerceEvents")
      .filter((row) => row.amountMicros !== undefined);
    // The bind grant correlates an existing purchase to a user; it is not a
    // second billing, so the count must not move.
    expect(priced.length).toBe(afterWebhook);
    expect(db.rows("commerceEvents").at(-1)?.eventType).toBe(
      "entitlement.granted",
    );
    expect(db.rows("commerceEvents").at(-1)?.amountMicros).toBeUndefined();
  });
});

describe("applySubscriptionEventHandler", () => {
  beforeEach(() => {
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  // Commerce Protocol's `whenNoPriorStoreEvent` turns on store history, not on
  // whether a record exists — a purchase learned from a client receipt but
  // never from the store still begins the story. That distinction lives here,
  // in the override, and nowhere in the state machine, so it is tested here.
  it("starts rather than recovers when a record exists with no store history", async () => {
    const db = new MemDb();
    db.seedProduct({
      projectId: PROJECT_ID,
      platform: "Android",
      productId: "premium_monthly",
      billingPeriod: "P1M",
    });
    // A client receipt created this row; no store notification ever touched it,
    // so it carries no lastEventId.
    await db.insert("subscriptions", {
      projectId: PROJECT_ID,
      platform: "Android",
      purchaseToken: TOKEN,
      productId: "premium_monthly",
      state: "Unknown",
      willRenew: true,
      updatedAt: 0,
    });
    const eventId = await seedWebhookEvent(db, {
      type: "SubscriptionStarted",
      notificationId: "message-first-store-event",
      occurredAt: 1_000,
    });

    await applySubscriptionEventHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      eventId: eventId as never,
    });
    // Assert on what was emitted, not what the handler returned: the override
    // applies to the commerce event, while the return value carries the state
    // machine's own transition.
    expect(db.rows("commerceEvents").map((row) => row.eventType)).toContain(
      "subscription.started",
    );
  });

  it.each([["SubscriptionPriceChange"], ["SubscriptionDeferred"]])(
    "emits no commerce event when %s is the first store event for a receipt-bootstrapped row",
    async (storeEventType) => {
      // store-event-mapping.json pins whenNoPriorStoreEvent -> event: null for
      // price changes and deferrals: with no earlier store event there is no
      // baseline the event could describe.
      const db = new MemDb();
      db.seedProduct({
        projectId: PROJECT_ID,
        platform: "Android",
        productId: "premium_monthly",
        billingPeriod: "P1M",
      });
      await db.insert("subscriptions", {
        projectId: PROJECT_ID,
        platform: "Android",
        purchaseToken: TOKEN,
        productId: "premium_monthly",
        state: "Active",
        expiresAt: 9_999_999_999_999,
        willRenew: true,
        updatedAt: 0,
      });
      const eventId = await seedWebhookEvent(db, {
        type: storeEventType as never,
        notificationId: `message-${storeEventType}`,
        occurredAt: 1_000,
      });

      await applySubscriptionEventHandler(makeCtx(db), {
        projectId: PROJECT_ID as never,
        eventId: eventId as never,
      });
      expect(db.rows("commerceEvents")).toEqual([]);
    },
  );

  // Rows written before `lastEventOccurredAt` existed carry only `lastEventId`,
  // so the timestamp guard cannot judge them. Both of its fallbacks protect a
  // money path: a redelivery re-applies the transition and books it twice.
  it.each([
    ["the same event redelivered", "message-legacy", 500, "Expired"],
    ["an older event arriving late", "message-older", 200, "Expired"],
  ])(
    "drops %s against a legacy row",
    async (_name, notificationId, occurredAt, expected) => {
      const db = new MemDb();
      db.seedProduct({
        projectId: PROJECT_ID,
        platform: "Android",
        productId: "premium_monthly",
