    });
    const started = await seedWebhookEvent(db, {
      type: "SubscriptionStarted",
      notificationId: "unbound-started",
      occurredAt: 1_000,
    });
    await applySubscriptionEventHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      eventId: started as never,
    });
    const expired = await seedWebhookEvent(db, {
      type: "SubscriptionExpired",
      notificationId: "unbound-expired",
      occurredAt: 2_000,
    });
    await applySubscriptionEventHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      eventId: expired as never,
    });

    const beforeBind = db.rows("commerceEvents").map((row) => row.eventType);
    expect(beforeBind).toEqual([
      "subscription.started",
      "subscription.expired",
    ]);

    await bindSubscriptionToUserHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "user-after-expiry",
    });

    expect(db.rows("commerceEvents").map((row) => row.eventType)).toEqual(
      beforeBind,
    );
    expect(db.rows("subscriptions")[0]).toMatchObject({
      state: "Expired",
      userId: "user-after-expiry",
    });
  });

  it("uses the compact source snapshot after the webhook row is pruned", async () => {
    const db = new MemDb();
    const eventId = await seedWebhookEvent(db, {
      type: "SubscriptionStarted",
      notificationId: "old-webhook",
      occurredAt: 2_000,
    });
    await applySubscriptionEventHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      eventId: eventId as never,
    });
    await db.delete(eventId);

    await bindSubscriptionToUserHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "user-after-retention",
    });
    expect(db.rows("commerceEvents").at(-1)).toMatchObject({
      eventType: "entitlement.granted",
      productId: "premium_monthly",
      userId: "user-after-retention",
      sourceStoreNotificationId: "old-webhook",
    });
  });
});

describe("user binding authorization", () => {
  const seedBound = async (db: MemDb, userId?: string) => {
    db.seedProduct({
      projectId: PROJECT_ID,
      platform: "Android",
      productId: "premium_monthly",
      billingPeriod: "P1M",
    });
    await db.insert("subscriptions", {
      projectId: PROJECT_ID,
      platform: "Android",
      purchaseToken: TOKEN,
      productId: "premium_monthly",
      state: "Active",
      willRenew: true,
      updatedAt: 0,
      ...(userId ? { userId } : {}),
    });
  };

  // Token possession is not proof of ownership, and a distinct rejection would
  // tell any holder of the app-embedded publishable key that a token exists
  // and belongs to someone.
  it("reports an already-bound subscription the same as an unknown token", async () => {
    const owned = new MemDb();
    await seedBound(owned, "victim");
    const unknown = new MemDb();
    await seedBound(unknown, "victim");
    await unknown.delete(unknown.rows("subscriptions")[0]._id);

    const attacker = {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "attacker",
    };
    await expect(
      bindSubscriptionToUserHandler(makeCtx(owned) as never, attacker),
    ).resolves.toBeNull();
    await expect(
      bindSubscriptionToUserHandler(makeCtx(unknown) as never, attacker),
    ).resolves.toBeNull();
    expect(owned.rows("subscriptions")[0].userId).toBe("victim");
  });

  // Erasure unlinked the previous owner. Once the job is gone the record is
  // unowned, and an operator may associate it again exactly as a purchase can.
  it("rebinds a record whose erased owner has already been unlinked", async () => {
    const db = new MemDb();
    await seedBound(db, undefined);
    await db.patch(db.rows("subscriptions")[0]._id, { accountErased: true });
    expect(
      await rebindSubscriptionToUserHandler(makeCtx(db), {
        projectId: PROJECT_ID as never,
        purchaseToken: TOKEN,
        userId: "real-owner",
      }),
    ).not.toBeNull();
    const row = db.rows("subscriptions")[0];
    expect(row.userId).toBe("real-owner");
    expect(row.accountErased).toBeUndefined();
  });

  it("still refuses to move a record away from its live owner", async () => {
    const db = new MemDb();
    await seedBound(db, "real-owner");
    expect(
      await bindSubscriptionToUserHandler(makeCtx(db), {
        projectId: PROJECT_ID as never,
        purchaseToken: TOKEN,
        userId: "someone-else",
      }),
    ).toBeNull();
    expect(db.rows("subscriptions")[0].userId).toBe("real-owner");
  });

  it.each(["queued", "running", "completed"])(
    "refuses rebind into or out of an account with a %s erasure job",
    async (status) => {
      for (const erasedUser of ["source-user", "target-user"]) {
        const db = new MemDb();
        await seedBound(db, "source-user");
        const hashKey = "erasure-test-key";
        await db.patch(PROJECT_ID, { userErasureHashKey: hashKey });
        await db.insert("subscriptionUserErasureJobs", {
          projectId: PROJECT_ID,
          userIdHash: await hmacSha256Hex(hashKey, erasedUser),
          status,
        });
        const before = structuredClone(db.rows("subscriptions"));
        expect(
          await rebindSubscriptionToUserHandler(makeCtx(db), {
            projectId: PROJECT_ID as never,
            purchaseToken: TOKEN,
            userId: "target-user",
          }),
        ).toBeNull();
        expect(db.rows("subscriptions")).toEqual(before);
        expect(db.rows("commerceEvents")).toEqual([]);
      }
    },
  );

  // A consumer gating access on commerce events must be told the purchase
  // moved, or the wrong user keeps access and the real one never gets it.
  it("revokes the old user and grants the new one on a rebind", async () => {
    const db = new MemDb();
    db.seedProduct({
      projectId: PROJECT_ID,
      platform: "Android",
      productId: "premium_monthly",
      billingPeriod: "P1M",
    });
    const priorId = await seedWebhookEvent(db, {
      type: "SubscriptionStarted",
      notificationId: "rebind-source",
      occurredAt: 1_000,
    });
    await db.insert("subscriptions", {
      projectId: PROJECT_ID,
      platform: "Android",
      purchaseToken: TOKEN,
      productId: "premium_monthly",
      state: "Active",
      willRenew: true,
      userId: "wrong-user",
      lastEventId: priorId,
      lastEventOccurredAt: 1_000,
      lastEventSourceNotificationId: "rebind-source",
      lastEventSource: {
        type: "SubscriptionStarted",
        environment: "Production",
        productId: "premium_monthly",
      },
      expiresAt: Date.now() + 86_400_000,
      updatedAt: 0,
    });

    await rebindSubscriptionToUserHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "real-owner",
    });

    const emitted = db
      .rows("commerceEvents")
      .map((r) => [r.eventType, r.userId]);
    expect(emitted).toEqual([
      ["entitlement.revoked", "wrong-user"],
      ["entitlement.granted", "real-owner"],
    ]);
  });

  // A rebind that cannot attribute events leaves the developer backend
  // believing the old user still owns the purchase. Say so rather than
  // reporting plain success.
  it("reports a rebind it could not notify about", async () => {
    const db = new MemDb();
    db.seedProduct({
      projectId: PROJECT_ID,
      platform: "Android",
      productId: "premium_monthly",
      billingPeriod: "P1M",
    });
    await db.insert("subscriptions", {
      projectId: PROJECT_ID,
      platform: "Android",
      purchaseToken: TOKEN,
      productId: "premium_monthly",
      state: "Active",
      willRenew: true,
      userId: "wrong-user",
      expiresAt: Date.now() + 86_400_000,
      updatedAt: 0,
    });

    const outcome = await rebindSubscriptionToUserHandler(makeCtx(db), {
      projectId: PROJECT_ID as never,
      purchaseToken: TOKEN,
      userId: "real-owner",
    });
    expect(outcome?.notified).toBe(false);
    expect(db.rows("subscriptions")[0].userId).toBe("real-owner");
    expect(db.rows("commerceEvents")).toEqual([]);
  });

  it("lets an operator move a wrong binding", async () => {
    const db = new MemDb();
    await seedBound(db, "wrong-user");
    await expect(
      rebindSubscriptionToUserHandler(makeCtx(db) as never, {
        projectId: PROJECT_ID as never,
        purchaseToken: TOKEN,
        userId: "real-owner",
      }),
    ).resolves.not.toBeNull();
    expect(db.rows("subscriptions")[0].userId).toBe("real-owner");
  });
});

kit/convex/subscriptions/query.ts:
import { query, type QueryCtx } from "../_generated/server";
import { ConvexError, v, type Infer } from "convex/values";
import type { Doc, Id } from "../_generated/dataModel";

import {
  resolveProjectByApiKeyFromDb,
  resolveProjectByIdForCurrentUserFromDb,
} from "../projects/helpers";
import { monthlyMicrosForSub } from "./monthlyMicros";
import { selectMostRecentlyUpdatedSubscription } from "./selectLatest";
import {
  DEFAULT_REPORTING_CURRENCY,
  normalizeReportingCurrencyOrDefault,
} from "../utils/currency";
import { subscriptionStateValidator } from "../utils/validation";

const subscriptionFields = {
  id: v.id("subscriptions"),
  productId: v.string(),
  platform: v.union(v.literal("IOS"), v.literal("Android")),
  state: subscriptionStateValidator,
  expiresAt: v.optional(v.number()),
  renewsAt: v.optional(v.number()),
  willRenew: v.optional(v.boolean()),
  cancellationReason: v.optional(v.string()),
  currency: v.optional(v.string()),
  priceAmountMicros: v.optional(v.number()),
  startedAt: v.number(),
  updatedAt: v.number(),
  // SECURITY DEBT: on Android this is the credential a server accepts as proof
  // of purchase, and these rows reach routes that answer to a publishable key
  // shipped inside the app. It cannot be removed additively: MAUI declares it
  // `required`, and its tolerant deserializer turns a missing field into a null
  // subscription and silently drops entitlement rows — every installed MAUI app
  // would lose entitlement. Removal needs an explicit version transition.
  purchaseToken: v.string(),
  originalTransactionId: v.optional(v.string()),
  userId: v.optional(v.string()),
};
const subscriptionShape = v.object(subscriptionFields);
const subscriptionV2Shape = v.object({
  id: v.id("subscriptions"),
  productId: v.string(),
  platform: v.union(v.literal("IOS"), v.literal("Android")),
  state: subscriptionStateValidator,
  expiresAt: v.optional(v.number()),
  renewsAt: v.optional(v.number()),
  willRenew: v.optional(v.boolean()),
  cancellationReason: v.optional(v.string()),
  currency: v.optional(v.string()),
  priceAmountMicros: v.optional(v.number()),
  startedAt: v.number(),
  updatedAt: v.number(),
  userId: v.optional(v.string()),
});
const subscriptionEvaluationRowShape = v.object({
  ...subscriptionFields,
  createdAt: v.number(),
});
type SubscriptionRow = Infer<typeof subscriptionShape>;
type SubscriptionV2Row = Infer<typeof subscriptionV2Shape>;
type SubscriptionEvaluationRow = Infer<typeof subscriptionEvaluationRowShape>;
export const MAX_USER_SUBSCRIPTION_ROWS = 200;

/**
 * SPEC.md 2.3 entitlement gate as a pure predicate: only Active and
 * InGracePeriod grant access, an omitted expiry means none is known, and the
 * boundary is exclusive — expiresAt == now is NOT entitled. Exported so the
 * conformance adapter certifies the same predicate every read uses.
 */
export function isEntitledAt(
  state: string,
  expiresAt: number | null | undefined,
  now: number,
): boolean {
  if (state !== "Active" && state !== "InGracePeriod") return false;
  if (expiresAt != null && expiresAt <= now) return false;
  return true;
}

function isActive(sub: Doc<"subscriptions">, now: number): boolean {
  return isEntitledAt(sub.state, sub.expiresAt, now);
}

function isEntitledState(sub: Doc<"subscriptions">): boolean {
  return sub.state === "Active" || sub.state === "InGracePeriod";
}

export function assertUserSubscriptionRowLimit(
  rows: Array<Doc<"subscriptions">>,
): void {
  if (rows.length <= MAX_USER_SUBSCRIPTION_ROWS) return;
  throw new ConvexError({
    code: "ENTITLEMENT_SNAPSHOT_TOO_LARGE",
    message:
      "This user has more than 200 subscription rows. Contact IAPKit support before retrying.",
  });
}

async function userSubscriptionRows(
  ctx: QueryCtx,
  projectId: Id<"projects">,
  userId: string,
): Promise<Array<Doc<"subscriptions">>> {
  const rows = await ctx.db
    .query("subscriptions")
    .withIndex("by_project_and_user_and_updated", (q) =>
      q.eq("projectId", projectId).eq("userId", userId),
    )
    .order("desc")
    .take(MAX_USER_SUBSCRIPTION_ROWS + 1);
  assertUserSubscriptionRowLimit(rows);
  return rows;
}

export function shapeSubscriptionEvaluationSnapshot(
  rows: Array<Doc<"subscriptions">>,
): {
  candidates: SubscriptionEvaluationRow[];
  fallback: SubscriptionEvaluationRow | null;
} {
  const fallback = selectMostRecentlyUpdatedSubscription(rows);
  return {
    candidates: rows
      .filter(isEntitledState)
      .map(shapeSubscriptionEvaluationRow),
    fallback: fallback ? shapeSubscriptionEvaluationRow(fallback) : null,
  };
}

function shapeSubscriptionEvaluationRow(
  sub: Doc<"subscriptions">,
): SubscriptionEvaluationRow {
  return {
    ...shapeSubscriptionRow(sub),
    createdAt: sub._creationTime,
  };
}

export function shapeSubscriptionRow(
  sub: Doc<"subscriptions">,
): SubscriptionRow {
  const row: SubscriptionRow = {
    id: sub._id,
    productId: sub.productId,
    platform: sub.platform,
    state: sub.state,
    expiresAt: sub.expiresAt,
    renewsAt: sub.renewsAt,
    willRenew: sub.willRenew,
    cancellationReason: sub.cancellationReason,
    currency: sub.currency,
    priceAmountMicros: sub.priceAmountMicros,
    startedAt: sub.startedAt,
    updatedAt: sub.updatedAt,
    purchaseToken: sub.purchaseToken,
    userId: sub.userId,
  };

  if (sub.platform === "IOS") {
    return {
      ...row,
      originalTransactionId: sub.purchaseToken,
    };
  }

  return row;
}

export function shapeSubscriptionV2Row(
  sub: Doc<"subscriptions">,
): SubscriptionV2Row {
  return {
    id: sub._id,
    productId: sub.productId,
    platform: sub.platform,
    state: sub.state,
    expiresAt: sub.expiresAt,
    renewsAt: sub.renewsAt,
    willRenew: sub.willRenew,
    cancellationReason: sub.cancellationReason,
    currency: sub.currency,
    priceAmountMicros: sub.priceAmountMicros,
    startedAt: sub.startedAt,
    updatedAt: sub.updatedAt,
    userId: sub.userId,
  };
}

async function projectByApiKey(
  ctx: QueryCtx,
  apiKey: string | undefined,
  requiredAccess: "client" | "admin" = "client",
): Promise<Doc<"projects"> | null> {
  if (!apiKey) return null;
  const resolved = await resolveProjectByApiKeyFromDb(
    ctx,
    apiKey,
    requiredAccess,
  );
  return resolved?.project ?? null;
}

async function requireAdminProjectByApiKey(
  ctx: QueryCtx,
  apiKey: string,
): Promise<Doc<"projects">> {
  const project = await projectByApiKey(ctx, apiKey, "admin");
  if (!project) {
    throw new ConvexError({
      code: "INVALID_API_KEY",
      message: "API key is invalid or inactive",
    });
  }
  return project;
}

async function projectByIdForCurrentUser(
  ctx: QueryCtx,
  projectId: Id<"projects"> | undefined,
): Promise<Doc<"projects"> | null> {
  if (!projectId) return null;
  const resolved = await resolveProjectByIdForCurrentUserFromDb(ctx, projectId);
  return resolved?.project ?? null;
}

async function projectForReadArgs(
  ctx: QueryCtx,
  args: {
    apiKey?: string;
    projectId?: Id<"projects">;
  },
  apiKeyAccess: "client" | "admin" = "client",
): Promise<Doc<"projects"> | null> {
  if (args.projectId) {
    return projectByIdForCurrentUser(ctx, args.projectId);
  }

  if (args.apiKey !== undefined) {
    return projectByApiKey(ctx, args.apiKey, apiKeyAccess);
  }

  throw new Error("apiKey or projectId is required.");
}

export interface MrrCurrencyEntry {
  currency: string;
  mrrMicros: number;
}

/**
 * Selects the headline MRR entry for a project's reporting currency.
 *
 * `reportingCurrency` is normalized via `normalizeReportingCurrencyOrDefault`,
 * so unknown or invalid input falls back to `DEFAULT_REPORTING_CURRENCY`.
 * If no entry matches the normalized currency, returned `mrrMicros` is `0`.
 * Returned `excludedMrrByCurrency` contains every non-reporting-currency entry.
 *
 * @param entries Per-currency MRR rows already summed for the project.
 * @param reportingCurrency Project-configured reporting currency, raw or normalized.
 * @returns The normalized `currency`, selected `mrrMicros`, and excluded rows.
 */
export function selectReportingMrr(
  entries: MrrCurrencyEntry[],
  reportingCurrency: string | null | undefined,
): {
  currency: string;
  mrrMicros: number;
  excludedMrrByCurrency: MrrCurrencyEntry[];
} {
  const normalizedReportingCurrency =
    normalizeReportingCurrencyOrDefault(reportingCurrency);
  const reportingEntry = entries.find(
    (entry) => entry.currency === normalizedReportingCurrency,
  );

  return {
    currency: normalizedReportingCurrency,
    mrrMicros: reportingEntry?.mrrMicros ?? 0,
    excludedMrrByCurrency: entries.filter(
      (entry) => entry.currency !== normalizedReportingCurrency,
    ),
  };
}

// Time-independent evaluation snapshot for the Fly HTTP boundary. It excludes
// refunded, revoked, and other historical rows except for the single latest
// fallback needed by status. State-entitled candidates may include a row whose
// expiresAt has just passed; Fly removes it with its own current clock before
// producing the public HTTP response. Convex may safely cache the snapshot and
// invalidates it when a dependent row changes.
export const subscriptionEvaluationSnapshot = query({
  args: {
    apiKey: v.string(),
    userId: v.string(),
  },
  returns: v.object({
    projectId: v.union(v.id("projects"), v.null()),
    candidates: v.array(subscriptionEvaluationRowShape),
    fallback: v.union(subscriptionEvaluationRowShape, v.null()),
  }),
  handler: async (ctx, args) => {
    const project = await projectByApiKey(ctx, args.apiKey);
    if (!project) return { projectId: null, candidates: [], fallback: null };

    const rows = await userSubscriptionRows(ctx, project._id, args.userId);
    return {
      projectId: project._id,
      ...shapeSubscriptionEvaluationSnapshot(rows),
    };
  },
});

// `/v2` account reads are server-to-server. Convex repeats the admin check and
// shapes the response without store credentials before it crosses the HTTP
// boundary.
export const subscriptionStatusV2 = query({
  args: { apiKey: v.string(), userId: v.string(), now: v.number() },
  returns: v.object({
    active: v.boolean(),
    subscription: v.union(subscriptionV2Shape, v.null()),
  }),
  handler: async (ctx, args) => {
    const project = await requireAdminProjectByApiKey(ctx, args.apiKey);

    const subs = await userSubscriptionRows(ctx, project._id, args.userId);
    const activeSubs = subs.filter((candidate) =>
      isActive(candidate, args.now),
    );
    const selected = selectMostRecentlyUpdatedSubscription(
      activeSubs.length > 0 ? activeSubs : subs,
    );

    return {
      active: activeSubs.length > 0,
      subscription: selected ? shapeSubscriptionV2Row(selected) : null,
    };
  },
});

export const entitlementsV2 = query({
  args: { apiKey: v.string(), userId: v.string(), now: v.number() },
  returns: v.object({
    userId: v.string(),
    productIds: v.array(v.string()),
    subscriptions: v.array(subscriptionV2Shape),
  }),
  handler: async (ctx, args) => {
    const project = await requireAdminProjectByApiKey(ctx, args.apiKey);

    const all = await userSubscriptionRows(ctx, project._id, args.userId);
    const active = all.filter((sub) => isActive(sub, args.now));
    return {
      userId: args.userId,
      productIds: Array.from(new Set(active.map((sub) => sub.productId))),
      subscriptions: active.map(shapeSubscriptionV2Row),
    };
  },
});

// Authoritative server-credential gate with no side effect and no data. The
// commerce bindPurchase handler calls this before it parses store evidence, so
// an unknown or under-scoped key is rejected (UNAUTHORIZED / FORBIDDEN) before
// it can learn which stores bind or which evidence a store requires.
export const assertServerAccess = query({
  args: { apiKey: v.string() },
  returns: v.object({ ok: v.boolean() }),
  handler: async (ctx, args) => {
    await requireAdminProjectByApiKey(ctx, args.apiKey);
    return { ok: true };
  },
});

export const userErasureStatusV2 = query({
  args: {
    apiKey: v.string(),
    // The id arrives from a URL path; a malformed one must read as "no such
    // job" (404), not fail argument validation into a 500.
    jobId: v.string(),
  },
  returns: v.union(
    v.null(),
    v.object({
      jobId: v.id("subscriptionUserErasureJobs"),
      status: v.union(
        v.literal("queued"),
        v.literal("running"),
        v.literal("completed"),
      ),
      subscriptionsErased: v.number(),
      commerceEventsErased: v.number(),
      createdAt: v.number(),
      updatedAt: v.number(),
      completedAt: v.optional(v.number()),
    }),
  ),
  handler: async (ctx, args) => {
    const project = await requireAdminProjectByApiKey(ctx, args.apiKey);
    const jobId = ctx.db.normalizeId("subscriptionUserErasureJobs", args.jobId);
    if (!jobId) return null;
    const job = await ctx.db.get(jobId);
    if (!job || job.projectId !== project._id) return null;
    return {
      jobId: job._id,
      status: job.status,
      subscriptionsErased: job.subscriptionsErased,
      commerceEventsErased: job.commerceEventsErased,
      createdAt: job.createdAt,
      updatedAt: job.updatedAt,
      completedAt: job.completedAt,
    };
  },
});

// Match onesub's `/onesub/status?userId=` — returns the most-recently-
// updated active subscription when the user is entitled, otherwise the
// most-recently-updated subscription overall, plus one `active` boolean
// for simple gating.
export const subscriptionStatus = query({
  args: { apiKey: v.string(), userId: v.string() },
  returns: v.object({
    active: v.boolean(),
    subscription: v.union(subscriptionShape, v.null()),
  }),
  handler: async (ctx, args) => {
    const project = await projectByApiKey(ctx, args.apiKey);
    if (!project) return { active: false, subscription: null };

    const subs = await userSubscriptionRows(ctx, project._id, args.userId);

    const now = Date.now();
    const activeSubs = subs.filter((candidate) => isActive(candidate, now));
    const sub = selectMostRecentlyUpdatedSubscription(
      activeSubs.length > 0 ? activeSubs : subs,
    );
    if (!sub) return { active: false, subscription: null };

    return {
      active: activeSubs.length > 0,
      subscription: shapeSubscriptionRow(sub),
    };
  },
});

// Match onesub's entitlement evaluation — every productId the user
// currently has rights to. Aggregates across all subscription rows so
// a user with multiple offers (resub, family share, cross-grade) sees
// the union.
export const entitlements = query({
  args: { apiKey: v.string(), userId: v.string() },
  returns: v.object({
    userId: v.string(),
    productIds: v.array(v.string()),
    subscriptions: v.array(subscriptionShape),
  }),
  handler: async (ctx, args) => {
    const project = await projectByApiKey(ctx, args.apiKey);
    if (!project) {
      return { userId: args.userId, productIds: [], subscriptions: [] };
    }

    const all = await userSubscriptionRows(ctx, project._id, args.userId);

    const now = Date.now();
    const active = all.filter((sub) => isActive(sub, now));
    return {
      userId: args.userId,
      productIds: Array.from(new Set(active.map((sub) => sub.productId))),
      subscriptions: active.map(shapeSubscriptionRow),
    };
  },
});

// Filtered list for the dashboard's subscriptions page. Mirrors
// onesub's `SubscriptionStore.listFiltered` API.
export const listSubscriptions = query({
  args: {
    apiKey: v.optional(v.string()),
    projectId: v.optional(v.id("projects")),
    state: v.optional(subscriptionStateValidator),
    productId: v.optional(v.string()),
    userId: v.optional(v.string()),
    limit: v.optional(v.number()),
  },
  returns: v.object({
    items: v.array(subscriptionShape),
    total: v.number(),
  }),
  handler: async (ctx, args) => {
    const project = await projectForReadArgs(ctx, args, "admin");
    if (!project) return { items: [], total: 0 };

    const limit = Math.min(Math.max(args.limit ?? 50, 1), 200);

    // userId path: subscriptions per user is a small population
    // (single digits in practice — a user with 50 subscriptions on a
    // single project is pathological), so we collect the entire
    // by_project_and_user slice and apply state/productId filters in
    // memory rather than throwing. Earlier behaviour rejected the
    // combo with an error, which made the dashboard "filter user X by
    // state Active" path unusable (PR #124
    // (https://github.com/hyodotdev/openiap/pull/124) review).
    if (args.userId) {
      const userRows = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_user", (q) =>
          q.eq("projectId", project._id).eq("userId", args.userId),
        )
        .order("desc")
        .collect();
      const filtered = userRows.filter((sub) => {
        if (args.state && sub.state !== args.state) return false;
        if (args.productId && sub.productId !== args.productId) return false;
        return true;
      });
      return {
        items: filtered.slice(0, limit).map(shapeSubscriptionRow),
        total: filtered.length,
      };
    }

    // Pick the most-selective index for the supplied filters. Schema
    // covers single-filter combinations directly; the composite
    // (projectId, state, productId) index handles the dashboard's
    // common "filter by state and SKU" combination so we don't need
    // an over-fetch + in-memory post-filter that could miss rows
    // past the take() boundary.
    let rows: Array<Doc<"subscriptions">>;
    if (args.state && args.productId) {
      rows = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_state_and_product", (q) =>
          q
            .eq("projectId", project._id)
            .eq("state", args.state!)
            .eq("productId", args.productId!),
        )
        .order("desc")
        .take(limit);
    } else if (args.state) {
      rows = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_state", (q) =>
          q.eq("projectId", project._id).eq("state", args.state!),
        )
        .order("desc")
        .take(limit);
    } else if (args.productId) {
      rows = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_product", (q) =>
          q.eq("projectId", project._id).eq("productId", args.productId!),
        )
        .order("desc")
        .take(limit);
    } else {
      rows = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_updated", (q) =>
          q.eq("projectId", project._id),
        )
        .order("desc")
        .take(limit);
    }

    // All filter combinations hit an index that covers the supplied
    // columns now (the (state + productId) composite was added in
    // schema.ts), so no in-memory post-filter is needed here.

    // `total` reflects the filtered window we actually materialized,
    // not the full server-side count. Computing a true total would
    // require a separate aggregate scan that defeats the take() bound
    // we just put in. The dashboard treats `total` as "rows shown
    // matching the current filter" and surfaces "+ more" affordances
    // via the next page request.
    return {
      items: rows.slice(0, limit).map(shapeSubscriptionRow),
      total: rows.length,
    };
  },
});

// Metrics aggregation. Reads incrementally-maintained per-currency
// counters out of `subscriptionStats` for the live state buckets +
// MRR (O(currencies-per-project) — typically 1-3 rows), and bounded
// indexed scans over `by_project_and_state` for the 30-day rolling
// counters. The prior implementation took up to 10,000 subscriptions
// off the by_project_and_updated index and aggregated in memory,
// which silently undercounted projects above that cap.
//
// Migration safety: when the stats table is empty for a project
// (pre-rollout state) we fall through to a one-shot recompute via
// the same statsContributionFor logic so the dashboard stays
// correct on first read after deploy. The
// `recomputeSubscriptionStats` internal mutation populates rows for
// future reads.
export const metricsSummary = query({
  args: {
    apiKey: v.optional(v.string()),
    projectId: v.optional(v.id("projects")),
  },
  returns: v.object({
    activeSubs: v.number(),
    inGracePeriod: v.number(),
    inBillingRetry: v.number(),
    refunded30d: v.number(),
    canceled30d: v.number(),
    // Headline MRR in the project's reporting currency, normalized
    // to monthly. Historical field name kept for dashboard / MCP
    // consumers, but the value is no longer a cross-currency or
    // "most popular currency" total.
    mrrMicros: v.number(),
    currency: v.optional(v.string()),
    reportingCurrency: v.string(),
    // Full per-currency breakdown so consumers that care about
    // multi-currency aren't left guessing. Each entry's `mrrMicros`
    // is summed only over subscriptions in that currency, normalized
    // to monthly via the product's billingPeriod.
    mrrByCurrency: v.array(
      v.object({ currency: v.string(), mrrMicros: v.number() }),
    ),
    excludedMrrByCurrency: v.array(
      v.object({ currency: v.string(), mrrMicros: v.number() }),
    ),
  }),
  handler: async (ctx, args) => {
    const project = await projectForReadArgs(ctx, args, "admin");
    if (!project) {
      return {
        activeSubs: 0,
        inGracePeriod: 0,
        inBillingRetry: 0,
        refunded30d: 0,
        canceled30d: 0,
        mrrMicros: 0,
        currency: DEFAULT_REPORTING_CURRENCY,
        reportingCurrency: DEFAULT_REPORTING_CURRENCY,
        mrrByCurrency: [],
        excludedMrrByCurrency: [],
      };
    }
    const now = Date.now();
    const cutoff = now - 30 * 24 * 60 * 60 * 1000;

    // Live state counters + MRR — read out of the incrementally
    // maintained `subscriptionStats` table.
    const statsRows = await ctx.db
      .query("subscriptionStats")
      .withIndex("by_project", (q) => q.eq("projectId", project._id))
      .collect();

    let activeSubs = 0;
    let inGracePeriod = 0;
    let inBillingRetry = 0;
    const mrrAccumulators = new Map<string, number>();

    if (statsRows.length > 0) {
      for (const row of statsRows) {
        activeSubs += row.activeSubs;
        inGracePeriod += row.inGracePeriod;
        inBillingRetry += row.inBillingRetry;
        if (row.currency && row.mrrMicros > 0) {
          mrrAccumulators.set(
            row.currency,
            (mrrAccumulators.get(row.currency) ?? 0) + row.mrrMicros,
          );
        }
      }
    } else {
      // No stats rows yet — pre-rollout state for this project.
      // Compute on the fly so the dashboard isn't blank on first
      // read after deploy. Bounded by the same per-project scan the
      // backfill mutation does; for projects past the prior 10k cap
      // this is a one-time cost until `recomputeSubscriptionStats`
      // populates the table.
      //
      // Bounded by FALLBACK_SCAN_CAP so a project that's hugely past
      // the prior 10k scan limit can't crash the dashboard render.
      // The cap matches the previous implementation's bound; the
      // first read after deploy schedules an async backfill via the
      // drift-correction cron, after which subsequent reads come
      // out of subscriptionStats and have no scan at all.
      const FALLBACK_SCAN_CAP = 10_000;
      const periodByProductId = await loadPeriodByProductId(ctx, project._id);
      const allSubs = await ctx.db
        .query("subscriptions")
        .withIndex("by_project_and_updated", (q) =>
          q.eq("projectId", project._id),
        )
        .order("desc")
        .take(FALLBACK_SCAN_CAP);
      for (const sub of allSubs) {
        if (sub.state === "Active" && isActive(sub, now)) {
          activeSubs += 1;
          if (typeof sub.priceAmountMicros === "number" && sub.currency) {
            const monthly = monthlyMicrosForSub(
              sub,
              periodByProductId.get(sub.productId),
            );
            mrrAccumulators.set(
              sub.currency,
              (mrrAccumulators.get(sub.currency) ?? 0) + monthly,
            );
          }
        } else if (sub.state === "InGracePeriod") {
          inGracePeriod += 1;
        } else if (sub.state === "InBillingRetry") {
          inBillingRetry += 1;
        }
      }
    }

    // 30-day rolling counters — bounded by churn rather than by
    // historical state archive. The previous implementation walked
    // every `Refunded` row + every (Active|InGracePeriod|InBillingRetry
    // |Expired) row for the project and filtered in memory, which
    // grew unbounded as the historical archive accumulated. We now
    // do a single time-windowed scan via `by_project_and_updated`
    // with `gte(cutoff)`, then derive both refunded + canceled
    // counters in one pass. The candidate set is bounded by the
    // last 30 days of state changes (typically thousands per
    // project, never the full lifetime).
    // Cap the windowed scan so a project with > 10k state changes
    // in 30 days can't exceed Convex's 40k document-read limit. The
    // rolling counters degrade gracefully — if a project genuinely
    // hits this bound the dashboard shows an approximate count that
    // still tracks the cohort closely (this is the same trade-off
    // the previous SUBS_SCAN_CAP made for active counts, before the
    // incremental subscriptionStats path replaced it). Real-world
    // monthly churn is well under 10k for any realistic deployment.
    const ROLLING_SCAN_CAP = 10_000;
    const recentlyChanged = await ctx.db
      .query("subscriptions")
      .withIndex("by_project_and_updated", (q) =>
        q.eq("projectId", project._id).gte("updatedAt", cutoff),
      )
      .take(ROLLING_SCAN_CAP);
    let refunded30d = 0;
    let canceled30d = 0;
    const CANCELED_STATES = new Set([
      "Active",
      "InGracePeriod",
      "InBillingRetry",
      "Expired",
    ]);
    for (const sub of recentlyChanged) {
      if (sub.state === "Refunded") {
        refunded30d += 1;
      }
      if (
        sub.willRenew === false &&
        sub.cancellationReason === "UserCanceled" &&
        CANCELED_STATES.has(sub.state)
      ) {
        canceled30d += 1;
      }
    }

    // Sort per-currency MRR for deterministic UI rendering. The
    // headline `mrrMicros` below intentionally uses only the
    // project's reporting currency; other currencies remain visible
    // in `excludedMrrByCurrency` instead of being silently summed
    // by IAPKit.
    const sorted = Array.from(mrrAccumulators.entries()).sort(
      ([a, av], [b, bv]) => (bv !== av ? bv - av : a.localeCompare(b)),
    );
    const mrrByCurrency = sorted.map(([currency, mrrMicros]) => ({
      currency,
      mrrMicros,
    }));
    const reportingMrr = selectReportingMrr(
      mrrByCurrency,
      project.reportingCurrency,
    );

    return {
      activeSubs,
      inGracePeriod,
      inBillingRetry,
      refunded30d,
      canceled30d,
      mrrMicros: reportingMrr.mrrMicros,
      currency: reportingMrr.currency,
      reportingCurrency: reportingMrr.currency,
      mrrByCurrency,
      excludedMrrByCurrency: reportingMrr.excludedMrrByCurrency,
    };
  },
});

// Daily revenue + lifecycle metrics for the Analytics dashboard. Reads
// pre-computed rollups from `revenueMetricsDaily` (populated by the
// `recomputeAllRevenueMetrics` cron) so the dashboard never scans the
// raw webhookEvents log on render.
//
// `fromDay` and `toDay` are inclusive ISO date strings (YYYY-MM-DD,
// UTC) — same format `revenueMetricsDaily.day` is stored under, so
// the index range is a direct string comparison.
//
// Return shape: one entry per rollup row, i.e. one per
// (day, currency, productId, platform). Aggregation across rows
// happens client-side (`analytics.tsx`) so the dashboard can switch
// between filter combinations without re-querying. Summing across
// currencies is a UI-side concern — `revenueMicros` from a USD row
// and a EUR row cannot be added without an FX rate.
const platformValidator = v.union(v.literal("IOS"), v.literal("Android"));

export const getRevenueMetrics = query({
  args: {
    apiKey: v.optional(v.string()),
    projectId: v.optional(v.id("projects")),
    fromDay: v.string(),
    toDay: v.string(),
    // Server-side `productId` / `currency` / `platform` filters were
    // removed because the dashboard does all of that filtering
    // client-side (the unfiltered fetch is what backs the filter-
    // dropdown population — narrowing the scan would defeat that),
    // and a server-side narrowing path was incompatible with that
    // contract: when a productId was pinned the dropdowns silently
    // collapsed to that SKU's currencies / platforms only. If a
    // future caller needs server-side narrowing for a non-dashboard
    // surface, add a separate query — don't reintroduce these as
    // optional args on this one.
  },
  returns: v.object({
    days: v.array(
      v.object({
        day: v.string(),
        currency: v.string(),
        productId: v.string(),
        platform: platformValidator,
        activeSubs: v.number(),
        newSubs: v.number(),
        renewals: v.number(),
        cancellations: v.number(),
        refunds: v.number(),
        revenueMicros: v.number(),
      }),
    ),
    // Available filter values surfaced to the dashboard so the UI
    // can render dropdowns / chiclets for everything the project
    // actually has data for, without a second round-trip.
    currencies: v.array(v.string()),
    productIds: v.array(v.string()),
    platforms: v.array(platformValidator),
    // True when the underlying scan hit `REVENUE_SCAN_CAP` and the
    // returned rows are a partial view of the requested window. The
    // dashboard surfaces this as a banner so a truncated chart is
    // visible to the operator instead of silently rendering a
    // partial tail.
    truncated: v.boolean(),
  }),
  handler: async (ctx, args) => {
    const project = await projectForReadArgs(ctx, args, "admin");
    if (!project) {
      return {
        days: [],
        currencies: [],
        productIds: [],
        platforms: [],
        truncated: false,
      };
    }

    // Reject ranges past the dashboard's longest preset (90 days)
    // before issuing the index scan. A misbehaving client can
    // otherwise request `fromDay = "1970-01-01"` and force the
    // server to materialize every rollup row in the project. The
    // 90-day cap matches `RANGES` in `analytics.tsx`; widening
    // there should bump this in lockstep.
    const MAX_RANGE_DAYS = 92;
    if (args.fromDay > args.toDay) {
      throw new Error(
        `getRevenueMetrics: fromDay (${args.fromDay}) is after toDay (${args.toDay}).`,
      );
    }
    const fromMs = Date.parse(`${args.fromDay}T00:00:00.000Z`);
    const toMs = Date.parse(`${args.toDay}T00:00:00.000Z`);
    if (Number.isNaN(fromMs) || Number.isNaN(toMs)) {
      throw new Error(
        `getRevenueMetrics: invalid ISO date(s) fromDay=${args.fromDay} toDay=${args.toDay}.`,
      );
    }
    const spanDays = Math.round((toMs - fromMs) / 86_400_000) + 1;
    if (spanDays > MAX_RANGE_DAYS) {
      throw new Error(
        `getRevenueMetrics: span of ${spanDays} days exceeds MAX_RANGE_DAYS=${MAX_RANGE_DAYS}.`,
      );
    }

    // Range scan over `revenueMetricsDaily` via
    // `by_project_and_day_and_currency` (`[projectId, day, currency]`).
    // The dashboard does all filtering (currency / product /
    // platform) client-side, so we deliberately return the full
    // window — narrowing here would prune the data the dashboard
    // needs to populate its filter dropdowns.
    //
    // Capped at REVENUE_SCAN_CAP to stay under Convex's 32k
    // document-scan limit per query. A 92-day range across a
    // maximalist project (30 SKUs × 3 currencies × 2 platforms =
    // 180 rows/day → ~16.5k rows for 92 days) fits inside this
    // cap; truncation surfaces as the `truncated` flag below and
    // an amber banner on the dashboard so a partial chart is
    // never silently rendered.
    const REVENUE_SCAN_CAP = 20_000;
    const allRows = await ctx.db
      .query("revenueMetricsDaily")
      .withIndex("by_project_and_day_and_currency", (q) =>
        q
          .eq("projectId", project._id)
          .gte("day", args.fromDay)
          .lte("day", args.toDay),
      )
      .take(REVENUE_SCAN_CAP);
    const truncated = allRows.length === REVENUE_SCAN_CAP;
    if (truncated) {
      console.warn(
        `[getRevenueMetrics] revenueMetricsDaily scan hit REVENUE_SCAN_CAP=${REVENUE_SCAN_CAP} for project=${project._id} range=${args.fromDay}..${args.toDay}; chart will undercount the tail.`,
      );
    }

    // Populate filter-dropdown choices from the unfiltered range
    // scan so the UI can render every available currency /
    // productId / platform regardless of which filter the user
    // currently has active.
    const currencies = new Set<string>();
    const productIds = new Set<string>();
    const platforms = new Set<"IOS" | "Android">();
    for (const row of allRows) {
      if (row.currency) currencies.add(row.currency);
      productIds.add(row.productId);
      platforms.add(row.platform);
    }

    return {
      days: allRows.map((row) => ({
        day: row.day,
        currency: row.currency,
        productId: row.productId,
        platform: row.platform,
        activeSubs: row.activeSubs,
        newSubs: row.newSubs,
        renewals: row.renewals,
        cancellations: row.cancellations,
        refunds: row.refunds,
        revenueMicros: row.revenueMicros,
      })),
      currencies: Array.from(currencies).sort(),
      productIds: Array.from(productIds).sort(),
      platforms: Array.from(platforms).sort(),
      truncated,
    };
  },
});

async function loadPeriodByProductId(
  ctx: QueryCtx,
  projectId: Id<"projects">,
): Promise<Map<string, string | undefined>> {
  const periodByProductId = new Map<string, string | undefined>();
  for (const platform of ["IOS", "Android"] as const) {
    const productRows = await ctx.db
      .query("products")
      .withIndex("by_project_and_platform", (q) =>
        q.eq("projectId", projectId).eq("platform", platform),
      )
      .collect();
    for (const product of productRows) {
      if (
        !periodByProductId.has(product.productId) ||
        (periodByProductId.get(product.productId) === undefined &&
          product.billingPeriod !== undefined)
      ) {
        periodByProductId.set(product.productId, product.billingPeriod);
      }
    }
  }
  return periodByProductId;
}

