import {
  internalMutation,
  internalQuery,
  type MutationCtx,
  type QueryCtx,
} from "../_generated/server";
import { ConvexError, v } from "convex/values";
import type { Doc, Id } from "../_generated/dataModel";
import { internal } from "../_generated/api";

import { HarmonizedPurchaseState } from "../purchases/purchaseState";
import {
  applySubscriptionTransition,
  entitlementActive,
  type CurrentSubscription,
  type SubscriptionEventInput,
} from "./stateMachine";
import { applyStatsTransition, statsContributionFor } from "./stats";
import { assertProjectWritable } from "../projects/writable";
import { isValidSubscriptionUserId } from "./limits";
import { isUserErasureRequested } from "./erasure";

export const USER_ERASURE_BATCH_SIZE = 100;
export const USER_ERASURE_JOB_RETENTION_MS = 7 * 24 * 60 * 60 * 1_000;
const USER_ERASURE_STALE_MS = 10 * 60 * 1_000;
const USER_ERASURE_PRUNER_BATCH_SIZE = 100;

const subscriptionPlatformValidator = v.union(
  v.literal("IOS"),
  v.literal("Android"),
);

type RawEventInput = Pick<
  Doc<"webhookEvents">,
  | "type"
  | "productId"
  | "subscriptionState"
  | "expiresAt"
  | "renewsAt"
  | "willRenew"
  | "cancellationReason"
  | "currency"
  | "priceAmountMicros"
  | "platform"
  | "effectiveImmediately"
> & { purchaseToken: string };
type SubscriptionState = Doc<"subscriptions">["state"];
type SubscriptionCancellationReason = NonNullable<
  Doc<"subscriptions">["cancellationReason"]
>;
type SubscriptionPlatform = Doc<"subscriptions">["platform"];

export type VerifiedSubscriptionInput = {
  platform: SubscriptionPlatform;
  productId: string;
  purchaseState: HarmonizedPurchaseState;
  subscriptionState?: string;
  expiresAt?: number;
  renewsAt?: number;
  willRenew?: boolean;
  currency?: string;
  priceAmountMicros?: number;
  revocationReasonIOS?: number;
};

export type VerifiedSubscriptionSnapshot = {
  productId: string;
  state: SubscriptionState;
  expiresAt?: number;
  renewsAt?: number;
  willRenew?: boolean;
  cancellationReason?: SubscriptionCancellationReason;
  clearCancellationReason?: boolean;
  currency?: string;
  priceAmountMicros?: number;
};

type ExistingSubscriptionSnapshotFields = Pick<
  Doc<"subscriptions">,
  | "expiresAt"
  | "renewsAt"
  | "willRenew"
  | "cancellationReason"
  | "currency"
  | "priceAmountMicros"
>;

type RecordVerifiedSubscriptionArgs = {
  projectId: Id<"projects">;
  platform: SubscriptionPlatform;
  purchaseToken: string;
  productId: string;
  purchaseState: string;
  subscriptionState?: string;
  expiresAt?: number;
  renewsAt?: number;
  willRenew?: boolean;
  currency?: string;
  priceAmountMicros?: number;
  revocationReasonIOS?: number;
};

type BindSubscriptionToUserArgs = {
  projectId: Id<"projects">;
  purchaseToken: string;
  userId: string;
};

interface PersistSubscriptionSnapshotArgs {
  projectId: Id<"projects">;
  platform: SubscriptionPlatform;
  purchaseToken: string;
  existing: Doc<"subscriptions"> | null;
  next: NonNullable<CurrentSubscription>;
  now: number;
  lastEvent?: Pick<
    Doc<"webhookEvents">,
    | "_id"
    | "_creationTime"
    | "type"
    | "occurredAt"
    | "sourceNotificationId"
    | "environment"
    | "productId"
    | "applicationId"
    | "transactionId"
    | "originalTransactionId"
    | "currency"
    | "priceAmountMicros"
  >;
}

interface ApplySubscriptionEventArgs {
  projectId: Id<"projects">;
  eventId: Id<"webhookEvents">;
}

interface ApplySubscriptionEventResult {
  transition: string | null;
  active: boolean;
  subscriptionId?: Id<"subscriptions">;
}

// Apply a webhook event to the canonical `subscriptions` table. The event's
// durable appliedAt marker is committed in the same Convex transaction as
// the subscription and stats writes, so both retry gaps are safe: a crash
// before this mutation can be repaired, while any event this mutation already
// processed can never be replayed after a newer lastEventId replaces it.
import { emitCommerceEvent } from "../commerce/internal";

export const applySubscriptionEvent = internalMutation({
  args: {
    projectId: v.id("projects"),
    eventId: v.id("webhookEvents"),
  },
  returns: v.object({
    transition: v.union(v.string(), v.null()),
    active: v.boolean(),
    subscriptionId: v.optional(v.id("subscriptions")),
  }),
  handler: async (ctx, args) => applySubscriptionEventHandler(ctx, args),
});

export async function applySubscriptionEventHandler(
  ctx: MutationCtx,
  args: ApplySubscriptionEventArgs,
): Promise<ApplySubscriptionEventResult> {
  const project = await assertProjectWritable(ctx, args.projectId);
  const storedEvent = await ctx.db.get(args.eventId);
  if (!storedEvent || storedEvent.projectId !== args.projectId) {
    throw new Error("Webhook event not found for project");
  }

  const now = Date.now();
  if (storedEvent.productKind === "one_time") {
    if (storedEvent.appliedAt === undefined) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
    }
    return { transition: null, active: false };
  }
  if (!storedEvent.purchaseToken) {
    if (storedEvent.appliedAt === undefined) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
    }
    return { transition: null, active: false };
  }

  const supersedingResolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    storedEvent.purchaseToken,
  );
  const existingByCurrentToken = supersedingResolution.aliased
    ? null
    : await findSubscriptionByToken(
        ctx,
        args.projectId,
        storedEvent.purchaseToken,
      );
  if (supersedingResolution.aliased) {
    const supersedingSubscription = supersedingResolution.subscription;
    const aliasedTransition =
      storedEvent.type === "PurchaseRefunded"
        ? ("Refunded" as const)
        : storedEvent.type === "SubscriptionRevoked"
          ? ("Revoked" as const)
          : null;
    const active = supersedingSubscription
      ? isActive(supersedingSubscription, now)
      : false;
    const firstApplication = storedEvent.appliedAt === undefined;
    if (firstApplication) {
      if (supersedingSubscription && aliasedTransition) {
        const predecessorProductId =
          storedEvent.productId ?? supersedingResolution.productId;
        await emitCommerceEvent(ctx, {
          projectId: args.projectId,
          transition: aliasedTransition,
          active: false,
          previouslyActive: false,
          sourceEvent: {
            ...storedEvent,
            productId: predecessorProductId,
          },
          ...(predecessorProductId
            ? {
                subscription: {
                  state: aliasedTransition,
                  productId: predecessorProductId,
                  ...(supersedingSubscription.userId
                    ? { userId: supersedingSubscription.userId }
                    : {}),
                },
              }
            : {}),
        });
      }
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
    }
    return {
      transition: firstApplication ? aliasedTransition : null,
      active,
      ...(supersedingSubscription
        ? { subscriptionId: supersedingSubscription._id }
        : {}),
    };
  }
  const linkedResolution = storedEvent.linkedPurchaseToken
    ? await findSupersedingSubscription(
        ctx,
        args.projectId,
        storedEvent.linkedPurchaseToken,
      )
    : ({ aliased: false } as const);
  const linkedExact =
    storedEvent.linkedPurchaseToken && !linkedResolution.aliased
      ? await findSubscriptionByToken(
          ctx,
          args.projectId,
          storedEvent.linkedPurchaseToken,
        )
      : null;
  if (linkedResolution.aliased && !linkedResolution.subscription) {
    if (storedEvent.appliedAt === undefined) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
    }
    return { transition: null, active: false };
  }
  const linkedExisting =
    linkedExact ??
    (linkedResolution.aliased ? linkedResolution.subscription : null);
  let existing = preferredReplacementSnapshot(
    existingByCurrentToken,
    linkedExisting,
  );
  const priorStoreSnapshot = existingByCurrentToken?.lastEventId
    ? existingByCurrentToken
    : linkedExisting?.lastEventId
      ? linkedExisting
      : null;
  if (storedEvent.appliedAt !== undefined) {
    return {
      transition: null,
      active: existing ? isActive(existing, now) : false,
      ...(existing ? { subscriptionId: existing._id } : {}),
    };
  }

  // A linked-token event can arrive after both tokens already have rows. Keep
  // current-token state, merge predecessor identity/history, and remove the
  // duplicate contribution before applying same-token ordering.
  if (
    existingByCurrentToken &&
    linkedExisting &&
    existingByCurrentToken._id !== linkedExisting._id
  ) {
    // Two accounts on one subscription is a conflict whether or not either row
    // carries an erasure marker; a marker never decides which of them wins.
    if (
      existingByCurrentToken.userId &&
      linkedExisting.userId &&
      existingByCurrentToken.userId !== linkedExisting.userId
    ) {
      throw new ConvexError({
        code: "SUBSCRIPTION_USER_CONFLICT",
        message: "Linked Google purchase tokens belong to different users.",
      });
    }
    // The marker records that the row's own owner was erased. A live binding on
    // either row is a later, valid association, so it survives the merge and
    // the marker does not carry.
    const boundUserId =
      existingByCurrentToken.userId ?? linkedExisting.userId ?? undefined;
    const accountErased =
      !boundUserId &&
      (existingByCurrentToken.accountErased === true ||
        linkedExisting.accountErased === true);
    const survivor = preferredReplacementSnapshot(
      existingByCurrentToken,
      linkedExisting,
    )!;
    const removed =
      survivor._id === existingByCurrentToken._id
        ? linkedExisting
        : existingByCurrentToken;
    const removedPeriod = await fetchBillingPeriod(
      ctx,
      args.projectId,
      removed.platform,
      removed.productId,
    );
    await applyStatsTransition(
      ctx,
      args.projectId,
      statsContributionFor(removed, removedPeriod, now),
      null,
    );
    await ctx.db.delete(removed._id);
    existing = {
      ...survivor,
      purchaseToken: storedEvent.purchaseToken,
      accountErased: accountErased || undefined,
      userId: boundUserId,
      startedAt: Math.min(survivor.startedAt, removed.startedAt),
    };
    await ctx.db.patch(survivor._id, {
      purchaseToken: existing.purchaseToken,
      accountErased: existing.accountErased,
      userId: existing.userId,
      startedAt: existing.startedAt,
      updatedAt: now,
    });
    await recordSubscriptionTokenAlias(ctx, {
      projectId: args.projectId,
      purchaseToken: removed.purchaseToken,
      successorPurchaseToken: existing.purchaseToken,
      predecessorProductId: removed.productId,
      now,
    });
  }

  // Compare with the last persisted gate; today's clock may already have expired it.
  const previouslyActive = priorStoreSnapshot
    ? isActive(priorStoreSnapshot, priorStoreSnapshot.updatedAt)
    : false;
  const noOpResult = (): ApplySubscriptionEventResult => ({
    transition: null,
    active: existing ? isActive(existing, now) : false,
    ...(existing ? { subscriptionId: existing._id } : {}),
  });

  // Store timestamps only order events for the same purchase token. A linked
  // predecessor can expire after its replacement became active.
  const orderingExisting = existingByCurrentToken;

  // Rollout compatibility for events written before appliedAt existed. The
  // current last event proves itself applied; an event older than the current
  // last event must be marked handled without being allowed to roll state
  // backwards. Store timestamps are only millisecond-precision, so ingestion
  // order breaks ties between distinct same-timestamp events. A recorded-but-
  // unapplied newest event still falls through and repairs the original
  // action/mutation gap.
  if (
    orderingExisting?.lastEventSourceNotificationId ===
    storedEvent.sourceNotificationId
  ) {
    await ctx.db.patch(storedEvent._id, { appliedAt: now });
    return noOpResult();
  }
  if (orderingExisting?.lastEventOccurredAt !== undefined) {
    const stale =
      orderingExisting.lastEventOccurredAt > storedEvent.occurredAt ||
      (orderingExisting.lastEventOccurredAt === storedEvent.occurredAt &&
        (orderingExisting.lastEventCreationTime ?? 0) >
          storedEvent._creationTime);
    if (stale) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
      return noOpResult();
    }
  } else if (orderingExisting?.lastEventId) {
    if (orderingExisting.lastEventId === args.eventId) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
      return noOpResult();
    }
    const lastEvent = await ctx.db.get(orderingExisting.lastEventId);
    if (
      lastEvent?.projectId === args.projectId &&
      lastEvent.purchaseToken === storedEvent.purchaseToken &&
      lastEvent.platform === storedEvent.platform &&
      (lastEvent.occurredAt > storedEvent.occurredAt ||
        (lastEvent.occurredAt === storedEvent.occurredAt &&
          lastEvent._creationTime > storedEvent._creationTime))
    ) {
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
      return noOpResult();
    }
  }

  // Google subscription bundles can report ITEMS_CHANGED without identifying
  // which line item changed. Keep the raw event for operations, but never
  // overwrite the singular canonical product with an arbitrary bundle item.
  // Linked replacements still move the canonical row after the ordering guard.
  if (
    storedEvent.type === "SubscriptionProductChanged" &&
    !storedEvent.productId
  ) {
    if (existing) {
      const verifiedReplacementProductChanged =
        existingByCurrentToken?.lastEventId === undefined &&
        priorStoreSnapshot !== null &&
        priorStoreSnapshot.productId !== existing.productId;
      const subscriptionId = await persistSubscriptionSnapshot(ctx, {
        projectId: args.projectId,
        platform: existing.platform,
        purchaseToken: storedEvent.purchaseToken,
        existing,
        next: {
          state: existing.state,
          productId: existing.productId,
          expiresAt: existing.expiresAt,
          renewsAt: existing.renewsAt,
          willRenew: existing.willRenew,
          cancellationReason: existing.cancellationReason,
          currency: existing.currency,
          priceAmountMicros: existing.priceAmountMicros,
        },
        now,
        lastEvent: storedEvent,
      });
      await recordSubscriptionTokenAlias(ctx, {
        projectId: args.projectId,
        purchaseToken: existing.purchaseToken,
        successorPurchaseToken: storedEvent.purchaseToken,
        predecessorProductId: existing.productId,
        now,
      });
      await recordSubscriptionTokenAlias(ctx, {
        projectId: args.projectId,
        purchaseToken: storedEvent.linkedPurchaseToken,
        successorPurchaseToken: storedEvent.purchaseToken,
        predecessorProductId:
          priorStoreSnapshot?.productId ?? existing.productId,
        now,
      });
      await ctx.db.patch(storedEvent._id, { appliedAt: now });
      const active = isActive(existing, now);
      if (verifiedReplacementProductChanged) {
        await emitCommerceEvent(ctx, {
          projectId: args.projectId,
          transition: "ProductChanged",
          active,
          previouslyActive: active,
          sourceEvent: storedEvent,
          subscriptionId,
          previousProductId: priorStoreSnapshot.productId,
          subscription: {
            state: existing.state,
            productId: existing.productId,
            ...(existing.expiresAt !== undefined
              ? { expiresAt: existing.expiresAt }
              : {}),
            ...(existing.renewsAt !== undefined
              ? { renewsAt: existing.renewsAt }
              : {}),
            ...(existing.willRenew !== undefined
              ? { willRenew: existing.willRenew }
              : {}),
            ...(existing.cancellationReason
              ? { cancellationReason: existing.cancellationReason }
              : {}),
            ...(existing.userId ? { userId: existing.userId } : {}),
          },
        });
      }
      return {
        transition: verifiedReplacementProductChanged ? "ProductChanged" : null,
        active,
        subscriptionId,
      };
    }
    await ctx.db.patch(storedEvent._id, { appliedAt: now });
    return noOpResult();
  }

  const current: CurrentSubscription = existing
    ? {
        state: existing.state,
        productId: existing.productId,
        expiresAt: existing.expiresAt,
        renewsAt: existing.renewsAt,
        willRenew: existing.willRenew,
        cancellationReason: existing.cancellationReason,
        currency: existing.currency,
        priceAmountMicros: existing.priceAmountMicros,
      }
    : null;
  const event: RawEventInput = {
    type: storedEvent.type,
    productId: storedEvent.productId,
    subscriptionState: storedEvent.subscriptionState,
    expiresAt: storedEvent.expiresAt,
    renewsAt: storedEvent.renewsAt,
    willRenew: storedEvent.willRenew,
    cancellationReason: storedEvent.cancellationReason,
    currency: storedEvent.currency,
    priceAmountMicros: storedEvent.priceAmountMicros,
    platform: storedEvent.platform,
    effectiveImmediately: storedEvent.effectiveImmediately,
    purchaseToken: storedEvent.purchaseToken,
  };
  const transition = applySubscriptionTransition(
    current,
    coerceEventInput(event),
  );
  const linkedStartedOnActivePredecessor =
    storedEvent.type === "SubscriptionStarted" &&
    storedEvent.linkedPurchaseToken !== undefined &&
    priorStoreSnapshot !== null &&
    previouslyActive;
  const effectiveTransition = linkedStartedOnActivePredecessor
    ? transition.next?.productId !== priorStoreSnapshot.productId
      ? "ProductChanged"
      : priorStoreSnapshot.willRenew === false &&
          transition.next?.willRenew === true
        ? "Uncanceled"
        : transition.next?.expiresAt !== undefined &&
            priorStoreSnapshot.expiresAt !== undefined &&
            transition.next.expiresAt > priorStoreSnapshot.expiresAt
          ? "Renewed"
          : null
    : transition.transition;
  const firstStoreEventAfterVerification =
    storedEvent.type === "SubscriptionStarted" &&
    existing !== null &&
    existing.lastEventId === undefined &&
    priorStoreSnapshot === null;
  // Computed before persistSubscriptionSnapshot stamps lastEvent* onto the
  // row: a record bootstrapped by receipt verification has no store history,
  // so a price change or deferral arriving as its first store event has no
  // baseline to describe. The mapping vectors pin these to no event.
  const priceOrDeferralWithoutBaseline =
    existing !== null &&
    existing.lastEventId === undefined &&
    priorStoreSnapshot === null &&
    (effectiveTransition === "PriceChanged" ||
      effectiveTransition === "Deferred");
  const previousProductId =
    priorStoreSnapshot?.productId ?? existing?.productId;

  if (!transition.next) {
    await ctx.db.patch(storedEvent._id, { appliedAt: now });
    return {
      transition: transition.transition ?? null,
      active: false,
      ...(existing ? { subscriptionId: existing._id } : {}),
    };
  }

  const subscriptionId = await persistSubscriptionSnapshot(ctx, {
    projectId: args.projectId,
    platform: event.platform,
    purchaseToken: event.purchaseToken,
    existing,
    next: transition.next,
    now,
    lastEvent: storedEvent,
  });
  await recordSubscriptionTokenAlias(ctx, {
    projectId: args.projectId,
    purchaseToken: existing?.purchaseToken,
    successorPurchaseToken: storedEvent.purchaseToken,
    predecessorProductId: existing?.productId,
    now,
  });
  await recordSubscriptionTokenAlias(ctx, {
    projectId: args.projectId,
    purchaseToken: storedEvent.linkedPurchaseToken,
    successorPurchaseToken: storedEvent.purchaseToken,
    predecessorProductId: priorStoreSnapshot?.productId ?? existing?.productId,
    now,
  });
  await ctx.db.patch(storedEvent._id, { appliedAt: now });
  const active = entitlementActive(transition.next, now);
  // A record bootstrapped by receipt verification has no store history, so a
  // price change or deferral arriving as its first store event has no
  // baseline to describe. The mapping vectors pin these to no event.
  const commerceTransition = linkedStartedOnActivePredecessor
    ? effectiveTransition
    : firstStoreEventAfterVerification
      ? "Started"
      : priceOrDeferralWithoutBaseline
        ? null
        : effectiveTransition;
  await emitCommerceEvent(ctx, {
    projectId: args.projectId,
    transition: commerceTransition ?? null,
    active,
    previouslyActive,
    sourceEvent: storedEvent,
    subscriptionId,
    ...(previousProductId && previousProductId !== transition.next.productId
      ? { previousProductId }
      : {}),
    subscription: {
      state: transition.next.state,
      productId: transition.next.productId,
      ...(transition.next.expiresAt !== undefined
        ? { expiresAt: transition.next.expiresAt }
        : {}),
      ...(transition.next.renewsAt !== undefined
        ? { renewsAt: transition.next.renewsAt }
        : {}),
      ...(transition.next.willRenew !== undefined
        ? { willRenew: transition.next.willRenew }
        : {}),
      ...(transition.next.cancellationReason
        ? { cancellationReason: transition.next.cancellationReason }
        : {}),
      ...(existing?.userId ? { userId: existing.userId } : {}),
    },
  });

  return {
    transition: effectiveTransition ?? null,
    active,
    subscriptionId,
  };
}

export function buildVerifiedSubscriptionSnapshot(
  input: VerifiedSubscriptionInput,
): VerifiedSubscriptionSnapshot | null {
  if (input.productId.length === 0 || input.productId === "unknown") {
    return null;
  }
  if (input.purchaseState === HarmonizedPurchaseState.INAUTHENTIC) return null;

  const base: Pick<
    VerifiedSubscriptionSnapshot,
    | "productId"
    | "expiresAt"
    | "renewsAt"
    | "willRenew"
    | "currency"
    | "priceAmountMicros"
  > = {
    productId: input.productId,
    expiresAt: input.expiresAt,
    renewsAt: input.renewsAt,
    willRenew: input.willRenew,
    currency: input.currency,
    priceAmountMicros: input.priceAmountMicros,
  };

  if (input.platform === "IOS") {
    switch (input.purchaseState) {
      case HarmonizedPurchaseState.ENTITLED:
        return {
          ...base,
          state: "Active",
          cancellationReason: undefined,
          clearCancellationReason: true,
        };
      case HarmonizedPurchaseState.EXPIRED:
        return {
          ...base,
          state: "Expired",
          willRenew: false,
        };
      case HarmonizedPurchaseState.CANCELED:
        return {
          ...base,
          state: "Revoked",
          willRenew: false,
          // Apple's revocationReason field covers a transaction "refunded
          // ... or revoked from family sharing": value 1 is unambiguously a
          // refund, while 0 also covers Family Sharing loss. Mirroring the
          // webhook REVOKE policy, only the unambiguous value asserts money
          // moved back; webhook REFUND notifications carry the rest.
          ...(input.revocationReasonIOS === 1
            ? { cancellationReason: "Refunded" as const }
            : {}),
        };
      case HarmonizedPurchaseState.PENDING_ACKNOWLEDGMENT:
      case HarmonizedPurchaseState.PENDING:
      case HarmonizedPurchaseState.UNKNOWN:
        return {
          ...base,
          state: "Unknown",
        };
      case HarmonizedPurchaseState.READY_TO_CONSUME:
      case HarmonizedPurchaseState.CONSUMED:
        return null;
    }
  }

  switch (input.purchaseState) {
    case HarmonizedPurchaseState.UNKNOWN:
      return {
        ...base,
        state: "Unknown",
      };
    case HarmonizedPurchaseState.EXPIRED:
      return {
        ...base,
        state: "Expired",
        willRenew: false,
      };
    case HarmonizedPurchaseState.READY_TO_CONSUME:
    case HarmonizedPurchaseState.CONSUMED:
      return null;
    case HarmonizedPurchaseState.ENTITLED:
    case HarmonizedPurchaseState.CANCELED:
      break;
  }

  switch (input.subscriptionState?.toUpperCase()) {
    case "SUBSCRIPTION_STATE_ACTIVE":
      return {
        ...base,
        state: "Active",
        willRenew: input.willRenew ?? true,
        cancellationReason: undefined,
        clearCancellationReason: true,
      };
    case "SUBSCRIPTION_STATE_CANCELED":
      return {
        ...base,
        state: "Active",
        willRenew: false,
      };
    case "SUBSCRIPTION_STATE_IN_GRACE_PERIOD":
      return {
        ...base,
        state: "InGracePeriod",
        willRenew: input.willRenew ?? true,
        cancellationReason: undefined,
        clearCancellationReason: true,
      };
    case "SUBSCRIPTION_STATE_ON_HOLD":
      return {
        ...base,
        state: "InBillingRetry",
        cancellationReason: "BillingError",
      };
    case "SUBSCRIPTION_STATE_PAUSED":
      return {
        ...base,
        state: "Paused",
        willRenew: false,
      };
    case "SUBSCRIPTION_STATE_EXPIRED":
      return {
        ...base,
        state: "Expired",
        willRenew: false,
      };
    case "SUBSCRIPTION_STATE_PENDING":
      return {
        ...base,
        state: "Unknown",
      };
  }

  return {
    ...base,
    state:
      input.purchaseState === HarmonizedPurchaseState.ENTITLED ||
      input.purchaseState === HarmonizedPurchaseState.PENDING_ACKNOWLEDGMENT
        ? "Active"
        : "Unknown",
  };
}

export function mergeVerifiedSubscriptionSnapshot(
  existing: ExistingSubscriptionSnapshotFields | null,
  snapshot: VerifiedSubscriptionSnapshot,
): VerifiedSubscriptionSnapshot {
  if (!existing) return snapshot;

  return {
    ...snapshot,
    expiresAt: snapshot.expiresAt ?? existing.expiresAt,
    renewsAt:
      snapshot.willRenew === false
        ? undefined
        : (snapshot.renewsAt ?? existing.renewsAt),
    willRenew: snapshot.willRenew ?? existing.willRenew,
    cancellationReason:
      snapshot.cancellationReason !== undefined ||
      snapshot.clearCancellationReason
        ? snapshot.cancellationReason
        : existing.cancellationReason,
    currency: snapshot.currency ?? existing.currency,
    priceAmountMicros: snapshot.priceAmountMicros ?? existing.priceAmountMicros,
  };
}

// Receipt verification is the synchronous bootstrap path for
// subscriptions. Webhooks keep lifecycle state fresh later, but a
// successful verify must be enough for SDK clients to bind the just-
// purchased token to their app user.
export const recordVerifiedSubscription = internalMutation({
  args: {
    projectId: v.id("projects"),
    platform: subscriptionPlatformValidator,
    purchaseToken: v.string(),
    productId: v.string(),
    purchaseState: v.string(),
    subscriptionState: v.optional(v.string()),
    expiresAt: v.optional(v.number()),
    renewsAt: v.optional(v.number()),
    willRenew: v.optional(v.boolean()),
    currency: v.optional(v.string()),
    priceAmountMicros: v.optional(v.number()),
    revocationReasonIOS: v.optional(v.number()),
  },
  returns: v.union(v.id("subscriptions"), v.null()),
  handler: async (ctx, args) => recordVerifiedSubscriptionHandler(ctx, args),
});

export async function recordVerifiedSubscriptionHandler(
  ctx: MutationCtx,
  args: RecordVerifiedSubscriptionArgs,
): Promise<Id<"subscriptions"> | null> {
  await assertProjectWritable(ctx, args.projectId);
  const snapshot = buildVerifiedSubscriptionSnapshot({
    platform: args.platform,
    productId: args.productId,
    purchaseState: normalizeHarmonizedPurchaseState(args.purchaseState),
    subscriptionState: args.subscriptionState,
    expiresAt: args.expiresAt,
    renewsAt: args.renewsAt,
    willRenew: args.willRenew,
    currency: args.currency,
    priceAmountMicros: args.priceAmountMicros,
    revocationReasonIOS: args.revocationReasonIOS,
  });
  if (!snapshot) return null;

  const supersedingResolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  if (supersedingResolution.aliased) {
    return supersedingResolution.subscription?._id ?? null;
  }
  const existing = await findSubscriptionByToken(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  // Verification bootstraps a token before server notifications arrive. Once
  // a store event governs the row, a client can replay an older but still-valid
  // transaction; without comparable ordering metadata that snapshot must not
  // roll canonical product, state, or expiry backward.
  if (existing?.lastEventId) return existing._id;
  const now = Date.now();

  const next = mergeVerifiedSubscriptionSnapshot(existing, snapshot);
  return persistSubscriptionSnapshot(ctx, {
    projectId: args.projectId,
    platform: args.platform,
    purchaseToken: args.purchaseToken,
    existing,
    next,
    now,
  });
}

async function persistSubscriptionSnapshot(
  ctx: MutationCtx,
  args: PersistSubscriptionSnapshotArgs,
): Promise<Id<"subscriptions">> {
  // Stats deltas must compare the old row against the old catalog entry
  // and the new row against the new one; otherwise product/platform changes
  // subtract the wrong MRR bucket.
  const afterBillingPeriod = await fetchBillingPeriod(
    ctx,
    args.projectId,
    args.platform,
    args.next.productId,
  );
  const beforeBillingPeriod =
    args.existing &&
    (args.existing.productId !== args.next.productId ||
      args.existing.platform !== args.platform)
      ? await fetchBillingPeriod(
          ctx,
          args.projectId,
          args.existing.platform,
          args.existing.productId,
        )
      : afterBillingPeriod;
  const beforeContribution = args.existing
    ? statsContributionFor(args.existing, beforeBillingPeriod, args.now)
    : null;

  const row = {
    purchaseToken: args.purchaseToken,
    productKind: "subscription" as const,
    ...(args.existing?.userId ? { userId: args.existing.userId } : {}),
    productId: args.next.productId,
    platform: args.platform,
    state: args.next.state,
    expiresAt: args.next.expiresAt,
    renewsAt: args.next.renewsAt,
    willRenew: args.next.willRenew,
    cancellationReason: args.next.cancellationReason,
    currency: args.next.currency,
    priceAmountMicros: args.next.priceAmountMicros,
    updatedAt: args.now,
    ...(args.lastEvent
      ? {
          lastEventId: args.lastEvent._id,
          lastEventOccurredAt: args.lastEvent.occurredAt,
          lastEventCreationTime: args.lastEvent._creationTime,
          lastEventSourceNotificationId: args.lastEvent.sourceNotificationId,
          lastEventSource: {
            type: args.lastEvent.type,
            environment: args.lastEvent.environment,
            productId: args.lastEvent.productId,
            applicationId: args.lastEvent.applicationId,
            transactionId: args.lastEvent.transactionId,
            originalTransactionId: args.lastEvent.originalTransactionId,
            currency: args.lastEvent.currency,
            priceAmountMicros: args.lastEvent.priceAmountMicros,
          },
        }
      : {}),
  };

  const subscriptionId = args.existing
    ? args.existing._id
    : await ctx.db.insert("subscriptions", {
        projectId: args.projectId,
        startedAt: args.now,
        ...row,
      });

  if (args.existing) {
    await ctx.db.patch(args.existing._id, row);
  }

  const updatedRow = (await ctx.db.get(subscriptionId))!;
  const afterContribution = statsContributionFor(
    updatedRow,
    afterBillingPeriod,
    args.now,
  );
  await applyStatsTransition(
    ctx,
    args.projectId,
    beforeContribution,
    afterContribution,
  );

  return subscriptionId;
}

function findSubscriptionByToken(
  ctx: Pick<QueryCtx, "db">,
  projectId: Id<"projects">,
  purchaseToken: string,
): Promise<Doc<"subscriptions"> | null> {
  return ctx.db
    .query("subscriptions")
    .withIndex("by_project_and_token", (q) =>
      q.eq("projectId", projectId).eq("purchaseToken", purchaseToken),
    )
    .unique();
}

const MAX_SUBSCRIPTION_TOKEN_ALIAS_HOPS = 64;

type SupersedingSubscriptionResolution =
  | { aliased: false }
  | {
      aliased: true;
      subscription: Doc<"subscriptions"> | null;
      productId?: string;
    };

async function findSupersedingSubscription(
  ctx: Pick<QueryCtx, "db">,
  projectId: Id<"projects">,
  purchaseToken: string,
): Promise<SupersedingSubscriptionResolution> {
  let token = purchaseToken;
  let productId: string | undefined;
  const seen = new Set<string>([token]);
  for (let hop = 0; hop <= MAX_SUBSCRIPTION_TOKEN_ALIAS_HOPS; hop += 1) {
    const alias = await ctx.db
      .query("subscriptionTokenAliases")
      .withIndex("by_project_and_token", (q) =>
        q.eq("projectId", projectId).eq("purchaseToken", token),
      )
      .unique();
    if (!alias) {
      return hop === 0
        ? { aliased: false }
        : {
            aliased: true,
            subscription: await findSubscriptionByToken(ctx, projectId, token),
            productId,
          };
    }
    if (hop === 0) productId = alias.predecessorProductId;
    if (hop === MAX_SUBSCRIPTION_TOKEN_ALIAS_HOPS) {
      return { aliased: true, subscription: null, productId };
    }
    if (seen.has(alias.successorPurchaseToken)) {
      return { aliased: true, subscription: null, productId };
    }
    token = alias.successorPurchaseToken;
    seen.add(token);
  }
  return { aliased: true, subscription: null, productId };
}

async function recordSubscriptionTokenAlias(
  ctx: MutationCtx,
  args: {
    projectId: Id<"projects">;
    purchaseToken?: string;
    successorPurchaseToken: string;
    predecessorProductId?: string;
    now: number;
  },
): Promise<void> {
  if (
    !args.purchaseToken ||
    args.purchaseToken === args.successorPurchaseToken
  ) {
    return;
  }
  const existing = await ctx.db
    .query("subscriptionTokenAliases")
    .withIndex("by_project_and_token", (q) =>
      q
        .eq("projectId", args.projectId)
        .eq("purchaseToken", args.purchaseToken as string),
    )
    .unique();
  if (existing) {
    if (existing.successorPurchaseToken !== args.successorPurchaseToken) {
      await ctx.db.patch(existing._id, {
        successorPurchaseToken: args.successorPurchaseToken,
        predecessorProductId:
          existing.predecessorProductId ?? args.predecessorProductId,
        updatedAt: args.now,
      });
    }
    return;
  }
  await ctx.db.insert("subscriptionTokenAliases", {
    projectId: args.projectId,
    purchaseToken: args.purchaseToken,
    successorPurchaseToken: args.successorPurchaseToken,
    predecessorProductId: args.predecessorProductId,
    createdAt: args.now,
    updatedAt: args.now,
  });
}

function preferredReplacementSnapshot(
  current: Doc<"subscriptions"> | null,
  linked: Doc<"subscriptions"> | null,
): Doc<"subscriptions"> | null {
  if (!current) return linked;
  // Store timestamps from predecessor and replacement tokens are not a total
  // order: the predecessor can expire after the replacement becomes active.
  // Current-token state therefore wins even when it came from verification;
  // user identity and start history are merged separately during reconciliation.
  return current;
}

export const getSourceProductIdByToken = internalQuery({
  args: {
    projectId: v.id("projects"),
    purchaseToken: v.string(),
  },
  returns: v.union(v.string(), v.null()),
  handler: async (ctx, args) => getSourceProductIdByTokenHandler(ctx, args),
});

export async function getSourceProductIdByTokenHandler(
  ctx: Pick<QueryCtx, "db">,
  args: { projectId: Id<"projects">; purchaseToken: string },
): Promise<string | null> {
  const resolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  if (resolution.aliased) return resolution.productId ?? null;
  const subscription = await findSubscriptionByToken(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  return subscription?.productId ?? null;
}

export const getCurrentProductIdByToken = internalQuery({
  args: {
    projectId: v.id("projects"),
    purchaseToken: v.string(),
  },
  returns: v.union(v.string(), v.null()),
  handler: async (ctx, args) => getCurrentProductIdByTokenHandler(ctx, args),
});

export async function getCurrentProductIdByTokenHandler(
  ctx: Pick<QueryCtx, "db">,
  args: { projectId: Id<"projects">; purchaseToken: string },
): Promise<string | null> {
  const resolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  if (resolution.aliased) return resolution.subscription?.productId ?? null;
  const subscription = await findSubscriptionByToken(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  return subscription?.productId ?? null;
}

// Look up a product's billing period from the kit-side catalog. We
// Look up the row for the EXACT (platform, productId) — `products` is
// keyed by (projectId, platform, productId) precisely because the
// same SKU can exist on both stores with different billing periods.
// Earlier behaviour preferred iOS over Android by walking both
// platforms, which made an Android subscription inherit the iOS
// period when those rows diverged and skewed `mrrMicros` on both the
// incremental delta and the next recompute (PR #124
// (https://github.com/hyodotdev/openiap/pull/124) review). Returns
// undefined when the product isn't tracked or has no billingPeriod —
// monthlyMicrosForSub treats that as a P1M fallback.
async function fetchBillingPeriod(
  ctx: MutationCtx,
  projectId: Id<"projects">,
  platform: SubscriptionPlatform,
  productId: string,
): Promise<string | undefined> {
  const product = await ctx.db
    .query("products")
    .withIndex("by_project_and_platform_and_product", (q) =>
      q
        .eq("projectId", projectId)
        .eq("platform", platform)
        .eq("productId", productId),
    )
    .unique();
  return product?.billingPeriod ?? undefined;
}

function coerceEventInput(raw: RawEventInput): SubscriptionEventInput {
  const appleRenewalPreference =
    raw.platform === "IOS" &&
    raw.type === "SubscriptionProductChanged" &&
    raw.effectiveImmediately !== true;
  return {
    type: raw.type,
    // Apple's renewal preference is the product for the next billing period;
    // the current transaction remains active until then. Keep the target on
    // the source event, but do not replace the canonical subscription early.
    productId: appleRenewalPreference ? undefined : raw.productId,
    subscriptionState: raw.subscriptionState,
    expiresAt: raw.expiresAt,
    renewsAt: raw.renewsAt,
    willRenew: raw.willRenew,
    cancellationReason: raw.cancellationReason,
    currency: appleRenewalPreference ? undefined : raw.currency,
    priceAmountMicros: appleRenewalPreference
      ? undefined
      : raw.priceAmountMicros,
  };
}

function isActive(
  sub: Doc<"subscriptions">,
  now: number = Date.now(),
): boolean {
  return entitlementActive(sub, now);
}

function normalizeHarmonizedPurchaseState(
  state: string,
): HarmonizedPurchaseState {
  const normalized = state.trim().toUpperCase().replace(/-/g, "_");
  if (normalized in HarmonizedPurchaseState) {
    return HarmonizedPurchaseState[
      normalized as keyof typeof HarmonizedPurchaseState
    ];
  }
  return HarmonizedPurchaseState.UNKNOWN;
}

// Bind a subscription to a userId. Called by the SDK after a successful
// receipt validation when the host app knows which user owns the receipt.
export const bindSubscriptionToUser = internalMutation({
  args: {
    projectId: v.id("projects"),
    purchaseToken: v.string(),
    userId: v.string(),
  },
  returns: v.union(v.id("subscriptions"), v.null()),
  handler: async (ctx, args) => bindSubscriptionToUserHandler(ctx, args),
});

/**
 * The retained source a re-emitted entitlement event is attributed to. The
 * stored row is preferred; a pruned one is reconstructed from the snapshot the
 * subscription keeps. Price is stripped: a webhook already reported it, and
 * repeating it would put the same money on another event.
 */
async function retainedSourceEventFor(
  ctx: MutationCtx,
  projectId: Id<"projects">,
  sub: Doc<"subscriptions">,
) {
  if (!sub.lastEventId) return null;
  const retained = await ctx.db.get(sub.lastEventId);
  const source =
    retained?.projectId === projectId
      ? retained
      : sub.lastEventSource &&
          sub.lastEventOccurredAt !== undefined &&
          sub.lastEventSourceNotificationId
        ? {
            _id: sub.lastEventId,
            type: sub.lastEventSource.type,
            platform: sub.platform,
            environment: sub.lastEventSource.environment,
            productId: sub.lastEventSource.productId,
            applicationId: sub.lastEventSource.applicationId,
            transactionId: sub.lastEventSource.transactionId,
            originalTransactionId: sub.lastEventSource.originalTransactionId,
            sourceNotificationId: sub.lastEventSourceNotificationId,
            occurredAt: sub.lastEventOccurredAt,
          }
        : null;
  if (!source) return null;
  return {
    ...source,
    currency: undefined,
    priceAmountMicros: undefined,
    amountProvenance: undefined,
  };
}

/**
 * Moves an existing binding. `bindSubscriptionToUserHandler` refuses this on
 * purpose — a caller holding a purchase token has not proved it owns the
 * purchase — so correcting a wrong binding needs an operator-authorized path.
 * Callers must gate this on a secret key.
 */
export async function rebindSubscriptionToUserHandler(
  ctx: MutationCtx,
  args: BindSubscriptionToUserArgs,
): Promise<{ subscriptionId: Id<"subscriptions">; notified: boolean } | null> {
  if (!isValidSubscriptionUserId(args.userId)) {
    throw new ConvexError("userId must be nonblank and at most 256 characters");
  }
  const project = await assertProjectWritable(ctx, args.projectId);
  if (await isUserErasureRequested(ctx, project, args.userId)) return null;
  // Resolve exactly as `bind` does. An operator correcting a wrong binding
  // usually has the token the customer reported, which on Play may be the one
  // a replacement superseded.
  const supersedingResolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  const sub = supersedingResolution.aliased
    ? supersedingResolution.subscription
    : await findSubscriptionByToken(ctx, args.projectId, args.purchaseToken);
  if (!sub) return null;
  if (
    sub.userId &&
    sub.userId !== args.userId &&
    (await isUserErasureRequested(ctx, project, sub.userId))
  )
    return null;
  if (sub.userId === args.userId) {
    return { subscriptionId: sub._id, notified: true };
  }
  const previousUserId = sub.userId;
  const now = Date.now();

  // A consumer that gates access on commerce events has no other way to learn
  // the purchase moved: without these it keeps the wrong user entitled and
  // never entitles the real one. Decide before writing, so the caller is never
  // told a rebind succeeded when the notification half of it could not.
  const entitled = isActive({ ...sub, userId: args.userId }, now);
  const sourceEvent = entitled
    ? await retainedSourceEventFor(ctx, args.projectId, sub)
    : null;
  await ctx.db.patch(sub._id, {
    userId: args.userId,
    accountErased: undefined,
    updatedAt: now,
  });
  if (!entitled) return { subscriptionId: sub._id, notified: true };
  if (!sourceEvent) {
    // Every retained trace of the originating notification is gone, so no
    // event can be attributed. The binding moved; the operator must reconcile
    // the developer backend by hand.
    console.warn(
      "[subscriptions/rebind] moved a binding without emitting entitlement events",
      { projectId: args.projectId, subscriptionId: sub._id },
    );
    return { subscriptionId: sub._id, notified: false };
  }
  const snapshot = {
    state: sub.state,
    productId: sub.productId,
    ...(sub.expiresAt !== undefined ? { expiresAt: sub.expiresAt } : {}),
    ...(sub.renewsAt !== undefined ? { renewsAt: sub.renewsAt } : {}),
    ...(sub.willRenew !== undefined ? { willRenew: sub.willRenew } : {}),
    ...(sub.cancellationReason
      ? { cancellationReason: sub.cancellationReason }
      : {}),
  };
  for (const [userId, active, previouslyActive] of [
    ...(previousUserId
      ? ([[previousUserId, false, true]] as const)
      : ([] as const)),
    [args.userId, true, false] as const,
  ]) {
    await emitCommerceEvent(ctx, {
      projectId: args.projectId,
      transition: null,
      active,
      previouslyActive,
      sourceEvent,
      subscriptionId: sub._id,
      subscription: { ...snapshot, userId },
    });
  }
  return { subscriptionId: sub._id, notified: true };
}

export async function bindSubscriptionToUserHandler(
  ctx: MutationCtx,
  args: BindSubscriptionToUserArgs,
): Promise<Id<"subscriptions"> | null> {
  if (!isValidSubscriptionUserId(args.userId)) {
    throw new ConvexError("userId must be nonblank and at most 256 characters");
  }
  const project = await assertProjectWritable(ctx, args.projectId);
  if (await isUserErasureRequested(ctx, project, args.userId)) return null;
  const supersedingResolution = await findSupersedingSubscription(
    ctx,
    args.projectId,
    args.purchaseToken,
  );
  const sub = supersedingResolution.aliased
    ? supersedingResolution.subscription
    : await findSubscriptionByToken(ctx, args.projectId, args.purchaseToken);
  if (!sub) return null;
  if (sub.userId === args.userId) return sub._id;
  if (sub.userId) {
    // Reported the same as an unknown token. A distinct error would tell any
    // holder of the app-embedded publishable key whether a token exists and
    // whether someone owns it. The operator still sees the collision.
    console.warn(
      "[subscriptions/bind] rejected a bind for an already-bound subscription",
      { projectId: args.projectId, subscriptionId: sub._id },
    );
    return null;
  }
  const now = Date.now();
  // Erasure only unlinked the previous owner; this is a new association, and
  // the pending-erasure gate above still refuses a user who is being erased.
  await ctx.db.patch(sub._id, {
    userId: args.userId,
    accountErased: undefined,
    updatedAt: now,
  });

  // If the store webhook won the race against verify/bind, its initial event
  // had no account identity. Emit one correlated entitlement grant after the
  // binding so a developer backend never has to recover a purchase token from
  // the public payload. The normal verify -> bind -> webhook path has no
  // lastEventId yet and emits its grant when that first webhook arrives.
  if (sub.lastEventId && isActive(sub, now)) {
    const retainedSource = await ctx.db.get(sub.lastEventId);
    const sourceEvent =
      retainedSource?.projectId === args.projectId
        ? retainedSource
        : sub.lastEventSource &&
            sub.lastEventOccurredAt !== undefined &&
            sub.lastEventSourceNotificationId
          ? {
              _id: sub.lastEventId,
              type: sub.lastEventSource.type,
              platform: sub.platform,
              environment: sub.lastEventSource.environment,
              productId: sub.lastEventSource.productId,
              applicationId: sub.lastEventSource.applicationId,
              transactionId: sub.lastEventSource.transactionId,
              originalTransactionId: sub.lastEventSource.originalTransactionId,
              currency: sub.lastEventSource.currency,
              priceAmountMicros: sub.lastEventSource.priceAmountMicros,
              sourceNotificationId: sub.lastEventSourceNotificationId,
              occurredAt: sub.lastEventOccurredAt,
            }
          : null;
    if (sourceEvent) {
      // This only fires after a webhook already emitted the notification's
      // amount, so repeating it would put the same money on a second event.
      const entitlementSource = {
        ...sourceEvent,
        currency: undefined,
        priceAmountMicros: undefined,
        amountProvenance: undefined,
      };
      await emitCommerceEvent(ctx, {
        projectId: args.projectId,
        transition: null,
        active: true,
        previouslyActive: false,
        sourceEvent: entitlementSource,
        subscriptionId: sub._id,
        subscription: {
          state: sub.state,
          productId: sub.productId,
          ...(sub.expiresAt !== undefined ? { expiresAt: sub.expiresAt } : {}),
          ...(sub.renewsAt !== undefined ? { renewsAt: sub.renewsAt } : {}),
          ...(sub.willRenew !== undefined ? { willRenew: sub.willRenew } : {}),
          ...(sub.cancellationReason
            ? { cancellationReason: sub.cancellationReason }
            : {}),
          userId: args.userId,
        },
      });
    }
  }
  return sub._id;
}

export async function drainSubscriptionUserErasurePage(
  ctx: MutationCtx,
  jobId: Id<"subscriptionUserErasureJobs">,
): Promise<{
  done: boolean;
  subscriptionsErased: number;
  commerceEventsErased: number;
}> {
  const job = await ctx.db.get(jobId);
  if (!job || job.status === "completed" || !job.userId) {
    return {
      done: true,
      subscriptionsErased: job?.subscriptionsErased ?? 0,
      commerceEventsErased: job?.commerceEventsErased ?? 0,
    };
  }

  const now = Date.now();
  await ctx.db.patch(jobId, { status: "running", updatedAt: now });
  const [subscriptions, commerceEvents, purchases] = await Promise.all([
    ctx.db
      .query("subscriptions")
      .withIndex("by_project_and_user", (q) =>
        q.eq("projectId", job.projectId).eq("userId", job.userId),
      )
      .take(USER_ERASURE_BATCH_SIZE),
    ctx.db
      .query("commerceEvents")
      .withIndex("by_project_and_user", (q) =>
        q.eq("projectId", job.projectId).eq("userId", job.userId),
      )
      .take(USER_ERASURE_BATCH_SIZE),
    ctx.db
      .query("purchases")
      .withIndex("by_project_and_app_user", (q) =>
        q.eq("projectId", job.projectId).eq("appUserId", job.userId),
      )
      .take(USER_ERASURE_BATCH_SIZE),
  ]);

  for (const subscription of subscriptions) {
    await ctx.db.patch(subscription._id, {
      userId: undefined,
      accountErased: true,
    });
  }
  for (const purchase of purchases) {
    await ctx.db.patch(purchase._id, {
      appUserId: undefined,
      accountErased: true,
    });
  }
  let commerceEventsErasedThisPage = 0;
  let waitingForClaimedDelivery = false;
  for (const event of commerceEvents) {
    const deliveries = await ctx.db
      .query("outboundDeliveries")
      .withIndex("by_event", (q) => q.eq("eventId", event._id))
      .collect();
    if (deliveries.some((delivery) => delivery.status === "delivering")) {
      waitingForClaimedDelivery = true;
      continue;
    }
    if (event.eventType.startsWith("entitlement.")) {
      for (const delivery of deliveries) await ctx.db.delete(delivery._id);
      await ctx.db.delete(event._id);
    } else {
      await ctx.db.patch(event._id, { userId: undefined });
    }
    commerceEventsErasedThisPage += 1;
  }

  const subscriptionsErased = job.subscriptionsErased + subscriptions.length;
  const commerceEventsErased =
    job.commerceEventsErased + commerceEventsErasedThisPage;
  const done =
    !waitingForClaimedDelivery &&
    subscriptions.length < USER_ERASURE_BATCH_SIZE &&
    purchases.length < USER_ERASURE_BATCH_SIZE &&
    commerceEvents.length < USER_ERASURE_BATCH_SIZE;

  if (done) {
    await ctx.db.patch(jobId, {
      userId: undefined,
      status: "completed",
      subscriptionsErased,
      commerceEventsErased,
      updatedAt: now,
      completedAt: now,
    });
  } else {
    await ctx.db.patch(jobId, {
      subscriptionsErased,
      commerceEventsErased,
      updatedAt: now,
    });
    await ctx.scheduler.runAfter(
      waitingForClaimedDelivery ? 1_000 : 0,
      internal.subscriptions.internal.drainSubscriptionUserErasureJob,
      { jobId },
    );
  }

  return { done, subscriptionsErased, commerceEventsErased };
}

export const drainSubscriptionUserErasureJob = internalMutation({
  args: { jobId: v.id("subscriptionUserErasureJobs") },
  handler: async (ctx, args) =>
    drainSubscriptionUserErasurePage(ctx, args.jobId),
});

export const resumeSubscriptionUserErasureJobs = internalMutation({
  args: {},
  returns: v.object({ scheduled: v.number() }),
  handler: async (ctx) => {
    const staleBefore = Date.now() - USER_ERASURE_STALE_MS;
    const [queued, stale] = await Promise.all([
      ctx.db
        .query("subscriptionUserErasureJobs")
        .withIndex("by_status_and_updated", (q) => q.eq("status", "queued"))
        .take(10),
      ctx.db
        .query("subscriptionUserErasureJobs")
        .withIndex("by_status_and_updated", (q) =>
          q.eq("status", "running").lt("updatedAt", staleBefore),
        )
        .take(10),
    ]);
    const jobs = [...queued, ...stale].slice(0, 10);
    for (const job of jobs) {
      await ctx.scheduler.runAfter(
        0,
        internal.subscriptions.internal.drainSubscriptionUserErasureJob,
        { jobId: job._id },
      );
    }
    return { scheduled: jobs.length };
  },
});

export async function pruneCompletedSubscriptionUserErasureJobsHandler(
  ctx: MutationCtx,
): Promise<{ pruned: number }> {
  const completedBefore = Date.now() - USER_ERASURE_JOB_RETENTION_MS;
  const completed = await ctx.db
    .query("subscriptionUserErasureJobs")
    .withIndex("by_status_and_updated", (q) =>
      q.eq("status", "completed").lt("updatedAt", completedBefore),
    )
    .take(USER_ERASURE_PRUNER_BATCH_SIZE);

  for (const job of completed) {
    await ctx.db.delete(job._id);
  }
  if (completed.length === USER_ERASURE_PRUNER_BATCH_SIZE) {
    await ctx.scheduler.runAfter(
      0,
      internal.subscriptions.internal.pruneCompletedSubscriptionUserErasureJobs,
      {},
    );
  }
  return { pruned: completed.length };
}

export const pruneCompletedSubscriptionUserErasureJobs = internalMutation({
  args: {},
  returns: v.object({ pruned: v.number() }),
  handler: async (ctx) => pruneCompletedSubscriptionUserErasureJobsHandler(ctx),
});

kit/convex/subscriptions/mutation.test.t:
import { describe, expect, it, vi } from "vitest";

import { testableFunction } from "../test.setup";
import { hmacSha256Hex, sha256Hex } from "../utils/sha256";
import {
  bindUserAsServer as registeredBindUserAsServer,
  rebindUser as registeredRebindUser,
  requestUserErasure as registeredRequestUserErasure,
} from "./mutation";

const rebindUser = testableFunction(registeredRebindUser);
const requestUserErasure = testableFunction(registeredRequestUserErasure);
const bindUserAsServer = testableFunction(registeredBindUserAsServer);

// rebindUser moves who owns a purchase, so it is secret-key only. The check
// lives in the mutation, not in the HTTP layer, because Convex functions are
// publicly callable with a key alone.
describe("rebindUser authorization", () => {
  const project = {
    _id: "projects_1",
    _creationTime: 0,
    organizationId: "organizations_1",
    userErasureHashKey: "test-erasure-hash-key",
  };
  const organization = { _id: "organizations_1", _creationTime: 0 };

  const dbWith = (
    keyType?: "publishable" | "secret",
    erasureJob?: Record<string, unknown>,
  ) => ({
    rows: {
      apiKeys: keyType
        ? [
            {
              _id: "apiKeys_1",
              key: "k",
              keyType,
              isActive: true,
              projectId: project._id,
              organizationId: organization._id,
            },
          ]
        : [],
      projects: [project],
      organizations: [organization],
      subscriptions: [],
      subscriptionUserErasureJobs: erasureJob ? [erasureJob] : [],
    } as Record<string, Record<string, unknown>[]>,
    async get(id: string) {
      return (
        Object.values(this.rows)
          .flat()
          .find((r) => r._id === id) ?? null
      );
    },
    query(table: string) {
      const rows = this.rows[table] ?? [];
      const api = {
        withIndex: (_n: string, fn: (q: unknown) => unknown) => {
          const captured: Record<string, unknown> = {};
          const q: Record<string, (f: string, v: unknown) => unknown> = {};
          q.eq = (f, v) => {
            captured[f] = v;
            return q;
          };
          fn(q);
          return {
            first: async () =>
              rows.find((r) =>
                Object.entries(captured).every(([k, v]) => r[k] === v),
              ) ?? null,
            unique: async () =>
              rows.find((r) =>
                Object.entries(captured).every(([k, v]) => r[k] === v),
              ) ?? null,
            collect: async () => [],
          };
        },
      };
      return api;
    },
    async patch(id: string, value: Record<string, unknown>) {
      const row = Object.values(this.rows)
        .flat()
        .find((candidate) => candidate._id === id);
      if (row) Object.assign(row, value);
    },
    async insert(table: string, value: Record<string, unknown>) {
      const id = `${table}_${(this.rows[table]?.length ?? 0) + 1}`;
      const row = { _id: id, ...value };
      (this.rows[table] ??= []).push(row);
      return id;
    },
  });

  it("rejects a publishable key", async () => {
    await expect(
      rebindUser._handler(dbWithCtx("publishable"), {
        apiKey: "k",
        purchaseToken: "t",
        userId: "u",
      }),
    ).rejects.toSatisfy(
      (e: unknown) =>
        (e as { data?: { code?: string } }).data?.code === "INSUFFICIENT_SCOPE",
    );
  });

  it("accepts a secret key", async () => {
    await expect(
      rebindUser._handler(dbWithCtx("secret"), {
        apiKey: "k",
        purchaseToken: "t",
        userId: "u",
      }),
    ).resolves.toEqual({ ok: true, rebound: false, notified: true });
  });

  it("rejects a publishable key for user erasure inside Convex", async () => {
    await expect(
      requestUserErasure._handler(dbWithCtx("publishable"), {
        apiKey: "k",
        userId: "user-1",
      }),
    ).rejects.toSatisfy(
      (e: unknown) =>
        (e as { data?: { code?: string } }).data?.code === "INSUFFICIENT_SCOPE",
    );
  });

  it("rejects an unknown secret-shaped key for user erasure", async () => {
    await expect(
      requestUserErasure._handler(
        { db: dbWith() },
        {
          apiKey: "openiap-kit_sk_unknown",
          userId: "user-1",
        },
      ),
    ).rejects.toSatisfy(
      (error: unknown) =>
        (error as { data?: { code?: string } }).data?.code ===
        "INVALID_API_KEY",
    );
  });

  it("returns the completed erasure job instead of reopening it", async () => {
    const userId = "user-1";
    const completed = {
      _id: "subscriptionUserErasureJobs_1",
      projectId: project._id,
      userIdHash: await hmacSha256Hex(project.userErasureHashKey, userId),
      status: "completed",
    };
    const scheduler = { runAfter: vi.fn() };

    await expect(
      requestUserErasure._handler(
        { db: dbWith("secret", completed), scheduler },
        { apiKey: "k", userId },
      ),
    ).resolves.toEqual({
      ok: true,
      jobId: completed._id,
      status: "completed",
    });
    expect(scheduler.runAfter).not.toHaveBeenCalled();
  });

  it("rekeys a legacy completed job on an idempotent request", async () => {
    const userId = "legacy-user";
    const completed = {
      _id: "subscriptionUserErasureJobs_legacy",
      projectId: project._id,
      userIdHash: await sha256Hex(userId),
      status: "completed",
    };
    const db = dbWith("secret", completed);
    const scheduler = { runAfter: vi.fn() };

    await expect(
      requestUserErasure._handler(
        { db, scheduler },
        {
          apiKey: "k",
          userId,
        },
      ),
    ).resolves.toMatchObject({ jobId: completed._id, status: "completed" });
    expect(completed.userIdHash).toBe(
      await hmacSha256Hex(project.userErasureHashKey, userId),
    );
    expect(scheduler.runAfter).not.toHaveBeenCalled();
  });

  it("stores a keyed erasure lookup instead of a plain userId digest", async () => {
    const userId = "guessable-user@example.com";
    const db = dbWith("secret");
    const scheduler = { runAfter: vi.fn() };

    await requestUserErasure._handler(
      { db, scheduler },
      {
        apiKey: "k",
        userId,
      },
    );

    const [job] = db.rows.subscriptionUserErasureJobs;
    expect(job.userIdHash).toBe(
      await hmacSha256Hex(project.userErasureHashKey, userId),
    );
    expect(job.userIdHash).not.toBe(await sha256Hex(userId));
  });

  it("creates a project erasure key on first use", async () => {
    const userId = "first-erasure-user";
    const db = dbWith("secret");
    db.rows.projects = [{ ...project, userErasureHashKey: undefined }];
    const scheduler = { runAfter: vi.fn() };

    await requestUserErasure._handler(
      { db, scheduler },
      {
        apiKey: "k",
        userId,
      },
    );

    const [projectRow] = db.rows.projects;
    const key = projectRow.userErasureHashKey;
    expect(key).toEqual(expect.any(String));
    expect(String(key)).toHaveLength(64);
    expect(db.rows.subscriptionUserErasureJobs[0].userIdHash).toBe(
      await hmacSha256Hex(String(key), userId),
    );
  });

  // bindPurchase (server role) must distinguish an unknown key from an
  // under-scoped one: unknown/inactive is INVALID_API_KEY (UNAUTHORIZED at the
  // edge), only a real publishable key is INSUFFICIENT_SCOPE (FORBIDDEN).
  it("rejects an unknown key with INVALID_API_KEY, not INSUFFICIENT_SCOPE", async () => {
    await expect(
      bindUserAsServer._handler(
        { db: dbWith() },
        {
          apiKey: "openiap-kit_sk_unknown",
          purchaseToken: "t",
          userId: "u",
        },
      ),
    ).rejects.toSatisfy(
      (error: unknown) =>
        (error as { data?: { code?: string } }).data?.code ===
        "INVALID_API_KEY",
    );
  });

  it("rejects a valid publishable key with INSUFFICIENT_SCOPE", async () => {
    await expect(
      bindUserAsServer._handler(dbWithCtx("publishable"), {
        apiKey: "k",
        purchaseToken: "t",
        userId: "u",
      }),
    ).rejects.toSatisfy(
      (error: unknown) =>
        (error as { data?: { code?: string } }).data?.code ===
        "INSUFFICIENT_SCOPE",
    );
  });

  it("accepts a secret key", async () => {
    await expect(
      bindUserAsServer._handler(dbWithCtx("secret"), {
        apiKey: "k",
        purchaseToken: "t",
        userId: "u",
      }),
    ).resolves.toEqual({ ok: true, bound: false });
  });

  function dbWithCtx(keyType: "publishable" | "secret") {
    return { db: dbWith(keyType) } as never;
  }
});

kit/server/api/commerce/routes.ts:
// The portable REST binding plus the GraphQL endpoint, mounted under
// /commerce/v1. Routes are registered from the generated HTTP manifest, so a
// route cannot exist that the contract does not declare; every adapter only
// parses transport, builds the auth context, validates against the generated
// schemas, calls the shared handler, and maps the outcome back.

import { Hono, type Context, type Next } from "hono";
import HTTP_BINDING from "openiap-commerce-protocol/generated/bindings/http-binding.json";

import {
  apiKeyValidationError,
  isPublishableApiKey,
  isSecretApiKey,
} from "../v1/middleware";
import {
  getRequestIp,
  multiAxisRateLimitMiddleware,
  sourceRateLimitMiddleware,
} from "../v1/rate-limit";
import {
  JsonBodyTooLargeError,
  readJsonBodyWithLimit,
} from "../v1/request-body";
import { ProtocolOperationError, protocolErrorStatus } from "./errors";
import { executeCommerceGraphql } from "./graphql";
import * as handlers from "./handlers";
import type { ProtocolContext } from "./handlers";
import { validateOperationInput } from "./validation";

const MAX_COMMERCE_BODY_BYTES = 32 * 1024;
const MOUNT_PREFIX = "/commerce/v1";

type CommerceVariables = {
  apiKey?: string;
  apiKeyHash?: string;
  commerceInput?: unknown;
  verifyCapacityRejected?: boolean;
};
type CommerceContext = Context<{ Variables: CommerceVariables }>;

// verifyPurchase's replay/in-flight admission lives in the shared handler
// (verificationAdmission), so both the REST route and the GraphQL resolver run
// through it — see server/api/commerce/handlers.ts.

const operationHandlers: Record<
  string,
  (context: ProtocolContext, input: never) => unknown
> = {
  providerCapabilities: () => handlers.providerCapabilities(),
  subscriptionStatus: (context, input) =>
    handlers.subscriptionStatus(context, input),
  entitlements: (context, input) => handlers.entitlements(context, input),
  verifyPurchase: (context, input) => handlers.verifyPurchase(context, input),
  bindPurchase: (context, input) => handlers.bindPurchase(context, input),
  eraseUser: (context, input) => handlers.eraseUser(context, input),
};

const GRAPHQL_PATH = `${MOUNT_PREFIX}/graphql`;

// The two bindings wrap the same protocol code in different envelopes
// (SPEC.md 8): REST as `{error:{code,message}}`, GraphQL as
// `{errors:[{message,extensions:{code}}]}`. Transport failures — rate limit,
// oversized body, unparseable body — must use the envelope of the binding
// they hit, or a GraphQL client sees a body with neither data nor errors.
function isGraphqlRequest(c: Context): boolean {
  return c.req.path.endsWith(GRAPHQL_PATH) || c.req.path === "/graphql";
}

function protocolError(
  c: Context,
  code: string,
  message: string,
  status = protocolErrorStatus(code),
  retryAfterSec?: number,
): Response {
  // A retry hint reaches REST as the standard Retry-After header and GraphQL
  // as retryAfterSec in the error extensions, so neither binding drops it.
  if (retryAfterSec !== undefined) {
    c.header("Retry-After", String(retryAfterSec));
  }
  if (isGraphqlRequest(c)) {
    // SPEC.md 7: every operation failure on the GraphQL binding is HTTP 200
    // with the code in errors[].extensions.code. This is the single status
    // policy for the binding — the outer rate limiter and the handler
    // admission both surface RATE_LIMITED at 200, never 429, so the endpoint
    // does not split its own contract.
    return c.json(
      {
        errors: [
          {
            message,
            extensions: {
              code,
              ...(retryAfterSec === undefined ? {} : { retryAfterSec }),
            },
          },
        ],
      },
      200,
    );
  }
  return c.json({ error: { code, message } }, status as 400);
}

function bearerApiKey(c: Context): string | null {
  const header = c.req.header("Authorization");
  if (!header) return null;
  const parts = header.trim().split(/\s+/);
  if (parts.length !== 2 || parts[0].toLowerCase() !== "bearer") return null;
  return apiKeyValidationError(parts[1]) ? null : parts[1];
}

const respondRateLimited = (
  c: Context,
  result: { retryAfterSec: number },
): Response =>
  // Passing retryAfterSec sets the Retry-After header on REST and puts
  // retryAfterSec into the GraphQL error extensions — the outer limiter must
  // carry the same machine-readable hint the per-operation admission does.
  protocolError(
    c,
    "RATE_LIMITED",
    `Too many requests. Retry after ${result.retryAfterSec}s.`,
    429,
    result.retryAfterSec,
  );

const app = new Hono<{ Variables: CommerceVariables }>();

// Unauthenticated requests (capabilities, credential-less GraphQL) still ride
// the bounded source-IP and process buckets.
app.use(
  "*",
  sourceRateLimitMiddleware({ respond: respondRateLimited }) as never,
);

const keyedRateLimit = multiAxisRateLimitMiddleware({
  respond: respondRateLimited,
});
const keyedRateLimitIfAuthed = async (c: CommerceContext, next: Next) =>
  c.var.apiKey ? keyedRateLimit(c as never, next) : next();

function commerceAuth(auth: string) {
  return async (c: CommerceContext, next: Next) => {
    const apiKey = bearerApiKey(c);
    if (auth !== "none") {
      // Fail close in the protocol envelope. The prefix check only
      // fast-fails an explicitly publishable key on a server operation;
      // the stored key classification stays authoritative in Convex, where
      // unknown and legacy formats fail closed as publishable.
      if (apiKey === null) {
        return protocolError(c, "UNAUTHORIZED", "A credential is required");
      }
      if (auth === "server" && isPublishableApiKey(apiKey)) {
        return protocolError(
          c,
          "FORBIDDEN",
          "This operation requires the server role",
        );
      }
    }
    if (apiKey !== null) {
      c.set("apiKey", apiKey);
      if (isSecretApiKey(apiKey)) {
        c.header("Cache-Control", "private, no-store");
      }
    }
    await next();
  };
}

// SPEC.md 5: server-role authorization precedes input validation. Runs after
// the rate limiters (an unauthenticated caller must not buy a Convex round
// trip per request unmetered) and before the body is parsed or validated.
const authoritativeServerAuth = async (c: CommerceContext, next: Next) => {
  try {
    await handlers.assertServerCredential({
      apiKey: c.var.apiKey ?? "",
      requestIp: getRequestIp(c),
    });
  } catch (error) {
    if (error instanceof ProtocolOperationError) {
      return protocolError(
        c,
        error.code,
        error.message,
        protocolErrorStatus(error.code),
        error.retryAfterSec,
      );
    }
    return protocolError(c, "INTERNAL_ERROR", "The operation failed");
  }
  await next();
};

for (const operation of HTTP_BINDING.operations) {
  const path = operation.path.slice(MOUNT_PREFIX.length);
  const run = operationHandlers[operation.name];
  if (!run) throw new Error(`No handler for operation ${operation.name}`);

  // Parse, size-cap, and schema-validate the input, then stash it so the
  // verify guards (which run after this) and the handler read one parsed body.
  const parseInput = async (c: CommerceContext, next: Next) => {
    let input: unknown = null;
    if (operation.input && operation.method === "GET") {
      input = Object.fromEntries(
        Object.entries(c.req.query()).filter(([, value]) => value !== ""),
      );
    } else if (operation.input) {
      try {
        input = await readJsonBodyWithLimit(
          c.req.raw,
          MAX_COMMERCE_BODY_BYTES,
          "Request body is too large",
        );
      } catch (error) {
        if (error instanceof JsonBodyTooLargeError) {
          return protocolError(
            c,
            "INVALID_REQUEST",
            "Request body is too large",
          );
        }
        return protocolError(c, "INVALID_REQUEST", "Body is not JSON");
      }
    }
    if (operation.input) {
      const invalid = validateOperationInput(operation.name, input);
      if (invalid) return protocolError(c, "INVALID_REQUEST", invalid);
    }
    c.set("commerceInput", input);
    await next();
  };

  const handler = async (c: CommerceContext) => {
    try {
      const context: ProtocolContext = {
        apiKey: c.var.apiKey ?? "",
        requestIp: getRequestIp(c),
      };
      const result = await run(context, c.get("commerceInput") as never);
      return c.json(result as object, operation.successStatus as 200);
    } catch (error) {
      if (error instanceof ProtocolOperationError) {
        return protocolError(
          c,
          error.code,
          error.message,
          protocolErrorStatus(error.code),
          error.retryAfterSec,
        );
      }
      console.error(
        "[commerce] %s failed errorClass=%s",
        operation.name,
        error instanceof Error ? error.name : typeof error,
      );
      return protocolError(c, "INTERNAL_ERROR", "The operation failed");
    }
  };

  if (operation.auth === "server") {
    app.on(
      operation.method,
      path,
      commerceAuth(operation.auth),
      keyedRateLimitIfAuthed,
      authoritativeServerAuth,
      parseInput,
      handler,
    );
  } else {
    app.on(
      operation.method,
      path,
      commerceAuth(operation.auth),
      keyedRateLimitIfAuthed,
      parseInput,
      handler,
    );
  }
}

// The GraphQL binding shares the same handlers and the same role rules;
// SPEC.md 7 keeps operation failures inside the GraphQL errors array, so the
// only role decision made here is which credential kind was presented.
app.post(
  "/graphql",
  commerceAuth("none"),
  keyedRateLimitIfAuthed,
  async (c) => {
    let payload: unknown;
    try {
      payload = await readJsonBodyWithLimit(
        c.req.raw,
        MAX_COMMERCE_BODY_BYTES,
        "Request body is too large",
      );
    } catch (error) {
      if (error instanceof JsonBodyTooLargeError) {
        return protocolError(c, "INVALID_REQUEST", "Request body is too large");
      }
      return protocolError(c, "INVALID_REQUEST", "Body is not JSON");
    }

    const apiKey = c.var.apiKey;
    const { status, body } = await executeCommerceGraphql(payload, {
      role:
        apiKey === undefined
          ? null
          : isPublishableApiKey(apiKey)
            ? "verification"
            : "server",
      apiKey,
      requestIp: getRequestIp(c),
    });
    return c.json(body as object, status);
  },
);

// Terminal: an unknown /commerce/v1 path is a protocol 404, never an SPA
// fallthrough.
app.all("*", (c) =>
  c.json({ error: { code: "NOT_FOUND", message: "Unknown operation" } }, 404),
);

export { app as commerceRoutes };

kit/convex/commerce/capabilities.ts:
// Per-provider capability declarations.
//
// These describe what IAPKit *actually implements today*, not what a store's
// API theoretically allows. Consumers branch on this instead of assuming every
// store behaves like Apple, and support can answer "why is there no renewal
// event for Meta" without reading provider code.
//
// Keep in sync with the provider modules; `contract.test.ts` pins the
// claims that have a concrete implementation behind them.

import type { CommerceStore } from "./contract";

export type ProviderCapabilities = {
  /** Server-side receipt/token validation on demand. */
  supportsInitialValidation: boolean;
  /** Store pushes lifecycle notifications to IAPKit. */
  supportsServerNotifications: boolean;
  /** IAPKit keeps a canonical subscription record for this store. */
  supportsSubscriptions: boolean;
  /** Renewal is observable as a distinct lifecycle event. */
  supportsRenewalEvents: boolean;
  /** Refund or revocation is observable as a distinct lifecycle event. */
  supportsRefundEvents: boolean;
  /** Expiration is observable rather than only inferred from a timestamp. */
  supportsExpiration: boolean;
  /** A scheduled pass re-reads authoritative store state. */
  supportsReconciliation: boolean;
  /** Entitlement state is derivable for gating. */
  supportsEntitlements: boolean;
  /** The store asserts an amount IAPKit can attribute to revenue. */
  supportsRevenueAmount: boolean;
  /** Human-readable reason for every false above. */
  notes: string;
};

export const PROVIDER_CAPABILITIES: Record<
  CommerceStore,
  ProviderCapabilities
> = {
  apple: {
    supportsInitialValidation: true,
    supportsServerNotifications: true,
    supportsSubscriptions: true,
    supportsRenewalEvents: true,
    supportsRefundEvents: true,
    supportsExpiration: true,
    supportsReconciliation: false,
    supportsEntitlements: true,
    supportsRevenueAmount: true,
    notes:
      "App Store Server Notifications V2 drive the lifecycle. No scheduled " +
      "reconciliation pass exists yet, so a notification lost past Apple's " +
      "retry window is not self-healing. Receipt verification bootstraps a " +
      "token only before its first store event and cannot recreate a missed " +
      "commerce event.",
  },
  google: {
    supportsInitialValidation: true,
    supportsServerNotifications: true,
    supportsSubscriptions: true,
    supportsRenewalEvents: true,
    supportsRefundEvents: true,
    supportsExpiration: true,
    supportsReconciliation: false,
    supportsEntitlements: true,
    supportsRevenueAmount: true,
    notes:
      "RTDN drives the lifecycle. Google reissues purchaseToken across " +
      "upgrade/downgrade. The receiver requires subscriptionsv2 enrichment " +
      "for non-terminal lifecycle events and uses linkedPurchaseToken to move " +
      "the canonical row onto the replacement token. No scheduled " +
      "reconciliation pass exists, and receipt verification cannot recreate " +
      "a missed commerce event.",
  },
  horizon: {
    supportsInitialValidation: true,
    supportsServerNotifications: false,
    supportsSubscriptions: false,
    supportsRenewalEvents: false,
    supportsRefundEvents: false,
    supportsExpiration: false,
    supportsReconciliation: false,
    supportsEntitlements: true,
    supportsRevenueAmount: false,
    notes:
      "Only the Graph verify_entitlement endpoint is integrated: a one-shot " +
      "check that the viewer owns the SKU. Meta exposes no server " +
      "notifications to IAPKit, so there is no renewal, expiration or refund " +
      "signal and no canonical subscription record. Entitlement is answerable " +
      "only at the moment it is asked.",
  },
  amazon: {
    supportsInitialValidation: true,
    supportsServerNotifications: false,
    supportsSubscriptions: false,
    supportsRenewalEvents: false,
    supportsRefundEvents: false,
    supportsExpiration: false,
    supportsReconciliation: true,
    supportsEntitlements: true,
    supportsRevenueAmount: false,
    notes:
      "RVS validates receipts. Rows become due every 48 hours and a bounded " +
      "worker checks due work every five minutes, so backlog and retries can " +
      "extend that interval. RVS alone does not carry " +
      "enough lifecycle detail for a canonical subscription record, so no " +
      "subscription rows or lifecycle events are produced. A verification " +
      "still answers point-in-time entitlement.",
  },
};

/** Stores that can produce normalized subscription lifecycle events today. */
export function storesWithLifecycleEvents(): CommerceStore[] {
  return (Object.keys(PROVIDER_CAPABILITIES) as CommerceStore[]).filter(
    (store) => PROVIDER_CAPABILITIES[store].supportsSubscriptions,
  );
}

kit/convex/commerce/spec.conformance.tes:
// Proves IAPKit conforms to the OpenIAP Commerce Protocol.
//
// The specification is the authority: its JSON Schema validates real payloads
// this implementation builds, and its published vocabulary is compared against
// the one this implementation ships. Neither list is restated here, so the two
// cannot drift silently — if kit gains an event type the spec does not declare,
// this file fails.

import Ajv from "ajv/dist/2020.js";
import {
  KNOWN_COMMERCE_EVENT_TYPES as SPEC_EVENT_TYPES,
  COMMERCE_EVENT_VERSION,
  DATA_PROVENANCE as SPEC_DATA_PROVENANCE,
  EXTENSION_LIMITS,
  KNOWN_STORES as SPEC_KNOWN_STORES,
  SUBSCRIPTION_STATES as SPEC_SUBSCRIPTION_STATES,
  WEBHOOK,
  commerceEventSchema,
  primitivesSchema,
} from "openiap-commerce-protocol";
import { describe, expect, it } from "vitest";

import type { Doc } from "../_generated/dataModel";
import { PROVIDER_CAPABILITIES } from "./capabilities";
import {
  COMMERCE_ENVIRONMENTS,
  COMMERCE_EVENT_SCHEMA_VERSION,
  COMMERCE_EVENT_TYPES,
  COMMERCE_STORES,
  DATA_PROVENANCE_VALUES,
  commerceEventTypeForTransition,
  MAX_EXTENSION_ENTRIES,
  MAX_EXTENSION_KEY_LENGTH,
  MAX_EXTENSION_VALUE_LENGTH,
  TRANSITION_TO_EVENT,
  type LifecycleTransition,
} from "./contract";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

import {
  applySubscriptionTransition,
  entitlementActive,
} from "../subscriptions/stateMachine";
import {
  mapAppleNotificationType,
  mapGoogleSubscriptionNotificationType,
} from "../webhooks/shared";

import { buildEventPayload } from "./deliveryState";
import { emitCommerceEvent } from "./internal";
import {
  EVENT_ID_HEADER,
  DELIVERY_ID_HEADER,
  SIGNATURE_HEADER,
  CONTENT_TYPE,
  SIGNATURE_TOLERANCE_SECONDS,
  signPayloadWithRotation,
  TIMESTAMP_HEADER,
} from "./signing";

// kit is an ESM package, so `require` only exists through the test runner's
// interop shim. Resolve the specification's published subpaths the way any
// ESM consumer would instead of depending on that.
const resolveSpec = createRequire(import.meta.url).resolve;

function validator() {
  const ajv = new Ajv({ strict: true, allErrors: true });
  ajv.addSchema(primitivesSchema, "primitives.schema.json");
  ajv.addSchema(commerceEventSchema, "commerce-event.schema.json");
  return ajv;
}

const validateEvent = () =>
  validator().getSchema("commerce-event.schema.json")!;

/** A stored row shaped exactly as `emitCommerceEvent` writes one. */
function storedEvent(overrides: Record<string, unknown> = {}) {
  return {
    _id: "commerceEvents_1",
    _creationTime: 0,
    projectId: "projects_1",
    eventType: "subscription.renewed",
    eventVersion: COMMERCE_EVENT_SCHEMA_VERSION,
    store: "apple",
    environment: "production",
    userId: "user_1",
    productId: "premium.monthly",
    transactionId: "2000000912345678",
    originalTransactionId: "2000000811111111",
    subscriptionId: "subscriptions_1",
    subscription: {
      state: "Active",
      productId: "premium.monthly",
      expiresAt: 1_758_979_200_000,
      renewsAt: 1_758_979_200_000,
      willRenew: true,
    },
    entitlementActive: true,
    currency: "USD",
    amountMicros: 9_990_000,
    amountProvenance: "store",
    sourceEventId: "webhookEvents_1",
    sourceStoreNotificationId: "8f3b1c2d-4e5a-6b7c-8d9e-0f1a2b3c4d5e",
    occurredAt: 1_756_300_800_000,
    processedAt: 1_756_300_801_420,
    ...overrides,
  } as unknown as Doc<"commerceEvents">;
}

describe("IAPKit conforms to the OpenIAP Commerce Protocol", () => {
  it("declares only event types the specification names", () => {
    for (const eventType of COMMERCE_EVENT_TYPES) {
      expect(SPEC_EVENT_TYPES).toContain(eventType);
    }
  });

  it("emits the event version the specification names", () => {
    expect(COMMERCE_EVENT_SCHEMA_VERSION).toBe(COMMERCE_EVENT_VERSION);
  });

  it("bounds extensions exactly as the specification does", () => {
    expect({
      maxEntries: MAX_EXTENSION_ENTRIES,
      maxKeyLength: MAX_EXTENSION_KEY_LENGTH,
      maxValueLength: MAX_EXTENSION_VALUE_LENGTH,
    }).toEqual(EXTENSION_LIMITS);
  });

  it("uses the transport headers and replay window the specification fixes", () => {
    expect(SIGNATURE_HEADER).toBe(WEBHOOK.signatureHeader);
    expect(TIMESTAMP_HEADER).toBe(WEBHOOK.timestampHeader);
    expect(EVENT_ID_HEADER).toBe(WEBHOOK.eventIdHeader);
    expect(DELIVERY_ID_HEADER).toBe(WEBHOOK.deliveryIdHeader);
    expect(SIGNATURE_TOLERANCE_SECONDS).toBe(WEBHOOK.toleranceSeconds);
    expect(CONTENT_TYPE).toBe(WEBHOOK.contentType);
  });

  const signatureVectors = JSON.parse(
    readFileSync(
      resolveSpec("openiap-commerce-protocol/vectors/signatures.json"),
      "utf8",
    ),
  ) as {
    cases: {
      name: string;
      secret: string;
      previousSecret?: string;
      timestamp: number;
      body: string;
      expected: string;
    }[];
  };

  // SPEC.md 9.4.2 fixes the signed material. Every other signing test here is
  // self-relative, so it could be changed wholesale without one of them failing.
  it.each(signatureVectors.cases.map((c) => [c.name, c] as const))(
    "reproduces the %s signature vector",
    async (_name, vector) => {
      await expect(
        signPayloadWithRotation(
          { current: vector.secret, previous: vector.previousSecret },
          vector.timestamp,
          vector.body,
        ),
      ).resolves.toBe(vector.expected);
    },
  );
});

describe("built payloads validate against the specification schema", () => {
  it("a minimal event with no subscription and no price validates", () => {
    const validate = validateEvent();
    const payload = buildEventPayload(
      storedEvent({
        store: "amazon",
        subscription: undefined,
        subscriptionId: undefined,
        entitlementActive: undefined,
        currency: undefined,
        amountMicros: undefined,
        amountProvenance: undefined,
        userId: undefined,
        transactionId: undefined,
        originalTransactionId: undefined,
        sourceStoreNotificationId: undefined,
      }),
    );
    const ok = validate(payload);
    expect(validate.errors ?? [], JSON.stringify(validate.errors)).toEqual([]);
    expect(ok).toBe(true);
  });

  it("kit's emitter produces lifecycle events for Apple and Google only", async () => {
    // storeForPlatform maps the inbound platform enum, which has two members.
    // Horizon and Amazon reach kit through verification, not notifications —
    // which is exactly what their capability descriptor declares.
    for (const [platform, expectedStore] of [
      ["IOS", "apple"],
      ["Android", "google"],
    ] as const) {
      const { ctx, inserted } = emitterContext();
      await emitCommerceEvent(ctx as never, {
        projectId: "projects_1" as never,
        transition: "Renewed",
        active: true,
        previouslyActive: true,
        sourceEvent: { ...(richSource as object), platform } as never,
      });
      expect(inserted[0].doc.store).toBe(expectedStore);
    }
  });

  it("omits the snapshot rather than inventing an entitlement gate", () => {
    // The stored gate is optional. Emitting `active: false` for a row that
    // never recorded one would assert no access for something unknown.
    const payload = buildEventPayload(
      storedEvent({ entitlementActive: undefined }),
    );
    expect(payload.subscription).toBeUndefined();
    expect(validateEvent()(payload)).toBe(true);
  });

  it("carries the gate through when the row recorded one", () => {
    const payload = buildEventPayload(
      storedEvent({ entitlementActive: false }),
    );
    expect(payload.subscription?.active).toBe(false);
  });

  it("omits price entirely when the store asserted no amount, rather than sending zero", () => {
    const payload = buildEventPayload(
      storedEvent({ currency: undefined, amountMicros: undefined }),
    );
    expect(payload.price).toBeUndefined();
  });
});

describe("the subscription state vocabulary matches", () => {
  it("kit's own state vocabulary is one the specification declares", () => {
    // Reading the spec's enum and validating it against the spec's enum proves
    // nothing. The real claim is that kit's union is a subset of it.
    const source = readFileSync(
      fileURLToPath(new URL("../webhooks/shared.ts", import.meta.url)),
      "utf8",
    );
    const start = source.indexOf("export type SubscriptionState");
    const block = source.slice(start, source.indexOf(";", start));
    const declared = [...block.matchAll(/"([A-Za-z]+)"/g)].map((m) => m[1]);
    expect(declared.length).toBeGreaterThan(5);
    for (const state of declared) {
      expect(SPEC_SUBSCRIPTION_STATES, `${state} is undeclared`).toContain(
        state,
      );
    }
  });

  it("declares no provenance, store, or environment the specification lacks", () => {
    // Closed value space: the two lists must be identical.
    expect([...DATA_PROVENANCE_VALUES].sort()).toEqual(
      [...SPEC_DATA_PROVENANCE].sort(),
    );
    // Open value spaces: everything kit emits must still be a value the
    // specification names today.
    for (const store of COMMERCE_STORES) {
      expect(SPEC_KNOWN_STORES, `${store} is undeclared`).toContain(store);
    }
    const specEnvironments = (
      primitivesSchema as unknown as {
        $defs: { Environment: { examples: readonly string[] } };
      }
    ).$defs.Environment.examples;
    for (const environment of COMMERCE_ENVIRONMENTS) {
      expect(specEnvironments, `${environment} is undeclared`).toContain(
        environment,
      );
    }
  });

  it("rejects a state the specification does not declare", () => {
    const validate = validateEvent();
    const payload = buildEventPayload(
      storedEvent({
        subscription: { state: "Hibernating", productId: "premium.monthly" },
      }),
    );
    expect(validate(payload)).toBe(false);
  });
});

describe("kit's capabilities agree with the published descriptor", () => {
  const descriptor = JSON.parse(
    readFileSync(
      resolveSpec(
        "openiap-commerce-protocol/examples/provider-capabilities.json",
      ),
      "utf8",
    ),
  ) as {
    eventTypes: string[];
    stores: Record<
      string,
      Record<string, { provider: boolean; implementation: boolean }>
    >;
  };

  const FIELDS: [keyof (typeof PROVIDER_CAPABILITIES)["apple"], string][] = [
    ["supportsInitialValidation", "initialValidation"],
    ["supportsServerNotifications", "serverNotifications"],
    ["supportsSubscriptions", "subscriptions"],
    ["supportsRenewalEvents", "renewalEvents"],
    ["supportsRefundEvents", "refundEvents"],
    ["supportsExpiration", "expiration"],
    ["supportsReconciliation", "reconciliation"],
    ["supportsEntitlements", "entitlements"],
    ["supportsRevenueAmount", "revenueAmount"],
  ];

  it("publishes the event vocabulary kit implements", () => {
    expect([...descriptor.eventTypes].sort()).toEqual(
      [...COMMERCE_EVENT_TYPES].sort(),
    );
  });

  // kit knows one axis: what it implements. The descriptor carries both, and
  // fabricating the provider axis from kit's boolean is the conflation the
  // two-axis model exists to prevent — it would claim Amazon publishes no
  // notification channel merely because kit consumes none.
  it.each(Object.keys(PROVIDER_CAPABILITIES))(
    "%s implementation axis matches kit",
    (store) => {
      const caps =
        PROVIDER_CAPABILITIES[store as keyof typeof PROVIDER_CAPABILITIES];
      for (const [kitField, specField] of FIELDS) {
        expect(
          descriptor.stores[store][specField].implementation,
          `${store}.${specField}`,
        ).toBe(caps[kitField]);
      }
    },
  );

  it("never claims to implement more than the provider offers", () => {
    for (const [store, entry] of Object.entries(descriptor.stores)) {
      for (const [name, support] of Object.entries(entry)) {
        if (support.implementation) {
          expect(support.provider, `${store}.${name}`).toBe(true);
        }
      }
    }
  });
});

describe("kit reproduces the specification's lifecycle vectors", () => {
  const vectors = JSON.parse(
    readFileSync(
      resolveSpec("openiap-commerce-protocol/generated/vectors/lifecycle.json"),
      "utf8",
    ),
  ) as {
    entitlement: {
      cases: {
        name: string;
        state: string;
        expiresAt?: number;
        occurredAt: number;
        processedAt: number;
        entitled: boolean;
      }[];
    };
    emission: {
      cases: {
        name: string;
        lifecycleEvent: string | null;
        entitledBefore: boolean;
        entitledAfter: boolean;
        emit: string[];
      }[];
    };
    binding: {
      cases: {
        name: string;
        entitledAtBinding: boolean;
        emit: string[];
      }[];
    };
  };

  it.each(vectors.entitlement.cases.map((c) => [c.name, c] as const))(
    "entitlement: %s",
    (_name, testCase) => {
      const sub = {
        state: testCase.state,
        productId: "premium.monthly",
        ...(testCase.expiresAt === undefined
          ? {}
          : { expiresAt: testCase.expiresAt }),
      } as never;
      expect(entitlementActive(sub, testCase.processedAt)).toBe(
        testCase.entitled,
      );
    },
  );

  // Drives kit's REAL emitter. Re-deriving the expected list from
  // entitledBefore/entitledAfter would just restate the generator's formula and
  // could never fail — the point is to make `emitCommerceEvent` itself produce
  // the events the vectors demand.
  const KIT_TRANSITIONS = Object.keys(
    TRANSITION_TO_EVENT,
  ) as LifecycleTransition[];

  /** The kit transition whose mapping produces this specification event. */
  function transitionFor(lifecycleEvent: string | null) {
    const match = KIT_TRANSITIONS.find(
      (t) => commerceEventTypeForTransition(t) === lifecycleEvent,
    );
    if (!match) throw new Error(`no kit transition emits ${lifecycleEvent}`);
    return match;
  }

  it.each(vectors.emission.cases.map((c) => [c.name, c] as const))(
    "emission: %s",
    async (_name, testCase) => {
      const { ctx, inserted } = emitterContext();
      await emitCommerceEvent(ctx as never, {
        projectId: "projects_1" as never,
        transition: transitionFor(testCase.lifecycleEvent),
        active: testCase.entitledAfter,
        previouslyActive: testCase.entitledBefore,
        sourceEvent: richSource,
        subscription: {
          state: "Active",
          productId: "premium.monthly",
          userId: "user_5e91a7",
        },
      });
      const emitted = inserted
        .filter((row) => row.table === "commerceEvents")
        .map((row) => row.doc.eventType);
      expect(emitted).toEqual(testCase.emit);
    },
  );

  it.each(vectors.binding.cases.map((c) => [c.name, c] as const))(
    "first binding: %s",
    async (_name, testCase) => {
      const { ctx, inserted } = emitterContext();
      await emitCommerceEvent(ctx as never, {
        projectId: "projects_1" as never,
        transition: null,
        active: testCase.entitledAtBinding,
        previouslyActive: false,
        sourceEvent: richSource,
        subscription: {
          state: testCase.entitledAtBinding ? "Active" : "Expired",
          productId: "premium.monthly",
          userId: "user_5e91a7",
        },
      });
      expect(
        inserted
          .filter((row) => row.table === "commerceEvents")
          .map((row) => row.doc.eventType),
      ).toEqual(testCase.emit);
    },
  );

  it("maps every transition kit produces onto an event the vectors cover", () => {
    const covered = new Set(
      vectors.emission.cases.map((c) => c.lifecycleEvent).filter(Boolean),
    );
    const transitions = KIT_TRANSITIONS.filter((t) => t !== "Ignored");
    for (const transition of transitions) {
      const event = commerceEventTypeForTransition(transition);
      expect(event, `${transition} must map to an event`).toBeTruthy();
      expect(covered, `${event} must be covered by a vector`).toContain(event);
    }
  });

  it("emits nothing for the no-op transition, as the vectors require", () => {
    expect(commerceEventTypeForTransition("Ignored")).toBeNull();
    expect(commerceEventTypeForTransition(null)).toBeNull();
  });
});

describe("kit can produce everything the store mapping promises", () => {
  const mapping = JSON.parse(
    readFileSync(
      resolveSpec(
        "openiap-commerce-protocol/examples/store-event-mapping.json",
      ),
      "utf8",
    ),
  ) as {
    stores: Record<
      string,
      {
        notificationChannel: string | null;
        mappings: { event: string | null }[];
      }
    >;
  };

  it("never claims to consume a channel the store does not publish", () => {
    // notificationChannel is a fact about the store; the capability is a fact
    // about kit. Implementation implies provider, never the reverse.
    for (const [store, entry] of Object.entries(mapping.stores)) {
      const caps =
        PROVIDER_CAPABILITIES[store as keyof typeof PROVIDER_CAPABILITIES];
      if (!caps.supportsServerNotifications) continue;
      expect(
        entry.notificationChannel,
        `${store}: kit consumes notifications the mapping says do not exist`,
      ).not.toBeNull();
    }
  });

  it("records an unconsumed channel as a kit gap, not a store limitation", () => {
    // Amazon is the live case: the store publishes a channel, kit integrates
    // no receiver. Collapsing that into "the store has none" is the exact
    // conflation the two-axis capability model exists to prevent.
    expect(mapping.stores.amazon.notificationChannel).not.toBeNull();
    expect(PROVIDER_CAPABILITIES.amazon.supportsServerNotifications).toBe(
      false,
    );
  });

  it("produces no lifecycle events for a store the mapping leaves empty", () => {
    for (const [store, entry] of Object.entries(mapping.stores)) {
      if (entry.mappings.length > 0) continue;
      const caps =
        PROVIDER_CAPABILITIES[store as keyof typeof PROVIDER_CAPABILITIES];
      expect(caps.supportsSubscriptions, `${store}`).toBe(false);
      expect(caps.supportsRenewalEvents, `${store}`).toBe(false);
    }
  });
});

/**
 * Stands in for a MutationCtx. `destinations` lets a test exercise the
 * fan-out and the per-destination event-type filter, which a context that
 * always answers "no destinations" would hide entirely.
 */
function emitterContext(
  destinations: { _id: string; eventTypes?: string[] }[] = [],
) {
  const inserted: { table: string; doc: Record<string, unknown> }[] = [];
  const byId = new Map<string, Record<string, unknown>>();
  const rowsFor = (table: string) =>
    table === "outboundDestinations" ? destinations : [];
  const queryFor = (table: string) => {
    const q: Record<string, unknown> = {
      withIndex: () => q,
      collect: async () => rowsFor(table),
      unique: async () => rowsFor(table)[0] ?? null,
      first: async () => rowsFor(table)[0] ?? null,
    };
    return q;
  };
  const ctx = {
    db: {
      insert: async (table: string, doc: Record<string, unknown>) => {
        const id = `${table}_${inserted.length + 1}`;
        const row = { ...doc, _id: id, _creationTime: 0 };
        inserted.push({ table, doc: row });
        byId.set(id, row);
        return id;
      },
      patch: async (id: string, patchDoc: Record<string, unknown>) => {
        Object.assign(byId.get(id) ?? {}, patchDoc);
      },
      get: async (id: string) => byId.get(id) ?? null,
      query: (table: string) => queryFor(table),
    },
  };
  return { ctx, inserted };
}

/** A source event complete enough that the emitter fills every canonical field. */
const richSource = {
  _id: "webhookEvents_1",
  platform: "IOS",
  environment: "Production",
  occurredAt: 1_756_300_800_000,
  sourceNotificationId: "8f3b1c2d-4e5a-6b7c-8d9e-0f1a2b3c4d5e",
  productId: "premium.monthly",
  purchaseToken: "2000000811111111",
  currency: "USD",
  priceAmountMicros: 9_990_000,
  amountProvenance: "store",
} as never;

describe("kit's cancellation vocabulary is one the specification names", () => {
  // The tokens live in a schema description on one side and a TypeScript union
  // on the other, with nothing between them. A store this backend never sees
  // may add more, so the check is containment, not equality.
  const described = JSON.parse(
    readFileSync(
      resolveSpec(
        "openiap-commerce-protocol/generated/schemas/commerce-event.schema.json",
      ),
      "utf8",
    ),
  ).properties.subscription.properties.cancellationReason.description as string;

  const KIT_REASONS = [
    "UserCanceled",
    "BillingError",
    "PriceIncreaseDeclined",
    "ProductUnavailable",
    "Refunded",
    "Other",
  ];

  it("matches the union the receiver declares", () => {
    const source = readFileSync(
      fileURLToPath(new URL("../webhooks/shared.ts", import.meta.url)),
      "utf8",
    );
    const start = source.indexOf("export type WebhookCancellationReason");
    const block = source.slice(start, source.indexOf(";", start));
    const declared = [...block.matchAll(/"([A-Za-z]+)"/g)].map((m) => m[1]);
    expect(declared.sort()).toEqual([...KIT_REASONS].sort());
  });

  it("is named in full by the specification", () => {
    for (const reason of KIT_REASONS) {
      expect(described, `${reason} is unnamed by the spec`).toContain(reason);
    }
  });
});

describe("what the emitter writes is a valid specification event", () => {
  // The two halves of this file never met: one validated a hand-written row,
  // the other checked event-type strings. Neither took what emitCommerceEvent
  // actually inserted and ran it through the wire builder and the published
  // schema — which is the only assertion that makes this a conformance test.
  const validate = validateEvent();

  it("a full lifecycle emission survives buildEventPayload and the schema", async () => {
    const { ctx, inserted } = emitterContext();
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: "Renewed",
      active: true,
      previouslyActive: false,
      sourceEvent: richSource,
      subscriptionId: "subscriptions_1" as never,
      subscription: {
        state: "Active",
        productId: "premium.monthly",
        expiresAt: 1_758_979_200_000,
        renewsAt: 1_758_979_200_000,
        willRenew: true,
        userId: "user_5e91a7",
      },
    });

    const events = inserted.filter((row) => row.table === "commerceEvents");
    expect(events).toHaveLength(2);
    for (const row of events) {
      const payload = buildEventPayload(row.doc as never);
      const ok = validate(payload);
      expect(validate.errors ?? [], JSON.stringify(validate.errors)).toEqual(
        [],
      );
      expect(ok).toBe(true);
      // The internal identifiers the emitter stores must not reach the wire.
      const wire = payload as unknown as Record<string, unknown>;
      expect(wire.subscriptionId).toBeUndefined();
      expect(wire.sourceEventId).toBeUndefined();
      expect(wire._id).toBeUndefined();
    }
  });

  it("prices the lifecycle event only, never both events of one transition", async () => {
    const { ctx, inserted } = emitterContext();
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: "Started",
      active: true,
      previouslyActive: false,
      sourceEvent: richSource,
      subscription: {
        state: "Active",
        productId: "premium.monthly",
        userId: "user_5e91a7",
      },
    });
    const events = inserted.filter((row) => row.table === "commerceEvents");
    expect(events.map((row) => row.doc.eventType)).toEqual([
      "subscription.started",
      "entitlement.granted",
    ]);
    expect(events[0].doc.amountMicros).toBe(9_990_000);
    expect(events[1].doc.amountMicros).toBeUndefined();
    expect(events[1].doc.currency).toBeUndefined();
    expect(events[1].doc.amountProvenance).toBeUndefined();
  });

  it("omits the amount when the source recorded no provenance", async () => {
    // "store" is the only provenance the contract calls authoritative, so
    // defaulting to it would present an unknown as a store assertion.
    const { ctx, inserted } = emitterContext();
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: "Renewed",
      active: true,
      previouslyActive: true,
      sourceEvent: {
        ...(richSource as object),
        amountProvenance: undefined,
      } as never,
    });
    expect(inserted[0].doc.amountProvenance).toBeUndefined();
    expect(buildEventPayload(inserted[0].doc as never).price).toBeUndefined();
  });

  it("puts the amount on the entitlement event when there is no lifecycle event", async () => {
    // A receipt-bootstrapped first purchase flips the gate with no lifecycle
    // change. Dropping the amount there would lose it entirely.
    const { ctx, inserted } = emitterContext();
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: null,
      active: true,
      previouslyActive: false,
      sourceEvent: richSource,
      subscription: {
        state: "Active",
        productId: "premium.monthly",
        userId: "user_5e91a7",
      },
    });
    const events = inserted.filter((row) => row.table === "commerceEvents");
    expect(events.map((row) => row.doc.eventType)).toEqual([
      "entitlement.granted",
    ]);
    expect(events[0].doc.amountMicros).toBe(9_990_000);
  });

  it("carries the store's own notification id, not the emitter's row id", async () => {
    const { ctx, inserted } = emitterContext();
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: "Renewed",
      active: true,
      previouslyActive: true,
      sourceEvent: richSource,
    });
    const payload = buildEventPayload(inserted[0].doc as never);
    expect(payload.sourceStoreEventId).toBe(
      "8f3b1c2d-4e5a-6b7c-8d9e-0f1a2b3c4d5e",
    );
    expect(payload.price).toEqual({
      currency: "USD",
      amountMicros: 9_990_000,
      provenance: "store",
    });
  });

  it("fans out to a subscribed destination and skips an unsubscribed one", async () => {
    const { ctx, inserted } = emitterContext([
      { _id: "outboundDestinations_1" },
      { _id: "outboundDestinations_2", eventTypes: ["subscription.expired"] },
    ]);
    await emitCommerceEvent(ctx as never, {
      projectId: "projects_1" as never,
      transition: "Renewed",
      active: true,
      previouslyActive: true,
      sourceEvent: richSource,
    });
    const deliveries = inserted.filter(
      (row) => row.table === "outboundDeliveries",
    );
    // The filtering destination asked for a different event type.
    expect(deliveries).toHaveLength(1);
    expect(deliveries[0].doc.destinationId).toBe("outboundDestinations_1");
  });
});

describe("every mapping row produces the event it promises", () => {
  // The mapping table is prose until something runs it. Without this, a row can
  // claim any event that merely exists in the vocabulary and stay green — which
  // is exactly how several rows drifted from the pipeline.
  type Row = {
    storeNotification: string;
    storeNotificationCode?: string;
    storeSubtype?: string | null;
    whenNoPriorStoreEvent?: boolean;
    whenPreviousState?: string[];
    event: string | null;
  };
  const mapping = JSON.parse(
    readFileSync(
      resolveSpec(
        "openiap-commerce-protocol/examples/store-event-mapping.json",
      ),
      "utf8",
    ),
  ) as { stores: Record<string, { mappings: Row[] }> };

  /** Notifications carried on their own message field, not a type enum. */
  const SPECIAL: Record<string, string | null> = {
    voidedPurchaseNotification: "PurchaseRefunded",
    testNotification: "TestNotification",
  };

  function internalTypeFor(store: string, row: Row): string | null {
    if (row.storeNotification in SPECIAL) return SPECIAL[row.storeNotification];
    if (store === "apple") {
      return mapAppleNotificationType(
        row.storeNotification,
        row.storeSubtype ?? null,
      );
    }
    return mapGoogleSubscriptionNotificationType(
      Number(row.storeNotificationCode),
    );
  }

  function emittedFor(store: string, row: Row): string | null {
    const internalType = internalTypeFor(store, row);
    if (!internalType) return null;
    // This drives the state machine directly, so it models "no prior store
    // event" as "no record" — one of the two cases the qualifier covers. The
    // other, a record with no store history, is reached only through the full
    // handler and is exercised in subscriptions/internal.test.ts ("starts
    // rather than recovers when a record exists with no store history").
    const current = row.whenNoPriorStoreEvent
      ? null
      : {
          state: (row.whenPreviousState?.[0] ?? "Active") as never,
          productId: "premium.monthly",
          expiresAt: 9_999_999_999_999,
        };
    const result = applySubscriptionTransition(current, {
      type: internalType,
      productId: "premium.monthly",
      platform: store === "apple" ? "IOS" : "Android",
      purchaseToken: "token",
      expiresAt: 9_999_999_999_999,
    } as never);
    return commerceEventTypeForTransition(result.transition);
  }

  const cases = Object.entries(mapping.stores).flatMap(([store, entry]) =>
    entry.mappings.map(
      (row) =>
        [
          `${store} ${row.storeNotification}${row.storeSubtype ? `/${row.storeSubtype}` : ""}${row.whenNoPriorStoreEvent ? " (no store history)" : row.whenPreviousState ? ` (was ${row.whenPreviousState[0]})` : ""}`,
          store,
          row,
        ] as const,
    ),
  );

  // The implementation's own code table, read from its source. Google sends a
  // number; the readable name lives only in a trailing comment, so without this
  // the table's names are decoration the test never executes — swap two and it
  // stays green while an implementer maps the wrong notification.
  const googleCodeNames = (() => {
    const source = readFileSync(
      fileURLToPath(new URL("../webhooks/shared.ts", import.meta.url)),
      "utf8",
    );
    const start = source.indexOf("const GOOGLE_SUB_TYPE_MAP");
    expect(start, "GOOGLE_SUB_TYPE_MAP not found").toBeGreaterThan(-1);
    // End at the object's own closing brace rather than at whatever declaration
    // happens to follow it: a negative indexOf would silently swallow the rest
    // of the file and inflate the table.
    const end = source.indexOf("\n};", start);
    expect(end, "GOOGLE_SUB_TYPE_MAP is unterminated").toBeGreaterThan(start);
    const block = source.slice(start, end);
    const names = new Map<string, string>();
    const codes = new Set<string>();
    for (const line of block.split("\n")) {
      const entry = line.match(/^\s*(\d+):\s*"[^"]*",/);
      if (!entry) continue;
      codes.add(entry[1]);
      const named = line.match(/\/\/\s*([A-Z][A-Z_]+)/);
      // Every entry must name itself, or the table's names go unchecked.
      expect(named, `code ${entry[1]} has no name comment`).not.toBeNull();
      if (named) names.set(entry[1], named[1]);
    }
    expect(names.size).toBe(codes.size);
    return names;
  })();

  it("names every Google notification the way the store numbers it", () => {
    for (const row of mapping.stores.google.mappings) {
      if (!row.storeNotificationCode) continue;
      const expected = googleCodeNames.get(row.storeNotificationCode);
      expect(
        expected,
        `code ${row.storeNotificationCode} is not in the map`,
      ).toBeDefined();
      expect(row.storeNotification, `code ${row.storeNotificationCode}`).toBe(
        expected,
      );
    }
  });

  it("gives every Google notification code a row", () => {
    const covered = new Set(
      mapping.stores.google.mappings.map((row) => row.storeNotificationCode),
    );
    for (const code of googleCodeNames.keys()) {
      expect(covered, `code ${code} has no row`).toContain(code);
    }
  });

  it("names only Apple notifications the receiver recognises", () => {
    // A row for a type the receiver rejects would document a mapping that never
    // happens — and with `event: null` it would look like a deliberate no-op.
    for (const row of mapping.stores.apple.mappings) {
      expect(
        mapAppleNotificationType(
          row.storeNotification as never,
          (row.storeSubtype ?? null) as never,
        ),
        `${row.storeNotification} is not handled by the receiver`,
      ).not.toBeNull();
    }
  });

  // Both sides of the previous check came from the same object, so it could
  // never fail. Coverage has to be measured against the implementation's own
  // inventory, which is what the Google code check already does.
  const appleHandledTypes = (() => {
    const source = readFileSync(
      fileURLToPath(new URL("../webhooks/shared.ts", import.meta.url)),
      "utf8",
    );
    const start = source.indexOf("function mapAppleNotificationType");
    const end = source.indexOf("\n}", start);
    const body = source.slice(start, end);
    return new Set(
      [...body.matchAll(/case "([A-Z_]+)":/g)].map((match) => match[1]),
    );
  })();

  it("gives every Apple notification the receiver handles a row", () => {
    expect(appleHandledTypes.size).toBeGreaterThan(10);
    const covered = new Set(
      mapping.stores.apple.mappings.map((row) => row.storeNotification),
    );
    for (const type of appleHandledTypes) {
      expect(covered, `${type} has no row`).toContain(type);
    }
  });

  it.each(cases)("%s", (_label, store, row) => {
    expect(emittedFor(store, row)).toBe(row.event);
  });
});

kit/server/api/commerce/graphql.ts:
// The portable GraphQL binding: one POST endpoint executing the generated
// schema projection. Resolvers only adapt transport — auth context, variable
// unpacking, and error mapping — and delegate to the shared handlers.

import {
  buildSchema,
  execute,
  GraphQLError,
  Kind,
  OperationTypeNode,
  parse,
  validate,
  type DocumentNode,
  type OperationDefinitionNode,
  type SelectionSetNode,
} from "graphql";
import HTTP_BINDING from "openiap-commerce-protocol/generated/bindings/http-binding.json";
import operationsSdl from "openiap-commerce-protocol/generated/bindings/operations-sdl.json";

import { ProtocolOperationError } from "./errors";
import * as handlers from "./handlers";
import type { ProtocolContext } from "./handlers";
import { validateOperationInput } from "./validation";

// The projection is generated from the SDL; serving anything else would fail
// the introspection-agreement rule in SPEC.md 7.
export const commerceGraphqlSchema = buildSchema(operationsSdl.sdl);

// Bounds chosen far above the canonical documents and the standard
// introspection query, far below anything abusive.
const MAX_QUERY_DEPTH = 20;
const MAX_FIELD_NODES = 1_000;

type CommerceRole = "none" | "verification" | "server";

export interface GraphqlRequestContext {
  role: CommerceRole | null;
  apiKey?: string;
  requestIp?: string;
}

const operationAuth = new Map(
  HTTP_BINDING.operations.map((operation) => [operation.name, operation.auth]),
);

function assertRole(operationName: string, context: GraphqlRequestContext) {
  const required = operationAuth.get(operationName);
  if (required === "none" || required === undefined) return;
  if (context.role === null) {
    throw new GraphQLError("A credential is required", {
      extensions: { code: "UNAUTHORIZED" },
    });
  }
  if (required === "server" && context.role !== "server") {
    throw new GraphQLError("This operation requires the server role", {
      extensions: { code: "FORBIDDEN" },
    });
  }
}

function protocolContext(context: GraphqlRequestContext): ProtocolContext {
  if (!context.apiKey) {
    throw new GraphQLError("A credential is required", {
      extensions: { code: "UNAUTHORIZED" },
    });
  }
  return { apiKey: context.apiKey, requestIp: context.requestIp };
}

async function resolve<T>(
  operationName: string,
  context: GraphqlRequestContext,
  input: unknown,
  run: (input: never) => Promise<T> | T,
): Promise<T> {
  assertRole(operationName, context);
  // Server-role authoritative auth already ran in executeCommerceGraphql,
  // BEFORE execute() — graphql-js coerces variables before any resolver, so
  // an auth check here would come after input validation (SPEC.md 5 forbids
  // that ordering for server operations).
  // The same generated JSON Schema the REST binding enforces. GraphQL's own
  // coercion does not check the custom scalars' patterns and bounds, so
  // without this the bindings would disagree on CONTENT bounds (SPEC.md 8).
  // Structural asymmetry is different and documented: REST ignores an unknown
  // input member (SPEC.md 6) while GraphQL rejects one at coercion (SPEC.md 7).
  if (input !== undefined) {
    const invalid = validateOperationInput(operationName, input);
    if (invalid) {
      throw new GraphQLError(invalid, {
        extensions: { code: "INVALID_REQUEST" },
      });
    }
  }
  try {
    return await run(input as never);
  } catch (error) {
    if (error instanceof GraphQLError) throw error;
    if (error instanceof ProtocolOperationError) {
      throw new GraphQLError(error.message, {
        extensions: {
          code: error.code,
          ...(error.retryAfterSec === undefined
            ? {}
            : { retryAfterSec: error.retryAfterSec }),
        },
      });
    }
    throw new GraphQLError("The operation failed", {
      extensions: { code: "INTERNAL_ERROR" },
    });
  }
}

// buildSchema attaches no resolvers, so the root value carries one function
// per operation; nested members resolve off plain handler results.
const rootValue = {
  providerCapabilities: (
    _args: unknown,
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("providerCapabilities", context, undefined, () =>
      handlers.providerCapabilities(),
    ),
  subscriptionStatus: (
    args: { input: { userId: string } },
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("subscriptionStatus", context, args.input, (input) =>
      handlers.subscriptionStatus(protocolContext(context), input),
    ),
  entitlements: (
    args: { input: { userId: string } },
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("entitlements", context, args.input, (input) =>
      handlers.entitlements(protocolContext(context), input),
    ),
  verifyPurchase: (
    args: { input: Parameters<typeof handlers.verifyPurchase>[1] },
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("verifyPurchase", context, args.input, (input) =>
      handlers.verifyPurchase(protocolContext(context), input),
    ),
  bindPurchase: (
    args: { input: Parameters<typeof handlers.bindPurchase>[1] },
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("bindPurchase", context, args.input, (input) =>
      handlers.bindPurchase(protocolContext(context), input),
    ),
  eraseUser: (
    args: { input: { userId: string } },
    context: GraphqlRequestContext,
  ): Promise<unknown> =>
    resolve("eraseUser", context, args.input, (input) =>
      handlers.eraseUser(protocolContext(context), input),
    ),
};

function boundsError(document: DocumentNode): string | null {
  const operations = document.definitions.filter(
    (definition): definition is OperationDefinitionNode =>
      definition.kind === Kind.OPERATION_DEFINITION,
  );
  if (operations.length !== 1) {
    return "Send exactly one operation per request";
  }
  const operation = operations[0];
  if (operation.operation === OperationTypeNode.SUBSCRIPTION) {
    return "The GraphQL binding serves no subscriptions";
  }

  const fragments = new Map<string, SelectionSetNode>();
  for (const definition of document.definitions) {
    if (definition.kind === Kind.FRAGMENT_DEFINITION) {
      fragments.set(definition.name.value, definition.selectionSet);
    }
  }

  // Count actual selections after expanding inline and named fragments, so an
  // aliased amplification hidden inside `... on Query { a b c }` or a fragment
  // spread is counted at the level it really executes. Crucially the walk
  // ABORTS the instant any bound is exceeded, and a total node-visit budget
  // hard-caps the work: a fragment DAG (f0 spreads f1 twice, f1 spreads f2
  // twice, …) expands exponentially, so fully expanding it before checking is
  // itself the DoS. Early exit plus the visit budget keep the cost linear in
  // the budget regardless of how the DAG is shaped.
  const MAX_VISITS = 10_000;
  let fields = 0;
  let rootFields = 0;
  let visits = 0;
  const seenFragments = new Set<string>();
  const walk = (
    selectionSet: SelectionSetNode | undefined,
    depth: number,
  ): string | null => {
    if (depth > MAX_QUERY_DEPTH) return "Query is too deep";
    if (!selectionSet?.selections) return null;
    for (const selection of selectionSet.selections) {
      if (++visits > MAX_VISITS) return "Query is too complex";
      if (selection.kind === Kind.FIELD) {
        fields += 1;
        if (fields > MAX_FIELD_NODES) return "Query selects too many fields";
        if (depth === 1) {
          rootFields += 1;
          if (rootFields > 1) {
            return "Send exactly one operation field per request";
          }
        }
        const nested = walk(selection.selectionSet, depth + 1);
        if (nested) return nested;
      } else if (selection.kind === Kind.INLINE_FRAGMENT) {
        // An inline fragment does not add a level: its members select on the
        // same object at the current depth.
        const nested = walk(selection.selectionSet, depth);
        if (nested) return nested;
      } else {
        const name = selection.name.value;
        if (seenFragments.has(name)) continue; // cycle guard
        seenFragments.add(name);
        const nested = walk(fragments.get(name), depth);
        seenFragments.delete(name);
        if (nested) return nested;
      }
    }
    return null;
  };
  const exceeded = walk(operation.selectionSet, 1);
  if (exceeded) return exceeded;

  // A field-free operation (only fragment spreads that resolve to nothing) is
  // not one operation field.
  if (rootFields !== 1) return "Send exactly one operation field per request";
  return null;
}

function errorPayload(code: string, message: string) {
  return { errors: [{ message, extensions: { code } }] };
}

// graphql-js parse/validation/coercion messages embed the submitted document
// and variable VALUES verbatim — a coercion error on VerifyPurchaseInput
// echoes the whole JWS back to an unauthenticated caller, which SPEC.md 8
// forbids (no store evidence or signed payloads in messages). Request-level
// failures therefore answer with fixed text; the caller reproduces the detail
// locally against the published projection.
const PARSE_MESSAGE = "The GraphQL document does not parse";
const VALIDATION_MESSAGE = "The GraphQL document is not valid for the schema";
const COERCION_MESSAGE =
  "The request variables are not valid for the operation";

/**
 * The single root operation field, resolved through fragment spreads. Only
 * called after boundsError enforced exactly one operation with exactly one
 * root field, so the first field found is the operation being invoked.
 */
function rootFieldName(document: DocumentNode): string | null {
  const operations = document.definitions.filter(
    (definition): definition is OperationDefinitionNode =>
      definition.kind === Kind.OPERATION_DEFINITION,
  );
  const operation = operations[0];
  if (!operation) return null;
  const fragments = new Map<string, SelectionSetNode>();
  for (const definition of document.definitions) {
    if (definition.kind === Kind.FRAGMENT_DEFINITION) {
      fragments.set(definition.name.value, definition.selectionSet);
    }
  }
  const seen = new Set<string>();
  const find = (selectionSet?: SelectionSetNode): string | null => {
    for (const selection of selectionSet?.selections ?? []) {
      if (selection.kind === Kind.FIELD) return selection.name.value;
      if (selection.kind === Kind.INLINE_FRAGMENT) {
        const found = find(selection.selectionSet);
        if (found) return found;
      } else if (selection.kind === Kind.FRAGMENT_SPREAD) {
        const name = selection.name.value;
        if (seen.has(name)) continue;
        seen.add(name);
        const found = find(fragments.get(name));
        if (found) return found;
      }
    }
    return null;
  };
  return find(operation.selectionSet);
}

/**
 * Executes one GraphQL request against the projection. Returns the JSON body
 * and status; operation failures are 200 responses whose errors carry the
 * protocol code, per SPEC.md 7.
 */
export async function executeCommerceGraphql(
  payload: unknown,
  context: GraphqlRequestContext,
): Promise<{ status: 200; body: unknown }> {
  // SPEC.md 7: the GraphQL binding answers with HTTP 200 and the code in
  // errors[].extensions.code for every failure, including request-level ones.
  if (payload === null || typeof payload !== "object") {
    return {
      status: 200,
      body: errorPayload("INVALID_REQUEST", "Request body is not JSON"),
    };
  }
  const { query, variables, operationName } = payload as {
    query?: unknown;
    variables?: unknown;
    operationName?: unknown;
  };
  if (typeof query !== "string" || query.length === 0) {
    return {
      status: 200,
      body: errorPayload("INVALID_REQUEST", "query is required"),
    };
  }

  let document: DocumentNode;
  try {
    document = parse(query);
  } catch {
    // A syntax message can echo document text, and evidence pasted as a
    // literal is document text — fixed message only.
    return {
      status: 200,
      body: errorPayload("INVALID_REQUEST", PARSE_MESSAGE),
    };
  }

  const bounds = boundsError(document);
  if (bounds) {
    return { status: 200, body: errorPayload("INVALID_REQUEST", bounds) };
  }

  const validationErrors = validate(commerceGraphqlSchema, document);
  if (validationErrors.length) {
    // Literal-coercion validation errors echo the submitted value.
    return {
      status: 200,
      body: errorPayload("INVALID_REQUEST", VALIDATION_MESSAGE),
    };
  }

  // SPEC.md 5: server-role authorization precedes input validation, and
  // graphql-js coerces variables BEFORE any resolver runs — so the resolver is
  // too late. Authorize here, after transport-shape checks (parse, bounds,
  // validate) and before execute(), where coercion happens.
  const operationField = rootFieldName(document);
  if (operationField && operationAuth.get(operationField) === "server") {
    if (context.role === null) {
      return {
        status: 200,
        body: errorPayload("UNAUTHORIZED", "A credential is required"),
      };
    }
    if (context.role !== "server") {
      return {
        status: 200,
        body: errorPayload(
          "FORBIDDEN",
          "This operation requires the server role",
        ),
      };
    }
    try {
      await handlers.assertServerCredential({
        apiKey: context.apiKey ?? "",
        requestIp: context.requestIp,
      });
    } catch (error) {
      if (error instanceof ProtocolOperationError) {
        return { status: 200, body: errorPayload(error.code, error.message) };
      }
      return {
        status: 200,
        body: errorPayload("INTERNAL_ERROR", "The operation failed"),
      };
    }
  }

  const result = await execute({
    schema: commerceGraphqlSchema,
    document,
    rootValue,
    contextValue: context,
    variableValues:
      variables && typeof variables === "object"
        ? (variables as Record<string, unknown>)
        : undefined,
    operationName: typeof operationName === "string" ? operationName : null,
  });

  return {
    status: 200,
    body: {
      ...(result.data === undefined ? {} : { data: result.data }),
      ...(result.errors?.length
        ? {
            errors: result.errors.map((error) => {
              const coded = typeof error.extensions?.code === "string";
              return {
                // A codeless error here is graphql-js variable coercion,
                // whose message echoes the submitted value — replace it.
                // Resolver-raised errors carry a code and a safe message.
                message: coded ? error.message : COERCION_MESSAGE,
                extensions: {
                  code: coded
                    ? (error.extensions.code as string)
                    : "INVALID_REQUEST",
                  ...(typeof error.extensions?.retryAfterSec === "number"
                    ? { retryAfterSec: error.extensions.retryAfterSec }
                    : {}),
                },
              };
            }),
          }
        : {}),
    },
  };
}

